(function(){let last="",at=0;window.speakOnce=function(text,lang){if(!text||!("speechSynthesis"in window))return;let n=Date.now();if(text===last&&n-at<1800)return;last=text;at=n;speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(String(text));u.lang=lang||(navigator.language||"hi-IN");speechSynthesis.speak(u)};function f(){document.documentElement.style.overflowX="hidden";document.body.style.overflowX="hidden"}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",f);else f()})();
;

(function(){
  const KEY='pathshala_exam_results_v80';
  const WRONG='pathshala_wrong_questions_v80';
  const getJSON=(k,d)=>{try{return JSON.parse(localStorage.getItem(k)||JSON.stringify(d))}catch(e){return d}};
  const put=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch(e){}};
  function el(id){return document.getElementById(id)}
  function esc(x){return String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
  function inject(){
    const panel=el('examCenter'); if(!panel||el('v80ExamTools'))return;
    const box=document.createElement('div');box.id='v80ExamTools';box.className='panel';
    box.innerHTML='<h2>📊 मेरी प्रगति</h2><div id="v80Stats" class="v80-grid"></div><div style="margin-top:10px;display:grid;gap:8px"><button class="v80-btn" onclick="v80ShowHistory()">📈 परीक्षा परिणाम देखें</button><button class="v80-btn" onclick="v80ShowWrong()">🔁 गलत सवालों की प्रैक्टिस</button></div><div id="v80Extra"></div>';
    panel.appendChild(box); updateStats();
  }
  function updateStats(){
    const r=getJSON(KEY,[]), w=getJSON(WRONG,[]);
    const tests=r.length, correct=r.reduce((a,x)=>a+(+x.score||0),0), total=r.reduce((a,x)=>a+(+x.total||0),0);
    const pct=total?Math.round(correct/total*100):0;
    const stats=el('v80Stats'); if(!stats)return;
    stats.innerHTML='<div class="v80-card"><div class="v80-stat">'+tests+'</div><div class="v80-small">कुल परीक्षाएँ</div></div>'+
      '<div class="v80-card"><div class="v80-stat">'+pct+'%</div><div class="v80-small">औसत सही</div></div>'+
      '<div class="v80-card"><div class="v80-stat">'+w.length+'</div><div class="v80-small">गलत सवाल</div></div>'+
      '<div class="v80-card"><div class="v80-stat">'+correct+'/'+total+'</div><div class="v80-small">सही उत्तर</div></div>';
  }
  window.v80ShowHistory=function(){
    const r=getJSON(KEY,[]), box=el('v80Extra'); if(!box)return;
    if(!r.length){box.innerHTML='<div class="v80-card" style="margin-top:10px">अभी कोई परीक्षा परिणाम नहीं है। पहले एक परीक्षा दीजिए।</div>';return}
    box.innerHTML='<div class="v80-card" style="margin-top:10px"><h3>📈 हाल के परिणाम</h3>'+r.slice(0,10).map(x=>{
      const d=new Date(x.date); const date=isNaN(d)?'':d.toLocaleDateString('hi-IN');
      return '<div class="v80-wrong-item"><b>कक्षा '+esc(x.classId)+' • '+esc(x.subjectId)+'</b><br>⭐ '+esc(x.score)+' / '+esc(x.total)+' सही <span class="v80-small">• '+date+'</span></div>'
    }).join('')+'</div>';
  };
  window.v80ShowWrong=function(){
    const w=getJSON(WRONG,[]), box=el('v80Extra'); if(!box)return;
    if(!w.length){box.innerHTML='<div class="v80-card" style="margin-top:10px">🎉 अभी कोई गलत सवाल सेव नहीं है।</div>';return}
    box.innerHTML='<div class="v80-card" style="margin-top:10px"><h3>🔁 दोबारा अभ्यास करें</h3><p class="v80-small">पिछली परीक्षाओं में गलत हुए सवाल।</p>'+w.slice(0,20).map((x,i)=>
      '<div class="v80-wrong-item"><div class="v80-wrong-q">'+(i+1)+'. '+esc(x.q)+'</div><div class="v80-wrong-a">सही उत्तर: <b>'+esc(x.correct)+'</b></div><div class="v80-small">कक्षा '+esc(x.classId)+' • '+esc(x.subjectId)+'</div></div>'
    ).join('')+'</div>';
  };
  const oldAnswer=window.examAnswer;
  if(typeof oldAnswer==='function'){
    window.examAnswer=function(btn,opt){
      const q=window.__pathshalaExamCurrentQuestion;
      if(q && opt!==q.correct){
        const w=getJSON(WRONG,[]);
        const item={q:q.q,correct:q.correct,classId:window.__pathshalaExamClass,subjectId:window.__pathshalaExamSubject};
        if(!w.some(x=>x.q===item.q&&x.classId===item.classId&&x.subjectId===item.subjectId))w.unshift(item);
        put(WRONG,w.slice(0,100));
      }
      return oldAnswer(btn,opt);
    };
  }
  const oldOpen=window.openPage;
  if(typeof oldOpen==='function'){
    window.openPage=function(id,fromPop){const r=oldOpen(id,fromPop);if(id==='examCenter')setTimeout(inject,0);return r};
  }
  const obs=new MutationObserver(()=>{if(el('examCenter'))inject()});
  if(document.body)obs.observe(document.body,{childList:true});
  document.addEventListener('DOMContentLoaded',inject);
  // Keep current exam question context by observing the displayed question and title.
  setInterval(function(){
    const q=el('examQ'),t=el('examTitle');if(q&&t&&q.textContent){
      const txt=q.textContent.replace(/^\d+\.\s*/,'');
      const parts=t.textContent.split('•');
      let found=null;
      try{
        const c=(parts[0]||'').replace('कक्षा','').trim();
        const subj=(parts[1]||'').trim();
        const ss=Object.keys(STUDY_DATA||{}).find(k=>String(k)===c);
        if(ss){
          const subjects=(STUDY_DATA[ss].subjects||{});
          outer:
          for(const sid of Object.keys(subjects)){
            for(const l of (subjects[sid].lessons||[])){
              for(const qq of (l.quiz||[])){
                if(qq.q===txt){
                  found={...qq};
                  window.__pathshalaExamClass=c;
                  window.__pathshalaExamSubject=sid;
                  break outer;
                }
              }
            }
          }
        }
      }catch(e){}
      window.__pathshalaExamCurrentQuestion=found;
    }
    updateStats();
  },700);
})();

