(function(){
  var done=false;
  function hideSplash(){
    if(done)return; done=true;
    var el=document.getElementById('appSplash'); if(!el)return;
    el.style.opacity='0'; el.style.visibility='hidden';
    setTimeout(function(){ if(el&&el.parentNode)el.parentNode.removeChild(el); },420);
  }
  document.addEventListener('DOMContentLoaded',function(){ setTimeout(hideSplash,150); });
  window.addEventListener('load',function(){ setTimeout(hideSplash,150); });
  setTimeout(hideSplash,1800); // हार्ड fallback — कभी भी हमेशा के लिए न अटके
})();
;

const pageSpeech={onlineStudy:'बात करके ऑनलाइन पढ़ाई। सवाल लिखें या बोलें और पाठशाला से सीखें।',study:'पढ़ाई। अपनी कक्षा चुनें और पाठ सीखें।',adultEducation:'वयस्क शिक्षा। बुनियादी पढ़ना-लिखना सीखें।',write:'लिखने का अभ्यास। कोई विषय चुनें और अक्षर लिखना सीखें।',hindi:'हिंदी। वर्णमाला और पाठ।',english:'English. Letters and Words.',math:'गणित। जोड़, घटाव और पहाड़े।',count:'गिनती। एक से एक हजार तक।',game:'गेम। सवाल सुनें और सही उत्तर चुनें।',story:'कहानियाँ। सुनें और पढ़ें।',practice:'अभ्यास। सही उत्तर चुनें।',examCenter:'परीक्षा केंद्र। कक्षा और विषय चुनकर दस सवाल हल करें।',progress:'मेरी प्रगति। सितारे और उपलब्धियाँ।',updateInfo:'पाठशाला का नया अपडेट। नए सुधार और सुविधाएँ।',links:'लिंक केंद्र। उपयोगी लिंक जोड़ें और बाद में खोलें।',books:'किताब खोजें। किताब का नाम, लेखक या विषय लिखकर खोजें।'};
async function searchBooks(){
  const input=document.getElementById('bookQuery');
  const box=document.getElementById('bookResults');
  if(!input||!box)return;
  const q=(input.value||'').trim();
  if(!q){
    box.innerHTML='<div class="bookEmpty">📚 पहले किताब का नाम, लेखक या विषय लिखें।</div>';
    input.focus(); return;
  }
  const safe=t=>String(t||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const googleSearch='https://books.google.com/books?q='+encodeURIComponent(q);
  const storySearch='https://storyweaver.org.in/en/search?query='+encodeURIComponent(q);
  box.innerHTML='<div class="bookLoading">🔎 <b>किताबें खोजी जा रही हैं…</b><br><small>थोड़ा इंतज़ार करें</small></div>';

  try{
    const url='https://www.googleapis.com/books/v1/volumes?q='+encodeURIComponent(q)+'&maxResults=12&printType=books&orderBy=relevance';
    const controller=new AbortController();
    const timer=setTimeout(()=>controller.abort(),9000);
    const res=await fetch(url,{signal:controller.signal,cache:'no-store'});
    clearTimeout(timer);
    if(!res.ok) throw new Error('Google Books '+res.status);
    const data=await res.json();
    const items=Array.isArray(data.items)?data.items:[];
    if(!items.length) throw new Error('NO_RESULTS');

    box.innerHTML='<div class="bookResultHead"><h2>📚 "'+safe(q)+'" की किताबें</h2><p>'+items.length+' किताबें मिलीं। उपलब्ध होने पर Preview/Read खोलें।</p></div>'+items.map((item)=>{
      const v=item.volumeInfo||{};
      const title=safe(v.title||'बिना नाम की किताब');
      const authors=safe((v.authors||[]).join(', ')||'लेखक उपलब्ध नहीं');
      const desc=safe((v.description||'').replace(/\s+/g,' ').slice(0,180));
      const thumb=v.imageLinks?.thumbnail||v.imageLinks?.smallThumbnail||'';
      const cleanThumb=thumb.replace(/^http:/,'https:');
      const link=v.previewLink||v.infoLink||('https://books.google.com/books?id='+encodeURIComponent(item.id||''));
      return '<article class="bookResultItem">'+
        (cleanThumb?'<img class="bookCover" src="'+safe(cleanThumb)+'" alt="'+title+'" loading="lazy">':'<div class="bookCover bookCoverFallback">📚</div>')+
        '<div class="bookResultInfo"><h3>'+title+'</h3><p class="bookAuthor">✍️ '+authors+'</p>'+
        (desc?'<p class="bookDesc">'+desc+(v.description&&v.description.length>180?'…':'')+'</p>':'')+
        '<a class="bookOpen bookReadBtn" href="'+safe(link)+'" target="_blank" rel="noopener noreferrer">📖 किताब खोलें / Preview</a></div></article>';
    }).join('')+
    '<div class="bookSourceNote">Google Books से परिणाम — कई बार सिर्फ़ झलक (Preview) ही मिलती है, पूरी किताब नहीं। <a href="'+storySearch+'" target="_blank" rel="noopener noreferrer">बच्चों की पूरी मुफ़्त हिंदी कहानियों के लिए StoryWeaver देखें →</a></div>';
  }catch(err){
    box.innerHTML='<div class="bookFallback">'+
      '<div class="bookGoogleIcon">📚</div>'+
      '<h2>किताबें खोजने के लिए तैयार</h2>'+
      '<p>इस फोन/ब्राउज़र में सीधे किताबों की सूची लोड नहीं हो पाई। नीचे से खोजें:</p>'+
      '<a class="bookOpen bookGoogleMain" href="'+storySearch+'" target="_blank" rel="noopener noreferrer">📖 StoryWeaver में "'+safe(q)+'" खोजें (मुफ़्त पूरी किताबें)</a>'+
      '<a class="bookOpen bookGoogleAlt" href="'+googleSearch+'" target="_blank" rel="noopener noreferrer">🔎 Google Books में भी खोजें</a>'+
      '<div class="bookSourceNote">इंटरनेट चालू होना जरूरी है। पूरी किताब तभी पढ़ी जा सकती है जब वह कानूनी रूप से उपलब्ध हो।</div>'+ 
    '</div>';
  }
}
document.addEventListener('DOMContentLoaded',function(){const q=document.getElementById('bookQuery');if(q)q.addEventListener('keydown',function(e){if(e.key==='Enter'){e.preventDefault();searchBooks();}});});

let deferredInstallPrompt=null;
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;const s=document.getElementById('installStatus');if(s)s.textContent='इंस्टॉल करने के लिए तैयार है।'});
window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;const s=document.getElementById('installStatus');if(s)s.textContent='✅ पाठशाला फोन में जुड़ गया।'});
async function installPathshala(){if(deferredInstallPrompt){deferredInstallPrompt.prompt();try{await deferredInstallPrompt.userChoice}catch(e){}deferredInstallPrompt=null;return;}const s=document.getElementById('installStatus');if(s)s.textContent='Chrome के ⋮ मेन्यू में “Add to Home screen” चुनें।';}
let psHistoryReady=false;
function openPage(id,fromPop=false){if(!document.getElementById(id))return;if(id!=='onlineStudy' && typeof stopLiveClassPolling==='function')stopLiveClassPolling();if(!fromPop && history && history.pushState){try{history.pushState({page:id},'',location.pathname+location.search+'#'+id);psHistoryReady=true;}catch(e){}}if(id!=='onlineStudy' && typeof inlineRecording!=='undefined' && inlineRecording){try{stopInlineRecording();}catch(_){} }if('speechSynthesis' in window)window.speechSynthesis.cancel();if(typeof stopBgMusic==='function')stopBgMusic();document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));document.getElementById(id).classList.add('active');document.getElementById('backBtn').classList.remove('hide');scrollTo(0,0);if(typeof storyPlaying!=='undefined')storyPlaying=false;if(id==='english')renderEnglish();if(id==='hindi')renderHindiBook();if(id==='books')document.getElementById('bookQuery')?.focus();if(id==='links')renderPathshalaLinks();if(id==='onlineStudy'){initTutor();renderLiveClassCard();}if(id==='wordKnowledge')renderWordKnowledge();if(id==='settings'){syncSettingsUI(); renderRecordings();}if(id==='progress')refreshProgressUI();if(id==='about')document.getElementById('installStatus')&&(document.getElementById('installStatus').textContent=deferredInstallPrompt?'इंस्टॉल करने के लिए तैयार है।':'ब्राउज़र के ⋮ मेन्यू से Add to Home screen चुन सकते हैं।');if(id==='practice')newPracticeQuestion();if(id==='study'){studyState={view:'classes',classId:null,subjectId:null,lessonId:null,qIndex:0,endlessIndex:0,pageIndex:0};renderStudy()}if(id==='adultEducation'){adultState={view:'subjects',subjectId:null,lessonId:null,qIndex:0};renderAdult()}if(id==='write'){writeState={view:'groups',groupId:null,index:0};renderWrite()}if(id==='story'){storyState={view:'list'};renderStoryScreen()}if(id==='langStudy'){langStudyState={view:'languages',langCode:null,subjectId:null,lessonId:null,qIndex:0};renderLangStudy()}if(id!=='settings')setTimeout(()=>{if(id==='count')speakNumber();else if(id==='english')speakEnglish();else if(id==='math')speakTable();else if(id==='game')speakGame();else if(id!=='story')speakText(pageSpeech[id]||'')},150)}
function goHome(){document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));document.getElementById('home').classList.add('active');document.getElementById('backBtn').classList.add('hide');if(typeof storyPlaying!=='undefined')storyPlaying=false;if('speechSynthesis' in window)window.speechSynthesis.cancel();scrollTo(0,0)}
function handleBack(){const studyScreen=document.getElementById('study');const writeScreen=document.getElementById('write');const storyScreen=document.getElementById('story');if(studyScreen&&studyScreen.classList.contains('active')&&typeof studyState!=='undefined'&&studyState.view!=='classes'){studyGoBack()}else if(writeScreen&&writeScreen.classList.contains('active')&&typeof writeState!=='undefined'&&writeState.view!=='groups'){writeGoBack()}else if(storyScreen&&storyScreen.classList.contains('active')&&typeof storyState!=='undefined'&&storyState.view!=='list'){storyGoBack()}else{goHome()}}
window.addEventListener('popstate',e=>{
  const page=e.state&&e.state.page;
  /* फ़ोन के असली Back बटन/gesture पर भी वही एक-कदम-पीछे लॉजिक चलाएँ जो अंदर वाला "← वापस" बटन चलाता है,
     ताकि study/write/story की स्थिति रीसेट न हो और सवाल बार-बार न दोहराए। */
  const studyScreen=document.getElementById('study');
  const writeScreen=document.getElementById('write');
  const storyScreen=document.getElementById('story');
  let handledInternally=false;
  if(studyScreen&&studyScreen.classList.contains('active')&&typeof studyState!=='undefined'&&studyState.view!=='classes'){studyGoBack();handledInternally=true;}
  else if(writeScreen&&writeScreen.classList.contains('active')&&typeof writeState!=='undefined'&&writeState.view!=='groups'){writeGoBack();handledInternally=true;}
  else if(storyScreen&&storyScreen.classList.contains('active')&&typeof storyState!=='undefined'&&storyState.view!=='list'){storyGoBack();handledInternally=true;}
  if(handledInternally){
    if(history&&history.pushState){try{history.pushState({page:page||'study'},'',location.href);}catch(e){}}
    return;
  }
  if(page&&document.getElementById(page))openPage(page,true);else goHome();
});
if(history && history.replaceState && !history.state){try{history.replaceState({page:'home'},'',location.pathname+location.search+'#home');}catch(e){}}
