let hci=0;
function renderHindiConsonants(){
  document.getElementById('hindiConsGrid').innerHTML=hindiConsonants.map((x,i)=>`<button class="abc" onclick="selectHindiCons(${i})"><strong>${x[0]}</strong><span class="pic">${x[2]}</span><small>${x[1]}</small></button>`).join('');
  const x=hindiConsonants[hci];
  document.getElementById('hindiConsBig').textContent=x[0];
  document.getElementById('hindiConsWord').textContent=x[0]+' — '+x[1];
}
function selectHindiCons(i){hci=i;renderHindiConsonants();speakHindiConsonant()}
function hindiConsMove(d){
  const next=hci+d;
  if(next<0){speakText('यह पहला व्यंजन है।');return;}
  if(next>=hindiConsonants.length){speakText('आपने सभी व्यंजन देख लिए! अब हिंदी के पाठ पढ़ने के लिए "पढ़ाई" में जाएँ।');return;}
  hci=next;renderHindiConsonants();speakHindiConsonant();
}
function speakHindiConsonant(){const x=hindiConsonants[hci];speakText(x[0]+' से '+x[1])}
// छोटे (3 अक्षर वाले) असली शब्द — अक्षर पहचानने के बाद अब उन्हें जोड़कर शब्द पढ़ना सीखें
const CVC_WORDS=[
 ['CAT','बिल्ली','🐱'],['DOG','कुत्ता','🐶'],['SUN','सूरज','☀️'],['BAT','चमगादड़/बल्ला','🦇'],
 ['CUP','कप','☕'],['BAG','थैला','🎒'],['BED','बिस्तर','🛏️'],['BUS','बस','🚌'],
 ['HAT','टोपी','🎩'],['PIG','सुअर','🐷'],['RUN','दौड़ना','🏃'],['SIT','बैठना','🪑'],
 ['BIG','बड़ा','📏'],['RED','लाल','🔴'],['PEN','कलम','🖊️'],['TOP','ऊपर/लट्टू','🔝'],
 ['MAP','नक्शा','🗺️'],['JAM','जैम','🍯'],['WEB','जाला','🕸️'],['FOX','लोमड़ी','🦊'],
];
let cvcIndex=0;
function renderCVC(){
  const x=CVC_WORDS[cvcIndex]; if(!x)return;
  const set=(id,val)=>{const e=document.getElementById(id); if(e) e.textContent=val;};
  set('cvcEmoji',x[2]);
  set('cvcSpelled',x[0].split('').join(' - '));
  set('cvcWord',x[0]);
  set('cvcMeaning',x[0]+' = '+x[1]);
  set('cvcPageNum','शब्द '+(cvcIndex+1)+' / '+CVC_WORDS.length);
}
function cvcMove(d){
  const next=cvcIndex+d;
  if(next<0){speakText('यह पहला शब्द है।',null);return;}
  if(next>=CVC_WORDS.length){speakText('आपने सभी शब्द पढ़ लिए! बहुत बढ़िया।',null);return;}
  cvcIndex=next; renderCVC(); speakCVC();
}
function speakCVC(){
  const x=CVC_WORDS[cvcIndex]; if(!x)return;
  speakText(x[0].split('').join('... ')+'... '+x[0],'en-US');
}
