function renderABCDBook(){} // असली काम अब नए 500+ सिस्टम (bookRender) से होता है — यह सिर्फ़ जल्दी लोड होने वाली जगह बचाने के लिए है
// ===== ABCD क्विज़ — बच्चा खुद जाँच सके कि उसने अक्षर पहचानना सीखा या नहीं =====
let abcdQuizState={score:0,qIndex:0,total:8,current:null,answered:false};
function abcdQuizPickLetters(n){
  const letters=[...new Set(ABCD_BOOK.slice(0,26).map(x=>x[0]))];
  const picked=[];
  while(picked.length<n && picked.length<letters.length){
    const l=letters[Math.floor(Math.random()*letters.length)];
    if(!picked.includes(l)) picked.push(l);
  }
  return picked;
}
window.abcdQuizStart=function(){
  abcdQuizState={score:0,qIndex:0,total:8,current:null,answered:false};
  document.getElementById('abcdBookPanel').style.display='none';
  document.getElementById('abcdQuizPanel').style.display='block';
  document.getElementById('abcdQuizDone').style.display='none';
  abcdQuizNext();
};
function abcdQuizNext(){
  if(abcdQuizState.qIndex>=abcdQuizState.total){ abcdQuizEnd(); return; }
  const entry=ABCD_BOOK[Math.floor(Math.random()*26)]; // राउंड 1 के 26 शब्दों में से एक
  const wrongLetters=abcdQuizPickLetters(4).filter(l=>l!==entry[0]).slice(0,3);
  const options=[entry[0],...wrongLetters].sort(()=>Math.random()-0.5);
  abcdQuizState.current={entry,correct:entry[0]};
  abcdQuizState.answered=false;
  document.getElementById('abcdQuizEmoji').textContent=entry[3];
  document.getElementById('abcdQuizProgress').textContent='सवाल '+(abcdQuizState.qIndex+1)+' / '+abcdQuizState.total+' • स्कोर: '+abcdQuizState.score;
  document.getElementById('abcdQuizFeedback').textContent='';
  document.getElementById('abcdQuizOptions').innerHTML=options.map(o=>`<button onclick="abcdQuizAnswer('${o}')">${o}</button>`).join('');
  speakText('यह किस अक्षर से शुरू होता है?');
}
window.abcdQuizAnswer=function(letter){
  if(abcdQuizState.answered) return;
  abcdQuizState.answered=true;
  const fb=document.getElementById('abcdQuizFeedback');
  const entry=abcdQuizState.current.entry;
  if(letter===abcdQuizState.current.correct){
    abcdQuizState.score++;
    fb.style.color='#0f9d58';
    fb.textContent='🎉 सही! '+entry[0]+' for '+entry[1]+' ('+entry[2]+')';
    speakText('बहुत बढ़िया! सही उत्तर है। '+entry[0]+' for '+entry[1],'en-US');
  } else {
    fb.style.color='#c0392b';
    fb.textContent='सही उत्तर था: '+entry[0]+' for '+entry[1]+' ('+entry[2]+')';
    speakText('सही उत्तर है '+entry[0]+' for '+entry[1],'en-US');
  }
  abcdQuizState.qIndex++;
  setTimeout(abcdQuizNext,1600);
};
function abcdQuizEnd(){
  document.getElementById('abcdQuizQ').textContent='🏁 क्विज़ खत्म!';
  document.getElementById('abcdQuizEmoji').textContent='🏆';
  document.getElementById('abcdQuizOptions').innerHTML='';
  document.getElementById('abcdQuizProgress').textContent='आपका स्कोर: '+abcdQuizState.score+' / '+abcdQuizState.total;
  document.getElementById('abcdQuizFeedback').textContent='';
  document.getElementById('abcdQuizDone').style.display='block';
  speakText('क्विज़ खत्म हुई! आपका स्कोर है '+abcdQuizState.score+' में से '+abcdQuizState.total+'।');
  if(typeof addStar==='function' && abcdQuizState.score>=Math.ceil(abcdQuizState.total*0.6)) addStar();
}
function renderFullAlphabet(){
  const box=document.getElementById('fullAlphabetGrid');
  if(!box)return;
  box.innerHTML=eng.map((x,i)=>`<button class="abc" onclick="selectEnglish(${i})" aria-label="${x[0]} for ${x[1]}"><strong>${x[0]}<br><span style="font-size:18px">${x[0].toLowerCase()}</span></strong><span class="pic">${x[2]}</span><small>${x[0]} for ${x[1]}</small></button>`).join('');
}
function renderEnglish(){renderFullAlphabet();renderABCDBook();renderCVC();document.getElementById('abcGrid').innerHTML=eng.map((x,i)=>`<button class="abc" onclick="selectEnglish(${i})"><strong>${x[0]}</strong><span class="pic">${x[2]}</span><small>${x[1]}</small></button>`).join('');let x=eng[ei];document.getElementById('engLetter').textContent=x[0];document.getElementById('engWord').textContent=x[0]+' for '+x[1]}
function selectEnglish(i){ei=i;renderEnglish();speakEnglish()}
function englishMove(d){
  const next=ei+d;
  if(next<0){speakText('यह वर्णमाला का पहला अक्षर है।');return;}
  if(next>=eng.length){speakText('आपने A से Z तक पूरी वर्णमाला देख ली! अब "ABCD की किताब" या "पढ़ाई" में आगे पढ़ें।');return;}
  ei=next;renderEnglish();speakEnglish();
}
