function renderNumber(){document.getElementById('num').textContent=num;document.getElementById('numWord').textContent=numberWord(num)}function moveNumber(d){num=Math.max(1,Math.min(1000,num+d));renderNumber();speakNumber()}function speakNumber(){speakText(num+' — '+numberWord(num))}
let score=0; try{ score=parseInt(localStorage.getItem('pathshalaStars')||'0',10)||0; }catch(e){ score=0; }
function studyDoneCount(){return Object.keys(studyProgress()).length}
function writeDoneCount(){return Object.keys(writeProgress()).length}
function todayStr(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function getStreak(){try{return JSON.parse(localStorage.getItem('pathshalaStreak')||'{"lastDate":"","count":0}')}catch(e){return{lastDate:'',count:0}}}
function bumpStreak(){
  const today=todayStr();
  const st=getStreak();
  if(st.lastDate===today)return st;
  const y=new Date();y.setDate(y.getDate()-1);
  const yStr=y.getFullYear()+'-'+String(y.getMonth()+1).padStart(2,'0')+'-'+String(y.getDate()).padStart(2,'0');
  st.count=(st.lastDate===yStr)?st.count+1:1;
  st.lastDate=today;
  localStorage.setItem('pathshalaStreak',JSON.stringify(st));
  return st;
}
function renderStreakUI(){
  const st=getStreak();
  const badge=document.getElementById('streakBadge');
  if(badge){
    if(st.count>0){badge.style.display='flex';badge.innerHTML='🔥 <b>'+st.count+'</b> दिन लगातार पढ़ाई!';}
    else{badge.style.display='none';}
  }
  const line=document.getElementById('progressStreak');
  if(line)line.textContent=st.count>0?('🔥 '+st.count+' दिन लगातार पढ़ाई का सिलसिला!'):'🔥 आज से पढ़ाई शुरू करें और सिलसिला बनाएँ!';
}
function addStar(){score++;localStorage.setItem('pathshalaStars',String(score));bumpStreak();renderStreakUI();refreshProgressUI()}
function refreshProgressUI(){const st=document.getElementById('stars');if(st)st.textContent='⭐ '+score;const d=document.getElementById('progressDetails');if(d)d.innerHTML='📚 पाठ पूरे: '+studyDoneCount()+'<br>✍️ लिखने के अभ्यास: '+writeDoneCount()+'<br>📖 कहानी पढ़ाई: '+(localStorage.getItem('pathshala_story_last_read')||'अभी कोई पूरी नहीं')+'<br>📍 आखिरी कहानी: '+(Number(localStorage.getItem('pathshala_story_page')||0)+1)+' / 500 • '+(localStorage.getItem('pathshala_story_read_pct')||'0')+'% तक<br>⭐ कुल सितारे: '+score;renderStreakUI();}
function resetProgress(){if(!confirm('क्या पूरी प्रगति रीसेट करनी है?'))return;localStorage.removeItem('pathshalaProgress');localStorage.removeItem('pathshalaWritingProgress');localStorage.removeItem('pathshalaStars');localStorage.removeItem('pathshala_story_read_pct');localStorage.removeItem('pathshala_story_read_chars');localStorage.removeItem('pathshala_story_last_read');score=0;refreshProgressUI();document.getElementById('progressText').textContent='प्रगति रीसेट हो गई।';}

function shuffleOptions(correct){
  const set=new Set([correct]);
  let guard=0;
  while(set.size<4 && guard<50){
    guard++;
    const delta=Math.floor(Math.random()*7)-3;
    const cand=correct+delta;
    if(cand>0 && cand!==correct) set.add(cand);
  }
  const arr=Array.from(set);
  for(let i=arr.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));const t=arr[i];arr[i]=arr[j];arr[j]=t;}
  return arr;
}

let practiceState={a:5,b:3};
function newPracticeQuestion(){
  practiceState.a=Math.floor(Math.random()*9)+1;
  practiceState.b=Math.floor(Math.random()*9)+1;
  const correct=practiceState.a+practiceState.b;
  const qEl=document.getElementById('practiceQ');if(qEl)qEl.textContent=practiceState.a+' + '+practiceState.b+' = ?';
  const opts=shuffleOptions(correct);
  const btns=document.querySelectorAll('#practice .answers button');
  opts.forEach((o,i)=>{if(btns[i]){btns[i].textContent=o;btns[i].onclick=function(){practiceAnswer(o)};}});
  const res=document.getElementById('practiceResult');if(res)res.textContent='';
}
function practiceAnswer(val){
  const correct=practiceState.a+practiceState.b;
  const res=document.getElementById('practiceResult');
  if(val===correct){
    addStar();
    if(res)res.textContent='🎉 बहुत बढ़िया! सही उत्तर '+correct+' है।';
    const st=document.getElementById('stars');if(st)st.textContent='⭐ '+score;
    const pt=document.getElementById('progressText');if(pt)pt.textContent='अभ्यास में सही उत्तर मिला।';
    speakText('बहुत बढ़िया! सही उत्तर है।',null,()=>setTimeout(newPracticeQuestion,900));
  }else{
    if(res)res.textContent='फिर से कोशिश करें।';
    speakText('फिर से कोशिश करें।');
  }
}
renderTables();renderHindi();renderHindiConsonants();renderEnglish();renderNumber();newPracticeQuestion();refreshProgressUI();

