function dailyDateKey(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function dailyDayIndex(){const base=new Date(2026,0,1),now=new Date();return Math.max(0,Math.floor((new Date(now.getFullYear(),now.getMonth(),now.getDate())-base)/86400000))}
function dailyKey(classId,subject){return `pathshalaDaily-${classId}-${subject}-${dailyDateKey()}`}
function dailyCompleted(classId,subject){try{return localStorage.getItem(dailyKey(classId,subject))==='1'}catch(e){return false}}
function dailySaveCompleted(classId,subject){try{localStorage.setItem(dailyKey(classId,subject),'1')}catch(e){}}
function endlessKey(){return 'pathshalaEndlessCounter'}
function endlessCounter(){try{return Number(localStorage.getItem(endlessKey())||0)}catch(e){return 0}}
function endlessSaveCounter(n){try{localStorage.setItem(endlessKey(),String(n))}catch(e){}}
function endlessSubjectFor(classId){
  const map={hindi:'hindi',english:'english',math:'math',science:'science',gk:'gk',computer:'computer',life:'life',environment:'environment'};
  return map;
}
function endlessMakeLesson(classId, subject, n){
  const pool=ENDLESS_TOPICS[subject]||ENDLESS_TOPICS.gk;
  const t=pool[n%pool.length];
  const examples={hindi:['घर','पानी','किताब','पेड़','खेल','सूरज','दोस्त','स्कूल','फल','फूल'],english:['book','school','water','tree','friend','sun','home','game','fruit','flower'],math:['2','5','10','20','30','50','100','200','500','1000'],science:['पौधा','पानी','हवा','सूर्य','पृथ्वी','चाँद','बारिश','जानवर','बीज','प्रकाश'],gk:['भारत','पृथ्वी','नदी','पहाड़','समुद्र','सूर्य','चंद्रमा','पेड़','शहर','गाँव'],computer:['कंप्यूटर','मोबाइल','कीबोर्ड','इंटरनेट','ऐप','माउस','स्क्रीन','पासवर्ड','फाइल','ब्राउज़र'],life:['सफाई','समय','सुरक्षा','पढ़ाई','बातचीत','सहयोग','जिम्मेदारी','आराम','अनुशासन','अच्छी आदत'],environment:['पेड़','पानी','हवा','कचरा','धरती','मिट्टी','पक्षी','नदी','बगीचा','ऊर्जा']};
  const arr=examples[subject]||examples.gk, ex=arr[n%arr.length];
  const levelText=n<100?'बहुत आसान':n<200?'आसान':n<300?'मध्यम':n<400?'अभ्यास वाला':'चुनौती वाला';
  let content=t[1]+`

🎯 आज का लक्ष्य: ${ex} से जुड़ी एक नई बात समझना और उसे अपने शब्दों में बताना।

🪜 स्तर: ${levelText}. पहले धीरे-धीरे पढ़ें, उदाहरण देखें और फिर खुद जवाब देने की कोशिश करें।

🧠 याद रखें: हर दिन थोड़ा-थोड़ा सीखने से समझ मजबूत होती है।`;
  const genericTemplates=[
    {q:`आज के पाठ में ${ex} से जुड़ी बात समझना क्यों ज़रूरी है?`,options:['समझकर सीखने और रोज़मर्रा में उपयोग के लिए','सिर्फ स्क्रीन देखने के लिए','पाठ छोड़ने के लिए','कोई कारण नहीं'],correct:'समझकर सीखने और रोज़मर्रा में उपयोग के लिए'},
    {q:`आज के पाठ का मुख्य विषय क्या था?`,options:[ex,'कुछ भी नहीं','सिर्फ चित्र','सिर्फ अंक'],correct:ex},
    {q:`${ex} के बारे में सीखने के लिए सबसे अच्छा तरीका क्या है?`,options:['ध्यान से पढ़ना और उदाहरण देखना','जल्दी-जल्दी पढ़कर भूल जाना','सिर्फ स्क्रॉल करना','कुछ न करना'],correct:'ध्यान से पढ़ना और उदाहरण देखना'},
    {q:`रोज़ थोड़ा-थोड़ा सीखने से क्या फ़ायदा होता है?`,options:['समझ मज़बूत होती है','कुछ नहीं होता','भूल जाते हैं','समय बर्बाद होता है'],correct:'समझ मज़बूत होती है'},
    {q:`सीखी हुई बात को अपने शब्दों में बताना क्यों उपयोगी है?`,options:['इससे समझ पक्की होती है','इससे कुछ फ़ायदा नहीं','इससे भूल जाते हैं','इसकी ज़रूरत नहीं'],correct:'इससे समझ पक्की होती है'},
    {q:`आज का पाठ किस बारे में था?`,options:[ex,'कोई विषय नहीं','सिर्फ खेल','सिर्फ गाना'],correct:ex},
  ];
  const mathTemplates=[
    {q:'गणित सीखने का अच्छा तरीका क्या है?',options:['समझकर अभ्यास करना','सिर्फ उत्तर देखना','सवाल छोड़ देना','कुछ नहीं'],correct:'समझकर अभ्यास करना'},
    {q:`आज के पाठ में किस संख्या/उदाहरण का इस्तेमाल हुआ?`,options:[ex,'कोई नहीं','सिर्फ रंग','सिर्फ चित्र'],correct:ex},
    {q:'गणित के सवाल हल करते समय क्या करना चाहिए?',options:['हर कदम ध्यान से समझना','जल्दी में जवाब लिखना','सवाल छोड़ देना','अंदाज़े से लिखना'],correct:'हर कदम ध्यान से समझना'},
    {q:'रोज़ थोड़ा गणित अभ्यास करने से क्या होता है?',options:['हिसाब तेज़ हो जाता है','कुछ नहीं होता','भूल जाते हैं','मुश्किल हो जाता है'],correct:'हिसाब तेज़ हो जाता है'},
  ];
  const englishTemplates=[
    {q:'English सीखने में क्या मदद करता है?',options:['पढ़ना, बोलना और अभ्यास करना','सिर्फ देखना','सिर्फ चुप रहना','कुछ नहीं'],correct:'पढ़ना, बोलना और अभ्यास करना'},
    {q:`Today's lesson was about which word?`,options:[ex,'None','Only colours','Only numbers'],correct:ex},
    {q:'नए English शब्द याद रखने का अच्छा तरीका क्या है?',options:['बार-बार बोलकर अभ्यास करना','सिर्फ एक बार देखना','कभी न बोलना','भूल जाना'],correct:'बार-बार बोलकर अभ्यास करना'},
    {q:'रोज़ थोड़ा English पढ़ने से क्या फ़ायदा होता है?',options:['भाषा पर पकड़ मज़बूत होती है','कुछ नहीं होता','भूल जाते हैं','समय बर्बाद होता है'],correct:'भाषा पर पकड़ मज़बूत होती है'},
  ];
  let q=genericTemplates[n%genericTemplates.length];
  if(subject==='math') q=mathTemplates[n%mathTemplates.length];
  if(subject==='english') q=englishTemplates[n%englishTemplates.length];
  return {id:`daily-${classId}-${subject}-${n}`,title:`${t[0]} — दैनिक पाठ ${n+1}`,icon:['📘','🧠','🌟','🔎','📚'][n%5],content,quiz:[q],endless:true,number:n};
}
function studyOpenEndless(){studyState.view='endlessSubjects';renderStudy()}
function studyOpenEndlessTopic(subject){studyState.subjectId=subject;studyState.view='endlessLesson';const next=endlessCounter()+1;endlessSaveCounter(next);studyState.endlessIndex=next;renderStudy()}
function studyNextEndless(){
  const next=endlessCounter()+1; endlessSaveCounter(next); studyState.endlessIndex=next; studyState.view='endlessLesson'; speechSynthesis.cancel(); renderStudy();
}
function studyEndlessMark(){
  const id=`daily-${studyState.classId}-${studyState.subjectId}-${studyState.endlessIndex||dailyDayIndex()}`;
  const p=studyProgress(); if(!p[id]){p[id]=true;studySaveProgress(p);addStar();}
  dailySaveCompleted(studyState.classId,studyState.subjectId);
  renderStudy();
}

let studyState={view:'classes',classId:null,subjectId:null,lessonId:null,qIndex:0,endlessIndex:0,pageIndex:0};

function studyProgress(){try{return JSON.parse(localStorage.getItem('pathshalaProgress')||'{}')}catch(e){return{}}}
function studySaveProgress(p){localStorage.setItem('pathshalaProgress',JSON.stringify(p))}
function studyIsDone(lessonId){return !!studyProgress()[lessonId]}
