STUDY_DATA[6].subjects['hindi'].lessons.push({"id": "c6-hindi-v72-1", "title": "अलंकार: उपमा और रूपक", "icon": "📚", "content": "भाषा को सुंदर बनाने के लिए अलंकारों का प्रयोग होता है। उपमा में किसी वस्तु की तुलना जैसे, सा, समान आदि शब्दों से की जाती है। रूपक में तुलना सीधे पहचान के रूप में होती है। उदाहरण: उसका चेहरा चाँद सा है—उपमा। वह घर का दीपक है—रूपक।\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "“अलंकार: उपमा और रूपक” पाठ का मुख्य उद्देश्य क्या है?", "options": ["विषय को समझना", "केवल कहानी सुनना", "केवल चित्र बनाना", "केवल याद करना"], "correct": "विषय को समझना"}, {"q": "अच्छा उत्तर लिखते समय क्या जरूरी है?", "options": ["विषय के अनुसार स्पष्ट उत्तर", "बिना पढ़े अनुमान", "असंबंधित बातें", "केवल एक शब्द"], "correct": "विषय के अनुसार स्पष्ट उत्तर"}, {"q": "अभ्यास से क्या लाभ होता है?", "options": ["समझ और याददाश्त मजबूत होती है", "पढ़ाई रुक जाती है", "गलती हमेशा बढ़ती है", "कोई लाभ नहीं"], "correct": "समझ और याददाश्त मजबूत होती है"}, {"q": "नया पाठ सीखने का अच्छा क्रम कौन सा है?", "options": ["समझो → उदाहरण → अभ्यास", "पहले उत्तर रटें", "केवल शीर्षक पढ़ें", "अभ्यास छोड़ दें"], "correct": "समझो → उदाहरण → अभ्यास"}, {"q": "पाठ पूरा करने के बाद क्या करना उपयोगी है?", "options": ["अपने शब्दों में दोहराना", "बिना देखे छोड़ देना", "सवाल हटाना", "पढ़ना बंद करना"], "correct": "अपने शब्दों में दोहराना"}]});
