STUDY_DATA[6].subjects['math'].lessons.push({"id": "c6-math-v72-2", "title": "भिन्नों का जोड़", "icon": "➗", "content": "समान हर वाली भिन्नों को जोड़ते समय हर वही रहता है और अंश जोड़े जाते हैं। अलग हर होने पर पहले समान हर बनाना पड़ता है। उदाहरण: 1/5 + 2/5 = 3/5।\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "“भिन्नों का जोड़” पाठ में किस बात को समझना है?", "options": ["गणितीय विचार और उसका उपयोग", "केवल नाम", "केवल चित्र", "केवल अनुमान"], "correct": "गणितीय विचार और उसका उपयोग"}, {"q": "गणित के सवाल में पहला अच्छा कदम क्या है?", "options": ["दिए गए मान और पूछा गया मान पहचानना", "बिना पढ़े उत्तर चुनना", "इकाई छोड़ देना", "सवाल बदल देना"], "correct": "दिए गए मान और पूछा गया मान पहचानना"}, {"q": "उत्तर की जाँच क्यों करनी चाहिए?", "options": ["गलती पकड़ने के लिए", "समय खराब करने के लिए", "सवाल हटाने के लिए", "किसी कारण के बिना"], "correct": "गलती पकड़ने के लिए"}, {"q": "कठिन सवाल को कैसे हल करना बेहतर है?", "options": ["उसे छोटे चरणों में बाँटकर", "सीधे अनुमान लगाकर", "प्रश्न छोड़कर", "केवल उत्तर देखकर"], "correct": "उसे छोटे चरणों में बाँटकर"}, {"q": "अभ्यास से क्या मजबूत होता है?", "options": ["गणितीय समझ", "सिर्फ लिखावट", "केवल गति", "कुछ नहीं"], "correct": "गणितीय समझ"}]});
STUDY_DATA[6].subjects['math'].lessons.push({"id": "c6-math-v72-3", "title": "बीजगणितीय व्यंजक का परिचय", "icon": "➗", "content": "जिस व्यंजक में संख्या और अक्षर साथ हों, उसे बीजगणितीय व्यंजक कह सकते हैं। 3x + 2 में x चर है, 3 उसका गुणांक और 2 स्थिर पद है। ऐसे व्यंजकों को सरल करने के लिए समान पदों को जोड़ा जाता है।\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "“बीजगणितीय व्यंजक का परिचय” पाठ में किस बात को समझना है?", "options": ["गणितीय विचार और उसका उपयोग", "केवल नाम", "केवल चित्र", "केवल अनुमान"], "correct": "गणितीय विचार और उसका उपयोग"}, {"q": "गणित के सवाल में पहला अच्छा कदम क्या है?", "options": ["दिए गए मान और पूछा गया मान पहचानना", "बिना पढ़े उत्तर चुनना", "इकाई छोड़ देना", "सवाल बदल देना"], "correct": "दिए गए मान और पूछा गया मान पहचानना"}, {"q": "उत्तर की जाँच क्यों करनी चाहिए?", "options": ["गलती पकड़ने के लिए", "समय खराब करने के लिए", "सवाल हटाने के लिए", "किसी कारण के बिना"], "correct": "गलती पकड़ने के लिए"}, {"q": "कठिन सवाल को कैसे हल करना बेहतर है?", "options": ["उसे छोटे चरणों में बाँटकर", "सीधे अनुमान लगाकर", "प्रश्न छोड़कर", "केवल उत्तर देखकर"], "correct": "उसे छोटे चरणों में बाँटकर"}, {"q": "अभ्यास से क्या मजबूत होता है?", "options": ["गणितीय समझ", "सिर्फ लिखावट", "केवल गति", "कुछ नहीं"], "correct": "गणितीय समझ"}]});
STUDY_DATA[7].subjects['hindi'].lessons.push({"id": "c7-hindi-v72-1", "title": "समास के प्रमुख भेद", "icon": "📚", "content": "समास में दो या अधिक शब्द मिलकर छोटा और अर्थपूर्ण शब्द बनाते हैं। तत्पुरुष, द्वंद्व, कर्मधारय और बहुव्रीहि इसके प्रमुख भेदों में हैं। समास पहचानते समय विग्रह करके देखना उपयोगी होता है।\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "“समास के प्रमुख भेद” पाठ का मुख्य उद्देश्य क्या है?", "options": ["विषय को समझना", "केवल कहानी सुनना", "केवल चित्र बनाना", "केवल याद करना"], "correct": "विषय को समझना"}, {"q": "अच्छा उत्तर लिखते समय क्या जरूरी है?", "options": ["विषय के अनुसार स्पष्ट उत्तर", "बिना पढ़े अनुमान", "असंबंधित बातें", "केवल एक शब्द"], "correct": "विषय के अनुसार स्पष्ट उत्तर"}, {"q": "अभ्यास से क्या लाभ होता है?", "options": ["समझ और याददाश्त मजबूत होती है", "पढ़ाई रुक जाती है", "गलती हमेशा बढ़ती है", "कोई लाभ नहीं"], "correct": "समझ और याददाश्त मजबूत होती है"}, {"q": "नया पाठ सीखने का अच्छा क्रम कौन सा है?", "options": ["समझो → उदाहरण → अभ्यास", "पहले उत्तर रटें", "केवल शीर्षक पढ़ें", "अभ्यास छोड़ दें"], "correct": "समझो → उदाहरण → अभ्यास"}, {"q": "पाठ पूरा करने के बाद क्या करना उपयोगी है?", "options": ["अपने शब्दों में दोहराना", "बिना देखे छोड़ देना", "सवाल हटाना", "पढ़ना बंद करना"], "correct": "अपने शब्दों में दोहराना"}]});
STUDY_DATA[7].subjects['hindi'].lessons.push({"id": "c7-hindi-v72-2", "title": "वाच्य: कर्तृ और कर्मवाच्य", "icon": "📚", "content": "वाक्य में काम करने वाले पर जोर हो तो कर्तृवाच्य और काम या कर्म पर जोर हो तो कर्मवाच्य कहा जाता है। उदाहरण: सीमा ने पत्र लिखा—कर्तृवाच्य। पत्र सीमा द्वारा लिखा गया—कर्मवाच्य।\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "“वाच्य: कर्तृ और कर्मवाच्य” पाठ का मुख्य उद्देश्य क्या है?", "options": ["विषय को समझना", "केवल कहानी सुनना", "केवल चित्र बनाना", "केवल याद करना"], "correct": "विषय को समझना"}, {"q": "अच्छा उत्तर लिखते समय क्या जरूरी है?", "options": ["विषय के अनुसार स्पष्ट उत्तर", "बिना पढ़े अनुमान", "असंबंधित बातें", "केवल एक शब्द"], "correct": "विषय के अनुसार स्पष्ट उत्तर"}, {"q": "अभ्यास से क्या लाभ होता है?", "options": ["समझ और याददाश्त मजबूत होती है", "पढ़ाई रुक जाती है", "गलती हमेशा बढ़ती है", "कोई लाभ नहीं"], "correct": "समझ और याददाश्त मजबूत होती है"}, {"q": "नया पाठ सीखने का अच्छा क्रम कौन सा है?", "options": ["समझो → उदाहरण → अभ्यास", "पहले उत्तर रटें", "केवल शीर्षक पढ़ें", "अभ्यास छोड़ दें"], "correct": "समझो → उदाहरण → अभ्यास"}, {"q": "पाठ पूरा करने के बाद क्या करना उपयोगी है?", "options": ["अपने शब्दों में दोहराना", "बिना देखे छोड़ देना", "सवाल हटाना", "पढ़ना बंद करना"], "correct": "अपने शब्दों में दोहराना"}]});
STUDY_DATA[7].subjects['hindi'].lessons.push({"id": "c7-hindi-v72-3", "title": "कहानी का तत्व और संदेश", "icon": "📚", "content": "कहानी में पात्र, स्थान, घटना, समस्या और समाधान जैसे तत्व होते हैं। अच्छी कहानी घटनाओं को क्रम से रखती है और अंत में कोई सीख या प्रभाव छोड़ सकती है।\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "“कहानी का तत्व और संदेश” पाठ का मुख्य उद्देश्य क्या है?", "options": ["विषय को समझना", "केवल कहानी सुनना", "केवल चित्र बनाना", "केवल याद करना"], "correct": "विषय को समझना"}, {"q": "अच्छा उत्तर लिखते समय क्या जरूरी है?", "options": ["विषय के अनुसार स्पष्ट उत्तर", "बिना पढ़े अनुमान", "असंबंधित बातें", "केवल एक शब्द"], "correct": "विषय के अनुसार स्पष्ट उत्तर"}, {"q": "अभ्यास से क्या लाभ होता है?", "options": ["समझ और याददाश्त मजबूत होती है", "पढ़ाई रुक जाती है", "गलती हमेशा बढ़ती है", "कोई लाभ नहीं"], "correct": "समझ और याददाश्त मजबूत होती है"}, {"q": "नया पाठ सीखने का अच्छा क्रम कौन सा है?", "options": ["समझो → उदाहरण → अभ्यास", "पहले उत्तर रटें", "केवल शीर्षक पढ़ें", "अभ्यास छोड़ दें"], "correct": "समझो → उदाहरण → अभ्यास"}, {"q": "पाठ पूरा करने के बाद क्या करना उपयोगी है?", "options": ["अपने शब्दों में दोहराना", "बिना देखे छोड़ देना", "सवाल हटाना", "पढ़ना बंद करना"], "correct": "अपने शब्दों में दोहराना"}]});
STUDY_DATA[7].subjects['english'].lessons.push({"id": "c7-english-v72-1", "title": "Kinds of Sentences", "icon": "🔤", "content": "English sentences can be declarative, interrogative, imperative, or exclamatory. A declarative sentence gives information, an interrogative asks a question, an imperative gives a command or request, and an exclamatory sentence shows strong feeling.\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "What is the main focus of “Kinds of Sentences”?", "options": ["Understanding the topic", "Only drawing", "Only memorising", "Skipping practice"], "correct": "Understanding the topic"}, {"q": "What makes an answer clear?", "options": ["It directly addresses the question", "It changes the topic", "It has no explanation", "It is only one random word"], "correct": "It directly addresses the question"}, {"q": "Why is practice useful?", "options": ["It strengthens understanding", "It removes learning", "It always creates errors", "It has no purpose"], "correct": "It strengthens understanding"}, {"q": "Which learning order is best?", "options": ["Understand → Example → Practice", "Guess → Skip → Finish", "Read title only", "Avoid practice"], "correct": "Understand → Example → Practice"}, {"q": "After a lesson, what is useful?", "options": ["Explain it in your own words", "Forget it immediately", "Delete the questions", "Stop reading forever"], "correct": "Explain it in your own words"}]});
STUDY_DATA[7].subjects['english'].lessons.push({"id": "c7-english-v72-2", "title": "Past Continuous Tense", "icon": "🔤", "content": "The past continuous describes an action that was in progress at a particular time in the past. It uses was/were + verb-ing. Example: I was reading at eight. They were playing when it rained.\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "What is the main focus of “Past Continuous Tense”?", "options": ["Understanding the topic", "Only drawing", "Only memorising", "Skipping practice"], "correct": "Understanding the topic"}, {"q": "What makes an answer clear?", "options": ["It directly addresses the question", "It changes the topic", "It has no explanation", "It is only one random word"], "correct": "It directly addresses the question"}, {"q": "Why is practice useful?", "options": ["It strengthens understanding", "It removes learning", "It always creates errors", "It has no purpose"], "correct": "It strengthens understanding"}, {"q": "Which learning order is best?", "options": ["Understand → Example → Practice", "Guess → Skip → Finish", "Read title only", "Avoid practice"], "correct": "Understand → Example → Practice"}, {"q": "After a lesson, what is useful?", "options": ["Explain it in your own words", "Forget it immediately", "Delete the questions", "Stop reading forever"], "correct": "Explain it in your own words"}]});
STUDY_DATA[7].subjects['english'].lessons.push({"id": "c7-english-v72-3", "title": "Paragraph: A Clear Topic Sentence", "icon": "🔤", "content": "A paragraph becomes easier to understand when it begins with a clear topic sentence. Supporting sentences explain the topic with facts, examples, or reasons. The last sentence can close the idea neatly.\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "What is the main focus of “Paragraph: A Clear Topic Sentence”?", "options": ["Understanding the topic", "Only drawing", "Only memorising", "Skipping practice"], "correct": "Understanding the topic"}, {"q": "What makes an answer clear?", "options": ["It directly addresses the question", "It changes the topic", "It has no explanation", "It is only one random word"], "correct": "It directly addresses the question"}, {"q": "Why is practice useful?", "options": ["It strengthens understanding", "It removes learning", "It always creates errors", "It has no purpose"], "correct": "It strengthens understanding"}, {"q": "Which learning order is best?", "options": ["Understand → Example → Practice", "Guess → Skip → Finish", "Read title only", "Avoid practice"], "correct": "Understand → Example → Practice"}, {"q": "After a lesson, what is useful?", "options": ["Explain it in your own words", "Forget it immediately", "Delete the questions", "Stop reading forever"], "correct": "Explain it in your own words"}]});
STUDY_DATA[7].subjects['math'].lessons.push({"id": "c7-math-v72-1", "title": "परिमेय संख्याएँ", "icon": "➗", "content": "परिमेय संख्या वह संख्या है जिसे p/q के रूप में लिखा जा सके, जहाँ p और q पूर्णांक हों तथा q शून्य न हो। 1/2, -3/4 और 5 सभी परिमेय संख्याएँ हैं क्योंकि 5 को 5/1 लिखा जा सकता है।\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "“परिमेय संख्याएँ” पाठ में किस बात को समझना है?", "options": ["गणितीय विचार और उसका उपयोग", "केवल नाम", "केवल चित्र", "केवल अनुमान"], "correct": "गणितीय विचार और उसका उपयोग"}, {"q": "गणित के सवाल में पहला अच्छा कदम क्या है?", "options": ["दिए गए मान और पूछा गया मान पहचानना", "बिना पढ़े उत्तर चुनना", "इकाई छोड़ देना", "सवाल बदल देना"], "correct": "दिए गए मान और पूछा गया मान पहचानना"}, {"q": "उत्तर की जाँच क्यों करनी चाहिए?", "options": ["गलती पकड़ने के लिए", "समय खराब करने के लिए", "सवाल हटाने के लिए", "किसी कारण के बिना"], "correct": "गलती पकड़ने के लिए"}, {"q": "कठिन सवाल को कैसे हल करना बेहतर है?", "options": ["उसे छोटे चरणों में बाँटकर", "सीधे अनुमान लगाकर", "प्रश्न छोड़कर", "केवल उत्तर देखकर"], "correct": "उसे छोटे चरणों में बाँटकर"}, {"q": "अभ्यास से क्या मजबूत होता है?", "options": ["गणितीय समझ", "सिर्फ लिखावट", "केवल गति", "कुछ नहीं"], "correct": "गणितीय समझ"}]});
STUDY_DATA[7].subjects['math'].lessons.push({"id": "c7-math-v72-2", "title": "सरल रैखिक समीकरण", "icon": "➗", "content": "जिस समीकरण में चर की घात 1 हो, वह सरल रैखिक समीकरण हो सकता है। 2x+3=11 में दोनों पक्षों से 3 घटाकर 2x=8 और फिर 2 से भाग देकर x=4 मिलता है।\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "“सरल रैखिक समीकरण” पाठ में किस बात को समझना है?", "options": ["गणितीय विचार और उसका उपयोग", "केवल नाम", "केवल चित्र", "केवल अनुमान"], "correct": "गणितीय विचार और उसका उपयोग"}, {"q": "गणित के सवाल में पहला अच्छा कदम क्या है?", "options": ["दिए गए मान और पूछा गया मान पहचानना", "बिना पढ़े उत्तर चुनना", "इकाई छोड़ देना", "सवाल बदल देना"], "correct": "दिए गए मान और पूछा गया मान पहचानना"}, {"q": "उत्तर की जाँच क्यों करनी चाहिए?", "options": ["गलती पकड़ने के लिए", "समय खराब करने के लिए", "सवाल हटाने के लिए", "किसी कारण के बिना"], "correct": "गलती पकड़ने के लिए"}, {"q": "कठिन सवाल को कैसे हल करना बेहतर है?", "options": ["उसे छोटे चरणों में बाँटकर", "सीधे अनुमान लगाकर", "प्रश्न छोड़कर", "केवल उत्तर देखकर"], "correct": "उसे छोटे चरणों में बाँटकर"}, {"q": "अभ्यास से क्या मजबूत होता है?", "options": ["गणितीय समझ", "सिर्फ लिखावट", "केवल गति", "कुछ नहीं"], "correct": "गणितीय समझ"}]});
STUDY_DATA[7].subjects['math'].lessons.push({"id": "c7-math-v72-3", "title": "त्रिभुज के कोण", "icon": "➗", "content": "त्रिभुज के तीनों आंतरिक कोणों का योग 180° होता है। यदि दो कोण 60° और 70° हैं, तो तीसरा कोण 180°−130° = 50° होगा।\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "“त्रिभुज के कोण” पाठ में किस बात को समझना है?", "options": ["गणितीय विचार और उसका उपयोग", "केवल नाम", "केवल चित्र", "केवल अनुमान"], "correct": "गणितीय विचार और उसका उपयोग"}, {"q": "गणित के सवाल में पहला अच्छा कदम क्या है?", "options": ["दिए गए मान और पूछा गया मान पहचानना", "बिना पढ़े उत्तर चुनना", "इकाई छोड़ देना", "सवाल बदल देना"], "correct": "दिए गए मान और पूछा गया मान पहचानना"}, {"q": "उत्तर की जाँच क्यों करनी चाहिए?", "options": ["गलती पकड़ने के लिए", "समय खराब करने के लिए", "सवाल हटाने के लिए", "किसी कारण के बिना"], "correct": "गलती पकड़ने के लिए"}, {"q": "कठिन सवाल को कैसे हल करना बेहतर है?", "options": ["उसे छोटे चरणों में बाँटकर", "सीधे अनुमान लगाकर", "प्रश्न छोड़कर", "केवल उत्तर देखकर"], "correct": "उसे छोटे चरणों में बाँटकर"}, {"q": "अभ्यास से क्या मजबूत होता है?", "options": ["गणितीय समझ", "सिर्फ लिखावट", "केवल गति", "कुछ नहीं"], "correct": "गणितीय समझ"}]});
STUDY_DATA[8].subjects['hindi'].lessons.push({"id": "c8-hindi-v72-1", "title": "संधि का परिचय", "icon": "📚", "content": "दो वर्णों या शब्दांशों के मेल से होने वाले ध्वनि परिवर्तन को संधि कहते हैं। संधि को समझने के लिए बने हुए शब्द को अलग करके मूल रूप पहचानना उपयोगी है।\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "“संधि का परिचय” पाठ का मुख्य उद्देश्य क्या है?", "options": ["विषय को समझना", "केवल कहानी सुनना", "केवल चित्र बनाना", "केवल याद करना"], "correct": "विषय को समझना"}, {"q": "अच्छा उत्तर लिखते समय क्या जरूरी है?", "options": ["विषय के अनुसार स्पष्ट उत्तर", "बिना पढ़े अनुमान", "असंबंधित बातें", "केवल एक शब्द"], "correct": "विषय के अनुसार स्पष्ट उत्तर"}, {"q": "अभ्यास से क्या लाभ होता है?", "options": ["समझ और याददाश्त मजबूत होती है", "पढ़ाई रुक जाती है", "गलती हमेशा बढ़ती है", "कोई लाभ नहीं"], "correct": "समझ और याददाश्त मजबूत होती है"}, {"q": "नया पाठ सीखने का अच्छा क्रम कौन सा है?", "options": ["समझो → उदाहरण → अभ्यास", "पहले उत्तर रटें", "केवल शीर्षक पढ़ें", "अभ्यास छोड़ दें"], "correct": "समझो → उदाहरण → अभ्यास"}, {"q": "पाठ पूरा करने के बाद क्या करना उपयोगी है?", "options": ["अपने शब्दों में दोहराना", "बिना देखे छोड़ देना", "सवाल हटाना", "पढ़ना बंद करना"], "correct": "अपने शब्दों में दोहराना"}]});
STUDY_DATA[8].subjects['hindi'].lessons.push({"id": "c8-hindi-v72-2", "title": "वाक्य के प्रकार", "icon": "📚", "content": "रचना और भाव के आधार पर वाक्य अलग प्रकार के हो सकते हैं। सरल वाक्य में एक मुख्य कथन होता है, जबकि संयुक्त वाक्य में समान स्तर के कथन जुड़े होते हैं और मिश्र वाक्य में मुख्य तथा आश्रित उपवाक्य होते हैं।\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "“वाक्य के प्रकार” पाठ का मुख्य उद्देश्य क्या है?", "options": ["विषय को समझना", "केवल कहानी सुनना", "केवल चित्र बनाना", "केवल याद करना"], "correct": "विषय को समझना"}, {"q": "अच्छा उत्तर लिखते समय क्या जरूरी है?", "options": ["विषय के अनुसार स्पष्ट उत्तर", "बिना पढ़े अनुमान", "असंबंधित बातें", "केवल एक शब्द"], "correct": "विषय के अनुसार स्पष्ट उत्तर"}, {"q": "अभ्यास से क्या लाभ होता है?", "options": ["समझ और याददाश्त मजबूत होती है", "पढ़ाई रुक जाती है", "गलती हमेशा बढ़ती है", "कोई लाभ नहीं"], "correct": "समझ और याददाश्त मजबूत होती है"}, {"q": "नया पाठ सीखने का अच्छा क्रम कौन सा है?", "options": ["समझो → उदाहरण → अभ्यास", "पहले उत्तर रटें", "केवल शीर्षक पढ़ें", "अभ्यास छोड़ दें"], "correct": "समझो → उदाहरण → अभ्यास"}, {"q": "पाठ पूरा करने के बाद क्या करना उपयोगी है?", "options": ["अपने शब्दों में दोहराना", "बिना देखे छोड़ देना", "सवाल हटाना", "पढ़ना बंद करना"], "correct": "अपने शब्दों में दोहराना"}]});
STUDY_DATA[8].subjects['hindi'].lessons.push({"id": "c8-hindi-v72-3", "title": "निबंध लेखन की योजना", "icon": "📚", "content": "निबंध लिखने से पहले विषय के मुख्य बिंदु तय करें। भूमिका में विषय का परिचय, मध्य भाग में क्रमबद्ध विचार और अंत में निष्कर्ष रखें। उदाहरण और कारण लेख को अधिक स्पष्ट बनाते हैं।\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "“निबंध लेखन की योजना” पाठ का मुख्य उद्देश्य क्या है?", "options": ["विषय को समझना", "केवल कहानी सुनना", "केवल चित्र बनाना", "केवल याद करना"], "correct": "विषय को समझना"}, {"q": "अच्छा उत्तर लिखते समय क्या जरूरी है?", "options": ["विषय के अनुसार स्पष्ट उत्तर", "बिना पढ़े अनुमान", "असंबंधित बातें", "केवल एक शब्द"], "correct": "विषय के अनुसार स्पष्ट उत्तर"}, {"q": "अभ्यास से क्या लाभ होता है?", "options": ["समझ और याददाश्त मजबूत होती है", "पढ़ाई रुक जाती है", "गलती हमेशा बढ़ती है", "कोई लाभ नहीं"], "correct": "समझ और याददाश्त मजबूत होती है"}, {"q": "नया पाठ सीखने का अच्छा क्रम कौन सा है?", "options": ["समझो → उदाहरण → अभ्यास", "पहले उत्तर रटें", "केवल शीर्षक पढ़ें", "अभ्यास छोड़ दें"], "correct": "समझो → उदाहरण → अभ्यास"}, {"q": "पाठ पूरा करने के बाद क्या करना उपयोगी है?", "options": ["अपने शब्दों में दोहराना", "बिना देखे छोड़ देना", "सवाल हटाना", "पढ़ना बंद करना"], "correct": "अपने शब्दों में दोहराना"}]});
STUDY_DATA[8].subjects['english'].lessons.push({"id": "c8-english-v72-1", "title": "Active and Passive Voice", "icon": "🔤", "content": "In active voice, the subject performs the action: The boy opened the door. In passive voice, the receiver of the action is highlighted: The door was opened by the boy. The tense must remain consistent when changing voice.\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "What is the main focus of “Active and Passive Voice”?", "options": ["Understanding the topic", "Only drawing", "Only memorising", "Skipping practice"], "correct": "Understanding the topic"}, {"q": "What makes an answer clear?", "options": ["It directly addresses the question", "It changes the topic", "It has no explanation", "It is only one random word"], "correct": "It directly addresses the question"}, {"q": "Why is practice useful?", "options": ["It strengthens understanding", "It removes learning", "It always creates errors", "It has no purpose"], "correct": "It strengthens understanding"}, {"q": "Which learning order is best?", "options": ["Understand → Example → Practice", "Guess → Skip → Finish", "Read title only", "Avoid practice"], "correct": "Understand → Example → Practice"}, {"q": "After a lesson, what is useful?", "options": ["Explain it in your own words", "Forget it immediately", "Delete the questions", "Stop reading forever"], "correct": "Explain it in your own words"}]});
STUDY_DATA[8].subjects['english'].lessons.push({"id": "c8-english-v72-2", "title": "Direct and Indirect Speech", "icon": "🔤", "content": "Direct speech gives the speaker’s exact words inside quotation marks. Indirect speech reports the meaning without quoting the exact words. Pronouns, tense, and time expressions may change according to the reporting context.\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "What is the main focus of “Direct and Indirect Speech”?", "options": ["Understanding the topic", "Only drawing", "Only memorising", "Skipping practice"], "correct": "Understanding the topic"}, {"q": "What makes an answer clear?", "options": ["It directly addresses the question", "It changes the topic", "It has no explanation", "It is only one random word"], "correct": "It directly addresses the question"}, {"q": "Why is practice useful?", "options": ["It strengthens understanding", "It removes learning", "It always creates errors", "It has no purpose"], "correct": "It strengthens understanding"}, {"q": "Which learning order is best?", "options": ["Understand → Example → Practice", "Guess → Skip → Finish", "Read title only", "Avoid practice"], "correct": "Understand → Example → Practice"}, {"q": "After a lesson, what is useful?", "options": ["Explain it in your own words", "Forget it immediately", "Delete the questions", "Stop reading forever"], "correct": "Explain it in your own words"}]});
STUDY_DATA[8].subjects['english'].lessons.push({"id": "c8-english-v72-3", "title": "Reading: Fact and Opinion", "icon": "🔤", "content": "A fact can be checked or supported with evidence. An opinion expresses a belief, judgment, or personal view. While reading, look for evidence and words that show personal judgment to distinguish them.\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "What is the main focus of “Reading: Fact and Opinion”?", "options": ["Understanding the topic", "Only drawing", "Only memorising", "Skipping practice"], "correct": "Understanding the topic"}, {"q": "What makes an answer clear?", "options": ["It directly addresses the question", "It changes the topic", "It has no explanation", "It is only one random word"], "correct": "It directly addresses the question"}, {"q": "Why is practice useful?", "options": ["It strengthens understanding", "It removes learning", "It always creates errors", "It has no purpose"], "correct": "It strengthens understanding"}, {"q": "Which learning order is best?", "options": ["Understand → Example → Practice", "Guess → Skip → Finish", "Read title only", "Avoid practice"], "correct": "Understand → Example → Practice"}, {"q": "After a lesson, what is useful?", "options": ["Explain it in your own words", "Forget it immediately", "Delete the questions", "Stop reading forever"], "correct": "Explain it in your own words"}]});
STUDY_DATA[8].subjects['math'].lessons.push({"id": "c8-math-v72-1", "title": "घातांक के नियम", "icon": "➗", "content": "घातांक किसी संख्या के बार-बार गुणन को संक्षेप में लिखते हैं। समान आधार के गुणन में घातांक जोड़े जाते हैं: a^m × a^n = a^(m+n)। भाग में घातांक घटते हैं, जब आधार समान हो।\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "“घातांक के नियम” पाठ में किस बात को समझना है?", "options": ["गणितीय विचार और उसका उपयोग", "केवल नाम", "केवल चित्र", "केवल अनुमान"], "correct": "गणितीय विचार और उसका उपयोग"}, {"q": "गणित के सवाल में पहला अच्छा कदम क्या है?", "options": ["दिए गए मान और पूछा गया मान पहचानना", "बिना पढ़े उत्तर चुनना", "इकाई छोड़ देना", "सवाल बदल देना"], "correct": "दिए गए मान और पूछा गया मान पहचानना"}, {"q": "उत्तर की जाँच क्यों करनी चाहिए?", "options": ["गलती पकड़ने के लिए", "समय खराब करने के लिए", "सवाल हटाने के लिए", "किसी कारण के बिना"], "correct": "गलती पकड़ने के लिए"}, {"q": "कठिन सवाल को कैसे हल करना बेहतर है?", "options": ["उसे छोटे चरणों में बाँटकर", "सीधे अनुमान लगाकर", "प्रश्न छोड़कर", "केवल उत्तर देखकर"], "correct": "उसे छोटे चरणों में बाँटकर"}, {"q": "अभ्यास से क्या मजबूत होता है?", "options": ["गणितीय समझ", "सिर्फ लिखावट", "केवल गति", "कुछ नहीं"], "correct": "गणितीय समझ"}]});
STUDY_DATA[8].subjects['math'].lessons.push({"id": "c8-math-v72-2", "title": "रैखिक समीकरण और अनुप्रयोग", "icon": "➗", "content": "रैखिक समीकरण का उपयोग वास्तविक जीवन की समस्याओं में अज्ञात राशि खोजने के लिए किया जाता है। पहले अज्ञात को x मानें, फिर समस्या से समीकरण बनाएँ और अंत में उत्तर को मूल स्थिति से जाँचें।\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "“रैखिक समीकरण और अनुप्रयोग” पाठ में किस बात को समझना है?", "options": ["गणितीय विचार और उसका उपयोग", "केवल नाम", "केवल चित्र", "केवल अनुमान"], "correct": "गणितीय विचार और उसका उपयोग"}, {"q": "गणित के सवाल में पहला अच्छा कदम क्या है?", "options": ["दिए गए मान और पूछा गया मान पहचानना", "बिना पढ़े उत्तर चुनना", "इकाई छोड़ देना", "सवाल बदल देना"], "correct": "दिए गए मान और पूछा गया मान पहचानना"}, {"q": "उत्तर की जाँच क्यों करनी चाहिए?", "options": ["गलती पकड़ने के लिए", "समय खराब करने के लिए", "सवाल हटाने के लिए", "किसी कारण के बिना"], "correct": "गलती पकड़ने के लिए"}, {"q": "कठिन सवाल को कैसे हल करना बेहतर है?", "options": ["उसे छोटे चरणों में बाँटकर", "सीधे अनुमान लगाकर", "प्रश्न छोड़कर", "केवल उत्तर देखकर"], "correct": "उसे छोटे चरणों में बाँटकर"}, {"q": "अभ्यास से क्या मजबूत होता है?", "options": ["गणितीय समझ", "सिर्फ लिखावट", "केवल गति", "कुछ नहीं"], "correct": "गणितीय समझ"}]});
STUDY_DATA[8].subjects['math'].lessons.push({"id": "c8-math-v72-3", "title": "चतुर्भुज के गुण", "icon": "➗", "content": "चतुर्भुज के चारों आंतरिक कोणों का योग 360° होता है। समांतर चतुर्भुज में विपरीत भुजाएँ और विपरीत कोण बराबर होते हैं। आयत में सभी कोण 90° होते हैं।\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "“चतुर्भुज के गुण” पाठ में किस बात को समझना है?", "options": ["गणितीय विचार और उसका उपयोग", "केवल नाम", "केवल चित्र", "केवल अनुमान"], "correct": "गणितीय विचार और उसका उपयोग"}, {"q": "गणित के सवाल में पहला अच्छा कदम क्या है?", "options": ["दिए गए मान और पूछा गया मान पहचानना", "बिना पढ़े उत्तर चुनना", "इकाई छोड़ देना", "सवाल बदल देना"], "correct": "दिए गए मान और पूछा गया मान पहचानना"}, {"q": "उत्तर की जाँच क्यों करनी चाहिए?", "options": ["गलती पकड़ने के लिए", "समय खराब करने के लिए", "सवाल हटाने के लिए", "किसी कारण के बिना"], "correct": "गलती पकड़ने के लिए"}, {"q": "कठिन सवाल को कैसे हल करना बेहतर है?", "options": ["उसे छोटे चरणों में बाँटकर", "सीधे अनुमान लगाकर", "प्रश्न छोड़कर", "केवल उत्तर देखकर"], "correct": "उसे छोटे चरणों में बाँटकर"}, {"q": "अभ्यास से क्या मजबूत होता है?", "options": ["गणितीय समझ", "सिर्फ लिखावट", "केवल गति", "कुछ नहीं"], "correct": "गणितीय समझ"}]});
STUDY_DATA[9].subjects['hindi'].lessons.push({"id": "c9-hindi-v72-1", "title": "उपसर्ग और प्रत्यय", "icon": "📚", "content": "जो शब्दांश किसी शब्द के आरंभ में जुड़कर अर्थ बदलता है वह उपसर्ग कहलाता है, जबकि अंत में जुड़ने वाला शब्दांश प्रत्यय कहलाता है। उदाहरणों को मूल शब्द से जोड़कर समझना सबसे आसान तरीका है।\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "“उपसर्ग और प्रत्यय” पाठ का मुख्य उद्देश्य क्या है?", "options": ["विषय को समझना", "केवल कहानी सुनना", "केवल चित्र बनाना", "केवल याद करना"], "correct": "विषय को समझना"}, {"q": "अच्छा उत्तर लिखते समय क्या जरूरी है?", "options": ["विषय के अनुसार स्पष्ट उत्तर", "बिना पढ़े अनुमान", "असंबंधित बातें", "केवल एक शब्द"], "correct": "विषय के अनुसार स्पष्ट उत्तर"}, {"q": "अभ्यास से क्या लाभ होता है?", "options": ["समझ और याददाश्त मजबूत होती है", "पढ़ाई रुक जाती है", "गलती हमेशा बढ़ती है", "कोई लाभ नहीं"], "correct": "समझ और याददाश्त मजबूत होती है"}, {"q": "नया पाठ सीखने का अच्छा क्रम कौन सा है?", "options": ["समझो → उदाहरण → अभ्यास", "पहले उत्तर रटें", "केवल शीर्षक पढ़ें", "अभ्यास छोड़ दें"], "correct": "समझो → उदाहरण → अभ्यास"}, {"q": "पाठ पूरा करने के बाद क्या करना उपयोगी है?", "options": ["अपने शब्दों में दोहराना", "बिना देखे छोड़ देना", "सवाल हटाना", "पढ़ना बंद करना"], "correct": "अपने शब्दों में दोहराना"}]});
STUDY_DATA[9].subjects['hindi'].lessons.push({"id": "c9-hindi-v72-2", "title": "तर्कपूर्ण लेखन", "icon": "📚", "content": "तर्कपूर्ण लेखन में किसी विचार या दावे के साथ कारण और प्रमाण दिए जाते हैं। पहले विषय स्पष्ट करें, फिर पक्ष में कारण दें, संभव आपत्ति समझें और अंत में संतुलित निष्कर्ष लिखें।\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "“तर्कपूर्ण लेखन” पाठ का मुख्य उद्देश्य क्या है?", "options": ["विषय को समझना", "केवल कहानी सुनना", "केवल चित्र बनाना", "केवल याद करना"], "correct": "विषय को समझना"}, {"q": "अच्छा उत्तर लिखते समय क्या जरूरी है?", "options": ["विषय के अनुसार स्पष्ट उत्तर", "बिना पढ़े अनुमान", "असंबंधित बातें", "केवल एक शब्द"], "correct": "विषय के अनुसार स्पष्ट उत्तर"}, {"q": "अभ्यास से क्या लाभ होता है?", "options": ["समझ और याददाश्त मजबूत होती है", "पढ़ाई रुक जाती है", "गलती हमेशा बढ़ती है", "कोई लाभ नहीं"], "correct": "समझ और याददाश्त मजबूत होती है"}, {"q": "नया पाठ सीखने का अच्छा क्रम कौन सा है?", "options": ["समझो → उदाहरण → अभ्यास", "पहले उत्तर रटें", "केवल शीर्षक पढ़ें", "अभ्यास छोड़ दें"], "correct": "समझो → उदाहरण → अभ्यास"}, {"q": "पाठ पूरा करने के बाद क्या करना उपयोगी है?", "options": ["अपने शब्दों में दोहराना", "बिना देखे छोड़ देना", "सवाल हटाना", "पढ़ना बंद करना"], "correct": "अपने शब्दों में दोहराना"}]});
STUDY_DATA[9].subjects['hindi'].lessons.push({"id": "c9-hindi-v72-3", "title": "काव्य में भाव और बिंब", "icon": "📚", "content": "कविता केवल शब्दों का समूह नहीं है; उसमें भाव, कल्पना और चित्रात्मकता भी होती है। बिंब ऐसे शब्द या वर्णन हैं जो पाठक के मन में दृश्य या अनुभव की तस्वीर बना देते हैं।\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "“काव्य में भाव और बिंब” पाठ का मुख्य उद्देश्य क्या है?", "options": ["विषय को समझना", "केवल कहानी सुनना", "केवल चित्र बनाना", "केवल याद करना"], "correct": "विषय को समझना"}, {"q": "अच्छा उत्तर लिखते समय क्या जरूरी है?", "options": ["विषय के अनुसार स्पष्ट उत्तर", "बिना पढ़े अनुमान", "असंबंधित बातें", "केवल एक शब्द"], "correct": "विषय के अनुसार स्पष्ट उत्तर"}, {"q": "अभ्यास से क्या लाभ होता है?", "options": ["समझ और याददाश्त मजबूत होती है", "पढ़ाई रुक जाती है", "गलती हमेशा बढ़ती है", "कोई लाभ नहीं"], "correct": "समझ और याददाश्त मजबूत होती है"}, {"q": "नया पाठ सीखने का अच्छा क्रम कौन सा है?", "options": ["समझो → उदाहरण → अभ्यास", "पहले उत्तर रटें", "केवल शीर्षक पढ़ें", "अभ्यास छोड़ दें"], "correct": "समझो → उदाहरण → अभ्यास"}, {"q": "पाठ पूरा करने के बाद क्या करना उपयोगी है?", "options": ["अपने शब्दों में दोहराना", "बिना देखे छोड़ देना", "सवाल हटाना", "पढ़ना बंद करना"], "correct": "अपने शब्दों में दोहराना"}]});
STUDY_DATA[9].subjects['english'].lessons.push({"id": "c9-english-v72-1", "title": "Clauses and Sentence Structure", "icon": "🔤", "content": "A clause contains a subject and a verb. An independent clause can stand alone, while a dependent clause needs another clause to complete its meaning. Understanding clauses helps us write clear complex sentences.\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "What is the main focus of “Clauses and Sentence Structure”?", "options": ["Understanding the topic", "Only drawing", "Only memorising", "Skipping practice"], "correct": "Understanding the topic"}, {"q": "What makes an answer clear?", "options": ["It directly addresses the question", "It changes the topic", "It has no explanation", "It is only one random word"], "correct": "It directly addresses the question"}, {"q": "Why is practice useful?", "options": ["It strengthens understanding", "It removes learning", "It always creates errors", "It has no purpose"], "correct": "It strengthens understanding"}, {"q": "Which learning order is best?", "options": ["Understand → Example → Practice", "Guess → Skip → Finish", "Read title only", "Avoid practice"], "correct": "Understand → Example → Practice"}, {"q": "After a lesson, what is useful?", "options": ["Explain it in your own words", "Forget it immediately", "Delete the questions", "Stop reading forever"], "correct": "Explain it in your own words"}]});
STUDY_DATA[9].subjects['english'].lessons.push({"id": "c9-english-v72-2", "title": "Modals: Can, Could, Should, Must", "icon": "🔤", "content": "Modal verbs express ability, possibility, advice, or necessity. Can may show ability, could can show past ability or polite possibility, should gives advice, and must shows strong necessity.\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "What is the main focus of “Modals: Can, Could, Should, Must”?", "options": ["Understanding the topic", "Only drawing", "Only memorising", "Skipping practice"], "correct": "Understanding the topic"}, {"q": "What makes an answer clear?", "options": ["It directly addresses the question", "It changes the topic", "It has no explanation", "It is only one random word"], "correct": "It directly addresses the question"}, {"q": "Why is practice useful?", "options": ["It strengthens understanding", "It removes learning", "It always creates errors", "It has no purpose"], "correct": "It strengthens understanding"}, {"q": "Which learning order is best?", "options": ["Understand → Example → Practice", "Guess → Skip → Finish", "Read title only", "Avoid practice"], "correct": "Understand → Example → Practice"}, {"q": "After a lesson, what is useful?", "options": ["Explain it in your own words", "Forget it immediately", "Delete the questions", "Stop reading forever"], "correct": "Explain it in your own words"}]});
STUDY_DATA[9].subjects['english'].lessons.push({"id": "c9-english-v72-3", "title": "Formal Letter Structure", "icon": "🔤", "content": "A formal letter uses a clear purpose, suitable tone, and organized paragraphs. It generally includes sender details, date, receiver details, subject, salutation, body, closing, and name. The language should be polite and precise.\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "What is the main focus of “Formal Letter Structure”?", "options": ["Understanding the topic", "Only drawing", "Only memorising", "Skipping practice"], "correct": "Understanding the topic"}, {"q": "What makes an answer clear?", "options": ["It directly addresses the question", "It changes the topic", "It has no explanation", "It is only one random word"], "correct": "It directly addresses the question"}, {"q": "Why is practice useful?", "options": ["It strengthens understanding", "It removes learning", "It always creates errors", "It has no purpose"], "correct": "It strengthens understanding"}, {"q": "Which learning order is best?", "options": ["Understand → Example → Practice", "Guess → Skip → Finish", "Read title only", "Avoid practice"], "correct": "Understand → Example → Practice"}, {"q": "After a lesson, what is useful?", "options": ["Explain it in your own words", "Forget it immediately", "Delete the questions", "Stop reading forever"], "correct": "Explain it in your own words"}]});
STUDY_DATA[9].subjects['math'].lessons.push({"id": "c9-math-v72-1", "title": "बहुपद और उनके पद", "icon": "➗", "content": "बहुपद में चर और उनके घात वाले पद हो सकते हैं। 3x²+2x−5 में तीन पद हैं। पदों की डिग्री उनके चर की सबसे बड़ी घात से निर्धारित होती है। समान पदों को जोड़कर बहुपद को सरल किया जा सकता है।\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "“बहुपद और उनके पद” पाठ में किस बात को समझना है?", "options": ["गणितीय विचार और उसका उपयोग", "केवल नाम", "केवल चित्र", "केवल अनुमान"], "correct": "गणितीय विचार और उसका उपयोग"}, {"q": "गणित के सवाल में पहला अच्छा कदम क्या है?", "options": ["दिए गए मान और पूछा गया मान पहचानना", "बिना पढ़े उत्तर चुनना", "इकाई छोड़ देना", "सवाल बदल देना"], "correct": "दिए गए मान और पूछा गया मान पहचानना"}, {"q": "उत्तर की जाँच क्यों करनी चाहिए?", "options": ["गलती पकड़ने के लिए", "समय खराब करने के लिए", "सवाल हटाने के लिए", "किसी कारण के बिना"], "correct": "गलती पकड़ने के लिए"}, {"q": "कठिन सवाल को कैसे हल करना बेहतर है?", "options": ["उसे छोटे चरणों में बाँटकर", "सीधे अनुमान लगाकर", "प्रश्न छोड़कर", "केवल उत्तर देखकर"], "correct": "उसे छोटे चरणों में बाँटकर"}, {"q": "अभ्यास से क्या मजबूत होता है?", "options": ["गणितीय समझ", "सिर्फ लिखावट", "केवल गति", "कुछ नहीं"], "correct": "गणितीय समझ"}]});
STUDY_DATA[9].subjects['math'].lessons.push({"id": "c9-math-v72-2", "title": "निर्देशांक ज्यामिति की शुरुआत", "icon": "➗", "content": "निर्देशांक तल में क्षैतिज अक्ष x-अक्ष और ऊर्ध्वाधर अक्ष y-अक्ष कहलाता है। किसी बिंदु को (x,y) के रूप में लिखा जाता है; पहला मान x और दूसरा मान y बताता है।\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "“निर्देशांक ज्यामिति की शुरुआत” पाठ में किस बात को समझना है?", "options": ["गणितीय विचार और उसका उपयोग", "केवल नाम", "केवल चित्र", "केवल अनुमान"], "correct": "गणितीय विचार और उसका उपयोग"}, {"q": "गणित के सवाल में पहला अच्छा कदम क्या है?", "options": ["दिए गए मान और पूछा गया मान पहचानना", "बिना पढ़े उत्तर चुनना", "इकाई छोड़ देना", "सवाल बदल देना"], "correct": "दिए गए मान और पूछा गया मान पहचानना"}, {"q": "उत्तर की जाँच क्यों करनी चाहिए?", "options": ["गलती पकड़ने के लिए", "समय खराब करने के लिए", "सवाल हटाने के लिए", "किसी कारण के बिना"], "correct": "गलती पकड़ने के लिए"}, {"q": "कठिन सवाल को कैसे हल करना बेहतर है?", "options": ["उसे छोटे चरणों में बाँटकर", "सीधे अनुमान लगाकर", "प्रश्न छोड़कर", "केवल उत्तर देखकर"], "correct": "उसे छोटे चरणों में बाँटकर"}, {"q": "अभ्यास से क्या मजबूत होता है?", "options": ["गणितीय समझ", "सिर्फ लिखावट", "केवल गति", "कुछ नहीं"], "correct": "गणितीय समझ"}]});
STUDY_DATA[9].subjects['math'].lessons.push({"id": "c9-math-v72-3", "title": "सांख्यिकी: माध्य और माध्यिका", "icon": "➗", "content": "माध्य निकालने के लिए सभी मानों का योग करके कुल मानों की संख्या से भाग देते हैं। माध्यिका पाने के लिए आँकड़ों को क्रम में रखें और बीच का मान लें; सम संख्या होने पर बीच के दो मानों का औसत लिया जाता है।\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "“सांख्यिकी: माध्य और माध्यिका” पाठ में किस बात को समझना है?", "options": ["गणितीय विचार और उसका उपयोग", "केवल नाम", "केवल चित्र", "केवल अनुमान"], "correct": "गणितीय विचार और उसका उपयोग"}, {"q": "गणित के सवाल में पहला अच्छा कदम क्या है?", "options": ["दिए गए मान और पूछा गया मान पहचानना", "बिना पढ़े उत्तर चुनना", "इकाई छोड़ देना", "सवाल बदल देना"], "correct": "दिए गए मान और पूछा गया मान पहचानना"}, {"q": "उत्तर की जाँच क्यों करनी चाहिए?", "options": ["गलती पकड़ने के लिए", "समय खराब करने के लिए", "सवाल हटाने के लिए", "किसी कारण के बिना"], "correct": "गलती पकड़ने के लिए"}, {"q": "कठिन सवाल को कैसे हल करना बेहतर है?", "options": ["उसे छोटे चरणों में बाँटकर", "सीधे अनुमान लगाकर", "प्रश्न छोड़कर", "केवल उत्तर देखकर"], "correct": "उसे छोटे चरणों में बाँटकर"}, {"q": "अभ्यास से क्या मजबूत होता है?", "options": ["गणितीय समझ", "सिर्फ लिखावट", "केवल गति", "कुछ नहीं"], "correct": "गणितीय समझ"}]});
STUDY_DATA[10].subjects['hindi'].lessons.push({"id": "c10-hindi-v72-1", "title": "समास-विग्रह का अभ्यास", "icon": "📚", "content": "समास वाले शब्द को उसके विस्तृत रूप में खोलना समास-विग्रह कहलाता है। सही विग्रह से शब्दों के बीच का संबंध स्पष्ट होता है और समास का प्रकार पहचानने में मदद मिलती है।\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "“समास-विग्रह का अभ्यास” पाठ का मुख्य उद्देश्य क्या है?", "options": ["विषय को समझना", "केवल कहानी सुनना", "केवल चित्र बनाना", "केवल याद करना"], "correct": "विषय को समझना"}, {"q": "अच्छा उत्तर लिखते समय क्या जरूरी है?", "options": ["विषय के अनुसार स्पष्ट उत्तर", "बिना पढ़े अनुमान", "असंबंधित बातें", "केवल एक शब्द"], "correct": "विषय के अनुसार स्पष्ट उत्तर"}, {"q": "अभ्यास से क्या लाभ होता है?", "options": ["समझ और याददाश्त मजबूत होती है", "पढ़ाई रुक जाती है", "गलती हमेशा बढ़ती है", "कोई लाभ नहीं"], "correct": "समझ और याददाश्त मजबूत होती है"}, {"q": "नया पाठ सीखने का अच्छा क्रम कौन सा है?", "options": ["समझो → उदाहरण → अभ्यास", "पहले उत्तर रटें", "केवल शीर्षक पढ़ें", "अभ्यास छोड़ दें"], "correct": "समझो → उदाहरण → अभ्यास"}, {"q": "पाठ पूरा करने के बाद क्या करना उपयोगी है?", "options": ["अपने शब्दों में दोहराना", "बिना देखे छोड़ देना", "सवाल हटाना", "पढ़ना बंद करना"], "correct": "अपने शब्दों में दोहराना"}]});
STUDY_DATA[10].subjects['hindi'].lessons.push({"id": "c10-hindi-v72-2", "title": "अपठित गद्यांश की रणनीति", "icon": "📚", "content": "अपठित गद्यांश में पहले पूरे अनुच्छेद का अर्थ समझें, फिर प्रश्नों के लिए संबंधित पंक्तियाँ खोजें। उत्तर अपने शब्दों में और प्रश्न के अनुसार दें; केवल अनुमान से उत्तर न लिखें।\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "“अपठित गद्यांश की रणनीति” पाठ का मुख्य उद्देश्य क्या है?", "options": ["विषय को समझना", "केवल कहानी सुनना", "केवल चित्र बनाना", "केवल याद करना"], "correct": "विषय को समझना"}, {"q": "अच्छा उत्तर लिखते समय क्या जरूरी है?", "options": ["विषय के अनुसार स्पष्ट उत्तर", "बिना पढ़े अनुमान", "असंबंधित बातें", "केवल एक शब्द"], "correct": "विषय के अनुसार स्पष्ट उत्तर"}, {"q": "अभ्यास से क्या लाभ होता है?", "options": ["समझ और याददाश्त मजबूत होती है", "पढ़ाई रुक जाती है", "गलती हमेशा बढ़ती है", "कोई लाभ नहीं"], "correct": "समझ और याददाश्त मजबूत होती है"}, {"q": "नया पाठ सीखने का अच्छा क्रम कौन सा है?", "options": ["समझो → उदाहरण → अभ्यास", "पहले उत्तर रटें", "केवल शीर्षक पढ़ें", "अभ्यास छोड़ दें"], "correct": "समझो → उदाहरण → अभ्यास"}, {"q": "पाठ पूरा करने के बाद क्या करना उपयोगी है?", "options": ["अपने शब्दों में दोहराना", "बिना देखे छोड़ देना", "सवाल हटाना", "पढ़ना बंद करना"], "correct": "अपने शब्दों में दोहराना"}]});
STUDY_DATA[10].subjects['hindi'].lessons.push({"id": "c10-hindi-v72-3", "title": "लेखन में तर्क और उदाहरण", "icon": "📚", "content": "प्रभावी लेखन में विचार के साथ कारण और उपयुक्त उदाहरण होना चाहिए। भूमिका विषय स्पष्ट करती है, मुख्य भाग तर्क देता है और निष्कर्ष पूरे विचार को संक्षेप में बाँधता है।\n\nअभ्यास: पाठ को अपने शब्दों में समझाकर एक उदाहरण अपनी कॉपी में लिखें।", "quiz": [{"q": "“लेखन में तर्क और उदाहरण” पाठ का मुख्य उद्देश्य क्या है?", "options": ["विषय को समझना", "केवल कहानी सुनना", "केवल चित्र बनाना", "केवल याद करना"], "correct": "विषय को समझना"}, {"q": "अच्छा उत्तर लिखते समय क्या जरूरी है?", "options": ["विषय के अनुसार स्पष्ट उत्तर", "बिना पढ़े अनुमान", "असंबंधित बातें", "केवल एक शब्द"], "correct": "विषय के अनुसार स्पष्ट उत्तर"}, {"q": "अभ्यास से क्या लाभ होता है?", "options": ["समझ और याददाश्त मजबूत होती है", "पढ़ाई रुक जाती है", "गलती हमेशा बढ़ती है", "कोई लाभ नहीं"], "correct": "समझ और याददाश्त मजबूत होती है"}, {"q": "नया पाठ सीखने का अच्छा क्रम कौन सा है?", "options": ["समझो → उदाहरण → अभ्यास", "पहले उत्तर रटें", "केवल शीर्षक पढ़ें", "अभ्यास छोड़ दें"], "correct": "समझो → उदाहरण → अभ्यास"}, {"q": "पाठ पूरा करने के बाद क्या करना उपयोगी है?", "options": ["अपने शब्दों में दोहराना", "बिना देखे छोड़ देना", "सवाल हटाना", "पढ़ना बंद करना"], "correct": "अपने शब्दों में दोहराना"}]});
