function studySelectClass(cId){
  cId=String(cId);
  const selected=STUDY_DATA[cId];
  if(!selected){alert('⚠️ यह कक्षा अभी उपलब्ध नहीं है।');return;}
  studyState.classId=cId;
  studyState.subjectId=null;
  studyState.lessonId=null;
  studyState.qIndex=0;
  studyState.pageIndex=0;
  studyState.view='subjects';
  renderStudy();
  window.scrollTo({top:0,behavior:'smooth'});
}
function studySelectSubject(sId){studyState.subjectId=sId;studyState.view='lessons';renderStudy()}
function studySelectLesson(lId){studyState.lessonId=lId;studyState.view='page';studyState.pageIndex=0;studySaveLastLesson();renderStudy()}
function studyOpenPractice(){
  studyState.view='practice';
  studyState.qIndex=0;
  speechSynthesis.cancel();
  renderStudy();
}
function studyBackToLesson(){
  studyState.view='page';
  speechSynthesis.cancel();
  renderStudy();
}

function studyEndlessAnswer(opt){
  const l=endlessMakeLesson(studyState.classId,studyState.subjectId,studyState.endlessIndex||0),q=l.quiz[studyState.qIndex],res=document.getElementById('studyEndlessResult');
  if(opt===q.correct){if(res)res.textContent='🎉 बहुत बढ़िया! सही उत्तर है।';speakText('बहुत बढ़िया! सही उत्तर है।');studyState.qIndex++;setTimeout(renderStudy,700)}else{if(res)res.textContent='फिर से कोशिश करें।';speakText('फिर से कोशिश करें।')}
}

function studyMarkComplete(){
  const l=studyLessonById(studyState.lessonId);
  const p=studyProgress();
  if(!p[l.id]){
    p[l.id]=true;studySaveProgress(p);
    addStar();
    const st=document.getElementById('stars');if(st)st.textContent='⭐ '+score;
    const pt=document.getElementById('progressText');if(pt)pt.textContent='शाबाश! "'+l.title+'" पाठ पूरा हुआ।';
    speakText('शाबाश! पाठ पूरा हुआ।');
  }
  renderStudy();
}

function studyPracticeAnswer(opt){
  const l=studyLessonById(studyState.lessonId);
  const q=l.quiz[studyState.qIndex];
  const res=document.getElementById('studyPracticeResult');
  if(opt===q.correct){
    if(res){res.textContent='🎉 बहुत बढ़िया! सही उत्तर है।';res.style.color='#1f9d55'}
    speakText('बहुत बढ़िया! सही उत्तर है।');
    studyState.qIndex++;
    setTimeout(renderStudy,900);
  }else{
    if(res){res.textContent='फिर से कोशिश करें।';res.style.color='#c0392b'}
    speakText('फिर से कोशिश करें।');
  }
}

function studyGoBack(){
  speechSynthesis.cancel();
  if(studyState.view==='endlessPractice'){studyState.view='endlessLesson'}
  else if(studyState.view==='endlessLesson'){studyState.view='endlessSubjects'}
  else if(studyState.view==='endlessSubjects'){studyState.view='subjects'}
  else if(studyState.view==='video'){studyState.view='page'}
  else if(studyState.view==='practice'){studyState.view='page'}
  else if(studyState.view==='page'){studyState.view='lessons'}
  else if(studyState.view==='lessons'){studyState.view='subjects'}
  else if(studyState.view==='subjects'){studyState.view='classes'}
  else { return; }
  renderStudy();
}
