function storyIconSvg(key){
  const inner=ICONS[key];
  if(!inner)return '';
  return `<svg viewBox="0 0 100 100">${inner}</svg>`;
}
function storyIconsHtml(keys){
  const n=Math.min(4,keys.length)||1;
  return keys.map(k=>{
    const svg=storyIconSvg(k);
    if(!svg)return '';
    return `<div class="storyIconWrap n${n}"><svg class="storyIcon" viewBox="0 0 100 100">${ICONS[k]}</svg><div class="storyIconShadow"></div></div>`;
  }).join('');
}
