let psSpeechTimer = null;
let psLastText = '';
let psLastAt = 0;
let speechSpeed = 0.82; try{ speechSpeed = parseFloat(localStorage.getItem('pathshalaSpeechSpeed') || '0.82'); }catch(e){ speechSpeed = 0.82; }
function setSpeechSpeed(value){ speechSpeed=parseFloat(value)||0.82; localStorage.setItem('pathshalaSpeechSpeed',String(speechSpeed)); }

let voiceEnabled = true; try{ voiceEnabled = localStorage.getItem('pathshalaVoiceEnabled') !== 'false'; }catch(e){ voiceEnabled = true; }
function setDarkMode(on){
  document.body.classList.toggle('darkTheme', !!on);
  try{ localStorage.setItem('pathshalaDarkMode', on?'1':'0'); }catch(e){}
  const lbl=document.getElementById('darkModeLabel'); if(lbl) lbl.textContent = on?'चालू':'बंद'; const qd=document.getElementById('settingsQuickDark'); if(qd) qd.textContent=on?'चालू':'बंद';
  const toggle=document.getElementById('darkModeToggle'); if(toggle) toggle.checked = !!on;
}
function setVoiceEnabled(val){
  voiceEnabled = !!val;
  localStorage.setItem('pathshalaVoiceEnabled', voiceEnabled ? 'true' : 'false');
  if(!voiceEnabled && 'speechSynthesis' in window) window.speechSynthesis.cancel();
  const lbl=document.getElementById('voiceEnabledLabel'); if(lbl) lbl.textContent = voiceEnabled ? 'चालू' : 'बंद';
  const tog=document.getElementById('voiceEnabledToggle'); if(tog) tog.checked = voiceEnabled;
  const l=document.getElementById('voiceLanguage'); const qv=document.getElementById('settingsQuickVoice'); if(qv) qv.textContent=voiceEnabled?'चालू':'बंद'; const st=document.getElementById('voiceStatus');
  if(st && l) st.textContent = (voiceEnabled?'आवाज़ चालू • ':'आवाज़ बंद • ')+'भाषा: '+l.options[l.selectedIndex].text;
}
function syncSettingsUI(){ const l=document.getElementById('voiceLanguage'), s=document.getElementById('speechSpeed'); if(l) l.value=selectedVoiceLanguage; if(s) s.value=String(speechSpeed); const tog=document.getElementById('voiceEnabledToggle'); if(tog) tog.checked=voiceEnabled; const lbl=document.getElementById('voiceEnabledLabel'); if(lbl) lbl.textContent=voiceEnabled?'चालू':'बंद'; const st=document.getElementById('voiceStatus'); if(st && l) st.textContent=(voiceEnabled?'आवाज़ चालू • ':'आवाज़ बंद • ')+'भाषा: '+l.options[l.selectedIndex].text; const qv=document.getElementById('settingsQuickVoice'); if(qv) qv.textContent=voiceEnabled?'चालू':'बंद'; const ql=document.getElementById('settingsQuickLanguage'); if(ql && l) ql.textContent=l.value==='en-IN'?'English':'हिंदी'; const qd=document.getElementById('settingsQuickDark'); if(qd) qd.textContent=document.body.classList.contains('darkTheme')?'चालू':'बंद'; }
function testCurrentVoice(){ psSpeakRaw(selectedVoiceLanguage==='en-IN'?'Hello. This is the Pathshala voice test.':'नमस्ते। यह पाठशाला की आवाज़ की जाँच है।'); }

function psGetLanguage(){
  const sel = document.getElementById('voiceLanguage');
  return (sel && sel.value) || localStorage.getItem('pathshalaVoiceLanguage') || 'hi-IN';
}

function psSpeak(text, lang, onEnd){
  if(!voiceEnabled) return false;
  psSpeakRaw(text, lang, onEnd);
  return true;
}

function psGetBestVoice(useLang){
  const voices = window.speechSynthesis.getVoices();
  if(!voices || !voices.length) return null;
  const base = useLang.toLowerCase().split('-')[0];
  return voices.find(v => (v.lang||'').toLowerCase() === useLang.toLowerCase())
    || voices.find(v => (v.lang||'').toLowerCase().startsWith(base))
    || voices.find(v => (v.lang||'').toLowerCase().startsWith('hi'))
    || voices.find(v => (v.lang||'').toLowerCase().startsWith('en'))
    || voices[0];
}

function psSpeakRaw(text, lang, onEnd){
  if(text === undefined || text === null) return;
  const clean = String(text).replace(/\s+/g,' ').trim();
  if(!clean || !('speechSynthesis' in window)) return;

  const useLang = lang || psGetLanguage();
  const now = Date.now();

  // एक ही tap से आई duplicate call रोकें, लेकिन वही चीज़ बाद में फिर दबाने पर बोले।
  if(clean === psLastText && now - psLastAt < 120) return;
  psLastText = clean;
  psLastAt = now;

  try{
    window.speechSynthesis.cancel();
    if(psSpeechTimer) clearTimeout(psSpeechTimer);

    psSpeechTimer = setTimeout(function(){
      const utter = new SpeechSynthesisUtterance(clean);
      utter.lang = useLang;
      utter.rate = Math.min(speechSpeed, 0.78);
      utter.pitch = 1.12;
      utter.volume = 1;

      const voice = psGetBestVoice(useLang);
      if(voice) utter.voice = voice;
      if(onEnd){ utter.onend = onEnd; utter.onerror = onEnd; }

      window.speechSynthesis.speak(utter);
    }, 90);
  }catch(e){}
}

function speak(text){ psSpeak(text); }
function speakText(text, lang, onEnd){ return psSpeak(text, lang, onEnd); }
function speakEnglishOnce(text){ psSpeak(text); }
function speakEnglishCurrent(){
  const x = eng[ei];
  if(x) psSpeak(x[0] + ' for ' + x[1]);
}


// ===== चैट स्क्रीन की त्वरित रिकॉर्डिंग =====
let inlineRecording=false, inlineRecordTimerId=null, inlineRecordStartedAt=0;
function updateInlineRecordUI(){
  const b=document.getElementById('inlineRecordBtn'), st=document.getElementById('inlineRecordState'), tm=document.getElementById('inlineRecordTimer');
  if(!b||!st)return;
  if(inlineRecording){ b.textContent='⏹️ रिकॉर्डिंग बंद करें'; b.classList.add('recording'); st.textContent='🔴 रिकॉर्डिंग चालू है… पढ़ें, बोलें या गाएँ'; }
  else { b.textContent='🔴 रिकॉर्डिंग चालू'; b.classList.remove('recording'); st.textContent='🎙️ रिकॉर्डिंग बंद'; if(tm)tm.textContent='00:00'; }
}
async function toggleInlineRecording(){
  if(inlineRecording){ await stopInlineRecording(); } else { await startInlineRecording(); }
}
async function startInlineRecording(){
  if(typeof startVoiceRecording!=='function'){alert('रिकॉर्डिंग सुविधा उपलब्ध नहीं है।');return;}
  try{
    await startVoiceRecording();
    if(!mediaRecorder || mediaRecorder.state!=='recording') return;
    inlineRecording=true; inlineRecordStartedAt=Date.now(); clearInterval(inlineRecordTimerId);
    inlineRecordTimerId=setInterval(()=>{const el=document.getElementById('inlineRecordTimer');if(el)el.textContent=formatRecordTime(Date.now()-inlineRecordStartedAt)},250);
    updateInlineRecordUI();
  }catch(e){
    inlineRecording=false; clearInterval(inlineRecordTimerId); inlineRecordTimerId=null; updateInlineRecordUI();
  }
}
async function stopInlineRecording(){
  if(!inlineRecording)return;
  inlineRecording=false; clearInterval(inlineRecordTimerId); inlineRecordTimerId=null;
  await stopVoiceRecording(); updateInlineRecordUI();
  const el=document.getElementById('inlineRecordSaved'); if(el)el.innerHTML='<div class="recordStatus">✅ रिकॉर्डिंग सेव हो गई। इसे बाद में ⚙️ सेटिंग्स → मेरी रिकॉर्डिंग में भी सुन सकते हैं।</div>' ;
}

// ===== मेरी आवाज़ की रिकॉर्डिंग =====
const RECORD_DB_NAME='pathshalaRecordingsDB';
const RECORD_STORE='recordings';
let recordDB=null, mediaRecorder=null, recordChunks=[], recordStartedAt=0, recordTimerId=null, recordStream=null;
function openRecordDB(){
  return new Promise((resolve,reject)=>{
    if(!('indexedDB' in window)){reject(new Error('IndexedDB उपलब्ध नहीं है'));return;}
    if(recordDB){resolve(recordDB);return;}
    const req=indexedDB.open(RECORD_DB_NAME,1);
    req.onupgradeneeded=e=>{const db=e.target.result;if(!db.objectStoreNames.contains(RECORD_STORE)){const st=db.createObjectStore(RECORD_STORE,{keyPath:'id',autoIncrement:true});st.createIndex('createdAt','createdAt',{unique:false});}};
    req.onsuccess=e=>{recordDB=e.target.result;resolve(recordDB)};
    req.onerror=()=>reject(req.error||new Error('रिकॉर्डिंग स्टोरेज नहीं खुला'));
  });
}
function formatRecordTime(ms){const sec=Math.floor(ms/1000);return String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0')}
function setRecordStatus(t){const el=document.getElementById('recordStatus');if(el)el.textContent=t}
function startRecordTimer(){clearInterval(recordTimerId);recordStartedAt=Date.now();const el=document.getElementById('recordTimer');recordTimerId=setInterval(()=>{if(el)el.textContent=formatRecordTime(Date.now()-recordStartedAt)},250)}
function stopRecordTimer(){clearInterval(recordTimerId);recordTimerId=null}
function chooseRecordMime(){const opts=['audio/webm;codecs=opus','audio/webm','audio/mp4','audio/ogg;codecs=opus'];return opts.find(x=>MediaRecorder.isTypeSupported && MediaRecorder.isTypeSupported(x))||''}
async function startVoiceRecording(){
  if(mediaRecorder && mediaRecorder.state==='recording')return;
  if(!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia || !window.MediaRecorder){setRecordStatus('⚠️ इस ब्राउज़र में ऑडियो रिकॉर्डिंग उपलब्ध नहीं है। Chrome में कोशिश करें।');return;}
  try{
    await openRecordDB();
    recordStream=await navigator.mediaDevices.getUserMedia({audio:true});
    const mime=chooseRecordMime();
    mediaRecorder=mime?new MediaRecorder(recordStream,{mimeType:mime}):new MediaRecorder(recordStream);
    recordChunks=[];
    mediaRecorder.ondataavailable=e=>{if(e.data&&e.data.size)recordChunks.push(e.data)};
    mediaRecorder.onerror=()=>{setRecordStatus('⚠️ रिकॉर्डिंग में समस्या हुई।');stopVoiceRecording(true)};
    mediaRecorder.onstop=saveVoiceRecording;
    mediaRecorder.start(250);
    startRecordTimer();
    setRecordStatus('🔴 रिकॉर्डिंग चल रही है… पढ़ें, बोलें या गाएँ।');
    const a=document.getElementById('recordStartBtn'),b=document.getElementById('recordStopBtn');if(a)a.disabled=true;if(b)b.disabled=false;
  }catch(e){setRecordStatus(e && e.name==='NotAllowedError'?'⚠️ माइक्रोफोन की अनुमति नहीं मिली। ब्राउज़र में अनुमति दें।':'⚠️ माइक्रोफोन शुरू नहीं हो सका।');}
}
function stopVoiceRecording(errorStop){
  stopRecordTimer();
  if(recordStream){recordStream.getTracks().forEach(t=>t.stop());recordStream=null;}
  if(mediaRecorder && mediaRecorder.state!=='inactive')mediaRecorder.stop();
  const a=document.getElementById('recordStartBtn'),b=document.getElementById('recordStopBtn');if(a)a.disabled=false;if(b)b.disabled=true;
  if(!errorStop && mediaRecorder && mediaRecorder.state==='inactive')setRecordStatus('💾 रिकॉर्डिंग सेव हो रही है…');
}
async function saveVoiceRecording(){
  const duration=Date.now()-recordStartedAt;
  if(!recordChunks.length){setRecordStatus('⚠️ कोई आवाज़ रिकॉर्ड नहीं हुई।');mediaRecorder=null;return;}
  try{
    const mime=(mediaRecorder&&mediaRecorder.mimeType)||'audio/webm';
    const blob=new Blob(recordChunks,{type:mime});
    const db=await openRecordDB();
    const name='मेरी रिकॉर्डिंग — '+new Date().toLocaleString('hi-IN');
    await new Promise((resolve,reject)=>{const tx=db.transaction(RECORD_STORE,'readwrite');tx.objectStore(RECORD_STORE).add({name,createdAt:Date.now(),duration,blob,type:mime});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||new Error('save failed'));});
    setRecordStatus('✅ रिकॉर्डिंग सेव हो गई। नीचे से बाद में फिर सुन सकते हैं।');
    recordChunks=[];mediaRecorder=null;document.getElementById('recordTimer').textContent='00:00';renderRecordings();
  }catch(e){setRecordStatus('⚠️ रिकॉर्डिंग सेव नहीं हो सकी। ब्राउज़र का स्टोरेज उपलब्ध है या नहीं जाँचें।');mediaRecorder=null;}
}
async function getAllRecordings(){const db=await openRecordDB();return new Promise((resolve,reject)=>{const req=db.transaction(RECORD_STORE,'readonly').objectStore(RECORD_STORE).getAll();req.onsuccess=()=>resolve((req.result||[]).sort((a,b)=>b.createdAt-a.createdAt));req.onerror=()=>reject(req.error);})}
let activeRecordAudio=null, activeRecordUrl=null;
async function playSavedRecording(id,btn){
  try{
    if(activeRecordAudio){try{activeRecordAudio.pause()}catch(_){} activeRecordAudio=null;}
    if(activeRecordUrl){URL.revokeObjectURL(activeRecordUrl);activeRecordUrl=null;}
    const db=await openRecordDB();
    const row=await new Promise((resolve,reject)=>{const tx=db.transaction(RECORD_STORE,'readonly');const req=tx.objectStore(RECORD_STORE).get(id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});
    if(!row||!row.blob){setRecordStatus('⚠️ यह रिकॉर्डिंग उपलब्ध नहीं है।');return;}
    activeRecordUrl=URL.createObjectURL(row.blob);
    activeRecordAudio=new Audio(activeRecordUrl);
    activeRecordAudio.preload='auto';
    activeRecordAudio.onended=()=>{if(btn)btn.textContent='▶️ फिर से सुनें';};
    activeRecordAudio.onerror=()=>{if(btn)btn.textContent='▶️ फिर से सुनें';setRecordStatus('⚠️ यह ऑडियो इस ब्राउज़र में नहीं चल पा रहा। ऑनलाइन Chrome में फिर कोशिश करें।');};
    await activeRecordAudio.play();
    if(btn)btn.textContent='⏸️ सुनना रोकें';
    activeRecordAudio.onpause=()=>{if(btn)btn.textContent='▶️ फिर से सुनें';};
  }catch(e){if(btn)btn.textContent='▶️ फिर से सुनें';setRecordStatus('⚠️ रिकॉर्डिंग चल नहीं पाई। Chrome में अनुमति/ऑडियो सपोर्ट जाँचें।');}
}
async function renderRecordings(){const box=document.getElementById('recordingsList');if(!box)return;try{const rows=await getAllRecordings();if(!rows.length){box.innerHTML='<div class="recordStatus">अभी कोई रिकॉर्डिंग सेव नहीं है।</div>';return;}box.innerHTML='<h3 style="margin:14px 0 6px">🎧 सेव की गई रिकॉर्डिंग</h3>'+rows.map(r=>{const url=URL.createObjectURL(r.blob);return `<div class="recordItem"><div class="recordItemTitle">${escapeHtmlRecord(r.name)}</div><div class="recordMeta">${formatRecordTime(r.duration)} • ${new Date(r.createdAt).toLocaleString('hi-IN')}</div><audio controls preload="metadata" src="${url}"></audio><button class="settingsBtn" style="margin-top:8px" onclick="playSavedRecording(${r.id},this)">▶️ फिर से सुनें</button><button class="recordDelete" onclick="deleteRecording(${r.id})">🗑️ यह रिकॉर्डिंग हटाएँ</button></div>`}).join('');}catch(e){box.innerHTML='<div class="warning">⚠️ सेव की गई रिकॉर्डिंग अभी नहीं दिखाई जा सकीं।</div>'}}
function escapeHtmlRecord(v){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
async function deleteRecording(id){if(!confirm('क्या यह रिकॉर्डिंग हटानी है?'))return;try{const db=await openRecordDB();await new Promise((resolve,reject)=>{const tx=db.transaction(RECORD_STORE,'readwrite');tx.objectStore(RECORD_STORE).delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});renderRecordings();setRecordStatus('🗑️ रिकॉर्डिंग हटा दी गई।')}catch(e){setRecordStatus('⚠️ रिकॉर्डिंग हटाई नहीं जा सकी।')}}

document.addEventListener('DOMContentLoaded', function(){
  renderStreakUI();
  const sel=document.getElementById('voiceLanguage');
  if(sel) sel.value=selectedVoiceLanguage;
  const sp=document.getElementById('speechSpeed'); if(sp) sp.value=String(speechSpeed);
  const tog=document.getElementById('voiceEnabledToggle'); if(tog) tog.checked=voiceEnabled;
  const lbl=document.getElementById('voiceEnabledLabel'); if(lbl) lbl.textContent=voiceEnabled?'चालू':'बंद';
  const st=document.getElementById('voiceStatus'); if(st && sel) st.textContent=(voiceEnabled?'आवाज़ चालू • ':'आवाज़ बंद • ')+'भाषा: '+sel.options[sel.selectedIndex].text;
  if('speechSynthesis' in window){
    window.speechSynthesis.getVoices();
    window.speechSynthesis.addEventListener('voiceschanged', function(){ window.speechSynthesis.getVoices(); });
  }
});

// ===== बातचीत करके पढ़ाई / Voice Tutor =====
let tutorRecognition=null;
let tutorLastTopic='';
function openTutorDirect(){
  openPage('onlineStudy');
  setTimeout(()=>{const inp=document.getElementById('tutorInput'); if(inp){inp.focus(); inp.scrollIntoView({behavior:'smooth',block:'center'});}},180);
}
function clearTutorChat(){
  const box=document.getElementById('tutorChatBox');
  if(box){box.innerHTML=''; box.dataset.ready='';}
  tutorLastTopic='';
  initTutor();
  setTimeout(()=>document.getElementById('tutorInput')?.focus(),80);
}
function numberWordSmall(n){
  const a=['शून्य','एक','दो','तीन','चार','पाँच','छह','सात','आठ','नौ','दस','ग्यारह','बारह','तेरह','चौदह','पंद्रह','सोलह','सत्रह','अठारह','उन्नीस','बीस'];
  return a[n] ?? String(n);
}
function tutorAdd(role,text){
  const box=document.getElementById('tutorChatBox'); if(!box)return;
  const div=document.createElement('div'); div.className='chatMsg '+(role==='user'?'chatUser':'chatBot');
  div.textContent=text; box.appendChild(div); box.scrollTop=box.scrollHeight;
}
async function tutorAnswer(q){
  const raw=(q||'').trim();
  if(!raw) return 'अपना सवाल लिखिए या 🎤 दबाकर बोलिए।';
  const hindiDigits='०१२३४५६७८९';
  const norm=raw.replace(/[०-९]/g,ch=>String(hindiDigits.indexOf(ch)))
    .replace(/[“”‘’]/g,'').replace(/[।?？!！,，]/g,' ')
    .replace(/\s+/g,' ').trim().toLowerCase();
  const t=norm;

  // छोटे follow-up सवाल पिछली बात से जुड़े रहें।
  if(/^(और|फिर|आगे|इसके बाद|और बताओ|और बताइए)$/i.test(t) && tutorLastTopic){
    return 'ज़रूर 😊 हम अभी '+tutorLastTopic+' की बात कर रहे थे। आप चाहें तो मैं इसे और आसान तरीके से समझाऊँ।';
  }

  // गणित के सीधे सवाल।
  let m=norm.match(/(\d+)\s*[+＋]\s*(\d+)/) || norm.match(/(\d+)\s*(?:जोड़|जमा|plus)\s*(\d+)/i);
  if(m) return 'जवाब: '+(Number(m[1])+Number(m[2]))+'।';
  m=norm.match(/(\d+)\s*[-−]\s*(\d+)/) || norm.match(/(\d+)\s*(?:घटाओ|घटाव|minus)\s*(\d+)/i);
  if(m) return 'जवाब: '+(Number(m[1])-Number(m[2]))+'।';
  m=norm.match(/(\d+)\s*[×x*]\s*(\d+)/i) || norm.match(/(\d+)\s*(?:गुणा|times)\s*(\d+)/i);
  if(m) return 'जवाब: '+(Number(m[1])*Number(m[2]))+'।';
  m=norm.match(/(\d+)\s*[÷/]\s*(\d+)/) || norm.match(/(\d+)\s*(?:भाग|divide)\s*(\d+)/i);
  if(m && Number(m[2])!==0) return 'जवाब: '+(Number(m[1])/Number(m[2]))+'।';

  // गिनती।
  if(t.includes('गिनती')||t.includes('count')){
    let limit=20;
    const lm=norm.match(/(?:तक|to)\s*(\d{1,3})/);
    if(lm) limit=Math.min(100,Math.max(1,Number(lm[1])));
    tutorLastTopic='गिनती';
    return 'चलो '+limit+' तक गिनते हैं: '+Array.from({length:limit},(_,i)=>i+1).join(', ')+'।';
  }
  let after=norm.match(/(\d+)\s*(?:के बाद|बाद|after)/);
  if(after) return Number(after[1])+1+' आता है।';
  let before=norm.match(/(\d+)\s*(?:से पहले|के पहले|पहले|before)/);
  if(before) return Number(before[1])-1+' आता है।';

  if(/^(नमस्ते|हेलो|hello|hi|हाय)/i.test(t)) return 'नमस्ते! 😊 जो पूछना हो सीधे पूछिए।';
  if(/कैसे हो|कैसी हो|how are you/i.test(t)) return 'मैं बढ़िया हूँ 😊 आपकी पढ़ाई में मदद करने के लिए तैयार हूँ।';
  if(/धन्यवाद|शुक्रिया|thanks|thank you/i.test(t)) return 'आपका स्वागत है! 😊 अगला सवाल पूछिए।';
  if(/तुम कौन|आप कौन|who are you/i.test(t)) return 'मैं पाठशाला का पढ़ाई सहायक हूँ। आप किसी व्यक्ति, जगह, विषय या पढ़ाई के बारे में सवाल पूछ सकते हैं।';

  if(t.includes('संज्ञा')){ tutorLastTopic='संज्ञा'; return 'संज्ञा किसी व्यक्ति, वस्तु, स्थान या भाव के नाम को कहते हैं। जैसे राम, किताब और दिल्ली।'; }
  if(t.includes('सर्वनाम')){ tutorLastTopic='सर्वनाम'; return 'संज्ञा के स्थान पर आने वाले शब्द सर्वनाम कहलाते हैं। जैसे वह, यह और हम।'; }
  if(t.includes('भिन्न')||t.includes('fraction')){ tutorLastTopic='भिन्न'; return 'भिन्न किसी पूरे के बराबर हिस्से को दिखाती है। जैसे 4 बराबर हिस्सों में 1 हिस्सा = 1/4।'; }
  if(t.includes('प्रतिशत')||t.includes('percentage')){ tutorLastTopic='प्रतिशत'; return 'प्रतिशत का मतलब है प्रति सौ। 100 में 50 सही हों तो 50 प्रतिशत।'; }
  if(t.includes('पहाड़ा')||t.includes('table')){
    tutorLastTopic='पहाड़ा';
    const tm=norm.match(/(\d+)\s*(?:का|की|के)?\s*(?:पहाड़ा|table)/);
    if(tm){const n=Number(tm[1]); return n+' का पहाड़ा: '+Array.from({length:10},(_,i)=>n+' × '+(i+1)+' = '+n*(i+1)).join('। ')+ '।';}
    return 'जिस संख्या का पहाड़ा चाहिए, उसका नाम बताइए। जैसे “7 का पहाड़ा”।';
  }
  if(t.includes('कहानी')){ tutorLastTopic='कहानी'; return 'कहानी का नाम बताइए। मैं उसी कहानी के बारे में बताने की कोशिश करूँगा।'; }

  // पहले Pathshala के अपने पाठ खोजें — सही विषय का सही जवाब मिले, इसके लिए शब्द-सीमा जाँच और सबसे नज़दीकी मेल चुनते हैं (सिर्फ़ पहला मेल नहीं)।
  try{
    const all=[];
    Object.keys(STUDY_DATA||{}).forEach(c=>Object.keys(STUDY_DATA[c].subjects||{}).forEach(s=>((STUDY_DATA[c].subjects[s].lessons)||[]).forEach(l=>all.push(l))));
    const stop=/^(क्या|कौन|क्यों|कैसे|बताओ|बताइए|के|का|की|है|हैं|में|पर|बारे|किसे|कहते|about|what|who|why|how|is|are|the)$/i;
    const words=[...new Set(t.split(/\s+/).filter(w=>w.length>1 && !stop.test(w)))];
    if(words.length){
      // शब्द-सीमा (word boundary) से मिलान करें ताकि "उदय" जैसे छोटे शब्द किसी दूसरे बड़े शब्द के अंदर से झूठा मेल न खाएँ (जैसे सूर्योदय)
      const escRe=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
      let best=null, bestScore=-1;
      for(const l of all){
        const title=String(l.title||'').toLowerCase();
        const body=String(l.content||'').toLowerCase();
        // पूरा शीर्षक ही सवाल के अंदर मौजूद हो तो यह सबसे पक्का मेल है
        if(title.length>1 && t.includes(title)){ best=l; bestScore=1000; break; }
        let score=0;
        for(const w of words){
          const re=new RegExp('(^|[^\\p{L}\\p{N}])'+escRe(w)+'($|[^\\p{L}\\p{N}])','iu');
          if(re.test(' '+title+' ')) score+=5;      // शीर्षक में मिलना ज़्यादा भरोसेमंद
          else if(re.test(' '+body+' ')) score+=1;  // पाठ के अंदर मिलना कम भरोसेमंद
        }
        if(score>bestScore){ bestScore=score; best=l; }
      }
      if(best && bestScore>0){ tutorLastTopic=best.title; return best.title+'। '+best.content; }
    }
  }catch(e){}

  // सामान्य व्यक्ति/कैरेक्टर/जगह/विषय के लिए इंटरनेट पर उसी विषय को खोजें।
  // कोई API key ऐप में नहीं रखी गई है।
  async function wikiSummary(lang, query){
    const search='https://'+lang+'.wikipedia.org/w/api.php?action=query&list=search&srsearch='+encodeURIComponent(query)+'&utf8=1&format=json&origin=*';
    const r=await fetch(search,{cache:'no-store'});
    if(!r.ok) return null;
    const d=await r.json();
    const items=d && d.query && d.query.search ? d.query.search : [];
    if(!items.length) return null;
    const title=items[0].title;
    const sum='https://'+lang+'.wikipedia.org/api/rest_v1/page/summary/'+encodeURIComponent(title);
    const sr=await fetch(sum,{cache:'no-store'});
    if(!sr.ok) return null;
    const sd=await sr.json();
    if(!sd.extract) return null;
    return sd.extract+'\n\n📚 विषय: '+title+'।';
  }

  if(navigator.onLine){
    try{
      const hi=await wikiSummary('hi',raw);
      if(hi){ tutorLastTopic=raw; return hi; }
      const en=await wikiSummary('en',raw);
      if(en){ tutorLastTopic=raw; return en; }
    }catch(e){}
    return 'इस सवाल का सही उत्तर पाने में अभी दिक्कत हुई। इंटरनेट चालू रखकर वही सवाल एक बार फिर पूछिए।';
  }
  return 'यह सवाल मेरे अभी के ऑफलाइन पाठों में नहीं है। इंटरनेट चालू करके यही सवाल फिर पूछिए।';
}
function tutorQuick(q){const inp=document.getElementById('tutorInput');if(inp)inp.value=q;sendTutorMessage();}
async function sendTutorMessage(){
  const inp=document.getElementById('tutorInput'); if(!inp)return;
  const q=inp.value.trim(); if(!q)return;
  tutorAdd('user',q); inp.value='';
  const status=document.getElementById('tutorStatus'); if(status)status.textContent='🟡 जवाब तैयार हो रहा है…';
  try{
    const a=await tutorAnswer(q);
    tutorAdd('bot',a);
    if(status)status.textContent='🟢 अगला सवाल पूछिए।';
    if(voiceEnabled)speakText(a);
  }catch(e){
    tutorAdd('bot','⚠️ जवाब तैयार नहीं हो पाया। सवाल फिर से पूछिए।');
    if(status)status.textContent='🟢 अगला सवाल पूछिए।';
  }
}
function startTutorVoice(){
  const btn=document.getElementById('tutorMicBtn');
  const status=document.getElementById('tutorStatus');
  const SR=window.SpeechRecognition||window.webkitSpeechRecognition;

  if(!SR){
    if(status)status.textContent='⚠️ इस Chrome में बोलकर सवाल उपलब्ध नहीं है। Chrome को अपडेट करके HTTPS लिंक में खोलें।';
    return;
  }

  try{
    if(tutorRecognition){try{tutorRecognition.abort();}catch(e){} tutorRecognition=null;}

    const rec=new SR();
    tutorRecognition=rec;
    rec.lang=selectedVoiceLanguage||'hi-IN';
    rec.interimResults=false;
    rec.continuous=false;
    rec.maxAlternatives=1;

    if(btn){btn.disabled=false;btn.textContent='🎙️';}
    if(status)status.textContent='🎙️ सुन रहा हूँ… अब सीधे बोलिए।';

    rec.onstart=function(){
      if(status)status.textContent='🎙️ सुन रहा हूँ… अब सीधे बोलिए।';
    };

    rec.onresult=function(e){
      let text='';
      try{text=e.results[0][0].transcript.trim();}catch(err){}
      if(text){
        const inp=document.getElementById('tutorInput');
        if(inp)inp.value=text;
        sendTutorMessage();
      }else if(status){
        status.textContent='⚠️ आवाज़ समझ नहीं आई। 🎤 फिर से दबाकर बोलिए।';
      }
    };

    rec.onerror=function(e){
      let msg='⚠️ Mic शुरू नहीं हुआ। 🎤 फिर से दबाएँ।';
      if(e && e.error==='not-allowed') msg='⚠️ Mic की अनुमति बंद है। Chrome → साइट की जानकारी → Microphone → Allow करें।';
      else if(e && e.error==='service-not-allowed') msg='⚠️ इस पेज को Mic की अनुमति नहीं मिली। HTTPS वाली पाठशाला साइट में खोलें।';
      else if(e && e.error==='no-speech') msg='⚠️ आपकी आवाज़ सुनाई नहीं दी। 🎤 दबाकर सीधे बोलिए।';
      else if(e && e.error==='audio-capture') msg='⚠️ फोन का Mic उपलब्ध नहीं है। फोन की Microphone permission जाँचें।';
      else if(e && e.error==='network') msg='⚠️ आवाज़ पहचानने के लिए इंटरनेट चालू करें।';
      if(status)status.textContent=msg;
    };

    rec.onend=function(){
      if(status && status.textContent.indexOf('सुन रहा')>=0)status.textContent='🟢 अगला सवाल पूछिए।';
      if(tutorRecognition===rec)tutorRecognition=null;
    };

    /* सबसे महत्वपूर्ण: start() सीधे tap/click के इसी event में है।
       getUserMedia को await नहीं किया जाता, ताकि Android Chrome का
       user gesture न टूटे। उपलब्ध होने पर permission भी साथ में माँगी जाती है। */
    try{
      if(navigator.mediaDevices && navigator.mediaDevices.getUserMedia){
        navigator.mediaDevices.getUserMedia({audio:true}).then(function(stream){
          stream.getTracks().forEach(function(t){t.stop();});
        }).catch(function(){});
      }
    }catch(e){}

    rec.start();
  }catch(e){
    if(status)status.textContent='⚠️ Mic शुरू नहीं हो पाया। Chrome में Microphone → Allow करके फिर 🎤 दबाएँ।';
  }
}

/* ===== 👨‍🏫 Live Class — ऑनलाइन shared database (सभी फ़ोन पर एक जैसा दिखे) ===== */
/* MantleDB: free, no-signup JSON key-value store — https://mantledb.sh
   एक अलग, कम-टकराव वाला namespace इस्तेमाल किया गया है ताकि किसी और के डेटा से न टकराए। */
const LIVECLASS_NS='pathshala-app-h7k2m9';
const LIVECLASS_PATH='liveclass';
const LIVECLASS_URL='https://mantledb.sh/v2/'+LIVECLASS_NS+'/'+LIVECLASS_PATH;

let liveClassCache=null;      // आख़िरी जाना हुआ shared data (undefined=network error, null=कोई class नहीं, object=data)
let liveClassPollTimer=null;
let teacherUnlocked=false;    // सिर्फ इसी सेशन के लिए — student/teacher flow अलग रखने के लिए

function liveClassEsc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function teacherPinKey(){return 'pathshala_teacher_pin'}                    // PIN सिर्फ़ local device पर — shared data नहीं
function getTeacherPin(){try{return localStorage.getItem(teacherPinKey())||'1234'}catch(e){return '1234'}}
function setTeacherPin(p){try{localStorage.setItem(teacherPinKey(),p)}catch(e){}}

async function liveClassFetch(){
  try{
    const res=await fetch(LIVECLASS_URL,{method:'GET'});
    if(res.status===404)return null;
    if(!res.ok)throw new Error('HTTP '+res.status);
    return await res.json();
  }catch(e){
    console.warn('Live Class fetch failed',e);
    return undefined;
  }
}
async function liveClassPush(data){
  const res=await fetch(LIVECLASS_URL,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});
  if(!res.ok)throw new Error('HTTP '+res.status);
  return await res.json();
}
async function liveClassRemove(){
  const res=await fetch(LIVECLASS_URL,{method:'DELETE'});
  if(!res.ok && res.status!==404)throw new Error('HTTP '+res.status);
}

/* ---- शिक्षक मोड (सिर्फ़ लोकल PIN से गेट, student flow से अलग) ---- */
function enterTeacherMode(){
  const pin=prompt('👨‍🏫 शिक्षक मोड में जाने के लिए PIN डालें:');
  if(pin===null)return;
  if(pin===getTeacherPin()){
    teacherUnlocked=true;
    paintLiveClassCard(liveClassCache);
  }else{
    alert('❌ गलत PIN। (डिफ़ॉल्ट PIN: 1234 — इसे बदलने के लिए शिक्षक मोड खोलकर "🔑 PIN बदलें" इस्तेमाल करें)');
  }
}
function exitTeacherMode(){teacherUnlocked=false;paintLiveClassCard(liveClassCache)}
function changeTeacherPin(){
  const cur=prompt('मौजूदा PIN डालें:');
  if(cur===null)return;
  if(cur!==getTeacherPin()){alert('❌ गलत PIN।');return;}
  const next=prompt('नया PIN डालें (कम से कम 4 अंक):');
  if(next===null||next.trim().length<4){if(next!==null)alert('कम से कम 4 अंकों का PIN रखें।');return;}
  setTeacherPin(next.trim());
  alert('✅ PIN बदल दिया गया।');
}

/* ---- रेंडरिंग: student को सिर्फ़ आज की Live Class + Join दिखे; शिक्षक मोड में edit/delete भी ---- */
function paintLiveClassCard(data){
  const box=document.getElementById('liveClassCard'); if(!box)return;
  if(data===undefined){
    box.innerHTML='<div class="panel"><h2>👨‍🏫 Live Class</h2><p>⚠️ जानकारी लोड नहीं हो पाई। इंटरनेट जाँचकर फिर कोशिश करें।</p><button class="chatBtn" onclick="refreshLiveClass()">🔄 दोबारा कोशिश करें</button></div>';
    return;
  }
  const teacherBar=teacherUnlocked
    ?'<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:10px">'
      +'<button class="chatBtn sendBtn" onclick="editLiveClass()">✏️ '+((data&&data.link)?'बदलें':'जोड़ें')+'</button>'
      +((data&&data.link)?'<button class="chatBtn" onclick="clearLiveClassPrompt()">🗑️ हटाएँ</button>':'')
      +'<button class="chatBtn" onclick="changeTeacherPin()">🔑 PIN बदलें</button>'
      +'<button class="chatBtn" onclick="exitTeacherMode()">🔒 शिक्षक मोड बंद करें</button>'
    +'</div>'
    :'<button class="chatBtn" style="margin-top:10px" onclick="enterTeacherMode()">👨‍🏫 शिक्षक मोड</button>';

  if(data&&data.link){
    box.innerHTML='<div class="panel" style="border:2px solid #e74c3c;background:#fff5f5">'
      +'<h2>👨‍🏫 आज की Live Class</h2>'
      +'<div style="display:flex;gap:14px;flex-wrap:wrap;margin:6px 0 10px;font-weight:800;color:#444">'
      +'<span>📹 वीडियो क्लास</span><span>🎤 आवाज़ से पढ़ाना</span><span>💬 सवाल-जवाब</span></div>'
      +(data.time?'<p style="margin:4px 0"><b>📅 क्लास का समय:</b> '+liveClassEsc(data.time)+'</p>':'')
      +(data.topic?'<p style="margin:4px 0"><b>📝 आज का विषय:</b> '+liveClassEsc(data.topic)+'</p>':'')
      +'<div style="margin-top:10px"><button class="chatBtn sendBtn" onclick="joinLiveClass()">🔗 क्लास में जुड़ें</button></div>'
      +teacherBar+'</div>';
  }else{
    box.innerHTML='<div class="panel"><h2>👨‍🏫 Live Class</h2>'
      +'<div style="display:flex;gap:14px;flex-wrap:wrap;margin:6px 0 10px;font-weight:800;color:#444">'
      +'<span>📹 वीडियो क्लास</span><span>🎤 आवाज़ से पढ़ाना</span><span>💬 सवाल-जवाब</span><span>📅 क्लास का समय</span></div>'
      +'<p>अभी कोई Live Class शेड्यूल नहीं है।</p>'+teacherBar+'</div>';
  }
}

async function renderLiveClassCard(){
  const box=document.getElementById('liveClassCard');
  if(box && !liveClassCache)box.innerHTML='<div class="panel"><p>⏳ Live Class जानकारी लोड हो रही है…</p></div>';
  const data=await liveClassFetch();
  liveClassCache=data;
  paintLiveClassCard(data);
  startLiveClassPolling();
}
async function refreshLiveClass(){
  const data=await liveClassFetch();
  liveClassCache=data;
  paintLiveClassCard(data);
}

function startLiveClassPolling(){
  stopLiveClassPolling();
  liveClassPollTimer=setInterval(async()=>{
    const el=document.getElementById('onlineStudy');
    if(!el||!el.classList.contains('active')){stopLiveClassPolling();return;}
    const data=await liveClassFetch();
    if(data===undefined)return;
    if(JSON.stringify(data)!==JSON.stringify(liveClassCache)){liveClassCache=data;paintLiveClassCard(data);}
  },20000);
}
function stopLiveClassPolling(){if(liveClassPollTimer){clearInterval(liveClassPollTimer);liveClassPollTimer=null}}

/* ---- सवाल-जवाब/जुड़ना (student flow) ---- */
function joinLiveClass(){
  if(liveClassCache&&liveClassCache.link)window.open(liveClassCache.link,'_blank');
  else alert('अभी कोई Live Class लिंक सेट नहीं है।');
}

/* ---- शिक्षक: जोड़ें/बदलें/हटाएँ (सिर्फ़ शिक्षक मोड में दिखते हैं) ---- */
async function editLiveClass(){
  if(!teacherUnlocked)return;
  const cur=liveClassCache||{};
  const link=prompt('👨‍🏫 शिक्षक का Live Class लिंक डालें (Zoom/Google Meet/YouTube आदि):',cur.link||'');
  if(link===null)return;
  const time=prompt('📅 क्लास का समय (जैसे: सोमवार, शाम 5 बजे):',cur.time||'');
  if(time===null)return;
  const topic=prompt('📝 आज का विषय (वैकल्पिक, खाली छोड़ सकते हैं):',cur.topic||'');
  if(topic===null)return;
  const payload={link:link.trim(),time:(time||'').trim(),topic:(topic||'').trim(),updatedAt:Date.now()};
  const box=document.getElementById('liveClassCard');
  if(box)box.innerHTML='<div class="panel"><p>⏳ सेव हो रहा है…</p></div>';
  try{
    await liveClassPush(payload);
    liveClassCache=payload;
    paintLiveClassCard(payload);
  }catch(e){
    alert('⚠️ सेव नहीं हो पाया। इंटरनेट जाँचकर फिर कोशिश करें।');
    paintLiveClassCard(liveClassCache);
  }
}
async function clearLiveClassPrompt(){
  if(!teacherUnlocked)return;
  if(!confirm('क्या आप Live Class की जानकारी हटाना चाहते हैं?'))return;
  const box=document.getElementById('liveClassCard');
  if(box)box.innerHTML='<div class="panel"><p>⏳ हटाया जा रहा है…</p></div>';
  try{
    await liveClassRemove();
    liveClassCache=null;
    paintLiveClassCard(null);
  }catch(e){
    alert('⚠️ हटाया नहीं जा सका। इंटरनेट जाँचकर फिर कोशिश करें।');
    paintLiveClassCard(liveClassCache);
  }
}

