function globalSearch(){
  const q=(document.getElementById('globalQuery')?.value||'').trim().toLowerCase();
  const box=document.getElementById('globalResults'); if(!box)return;
  if(!q){box.innerHTML='<p class="sub">ऊपर कुछ लिखकर खोजें।</p>';return;}
  const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const hits=[];
  PUBLIC_SEARCH_ITEMS.forEach(x=>{
    if((x.title+' '+x.desc+' '+x.keys).toLowerCase().includes(q)) hits.push({title:x.title,desc:x.desc,page:x.page});
  });
  try{
    Object.keys(STUDY_DATA||{}).forEach(cid=>{
      const c=STUDY_DATA[cid]; Object.keys(c.subjects||{}).forEach(sid=>{
        const sub=c.subjects[sid]; (sub.lessons||[]).forEach(l=>{
          const hay=(l.title+' '+l.content+' '+(sub.name||'')+' '+(c.name||'')).toLowerCase();
          if(hay.includes(q)) hits.push({title:'📘 '+l.title,desc:(c.name||'')+' • '+(sub.name||'')+' — '+String(l.content||'').slice(0,120),page:'study'});
        });
      });
    });
  }catch(e){}
  // Remove duplicate results.
  const seen=new Set(); const unique=hits.filter(x=>{const k=x.title+'|'+x.page;if(seen.has(k))return false;seen.add(k);return true;}).slice(0,30);
  if(!unique.length){box.innerHTML='<div class="warning">😕 इस नाम का पाठ या सुविधा नहीं मिली। <button class="settingsBtn" onclick="openPage(\'books\')">📚 किताबों में खोजें</button></div>';return;}
  box.innerHTML='<div class="bookResultHead"><h2>🔎 '+esc(q)+' के परिणाम</h2><p>'+unique.length+' परिणाम मिले।</p></div>'+unique.map(x=>`<div class="settingsBox"><h3>${esc(x.title)}</h3><p>${esc(x.desc)}</p><button class="settingsBtn" onclick="openPage('${esc(x.page)}')">खोलें →</button></div>`).join('');
}

