/* V42: recording reliability + saved links */
(function(){
  const LS_KEY='pathshalaSavedLinksV1';
  function mimeForRecord(){
    const types=['audio/webm;codecs=opus','audio/webm','audio/mp4','audio/ogg;codecs=opus'];
    return types.find(t=>window.MediaRecorder&&MediaRecorder.isTypeSupported&&MediaRecorder.isTypeSupported(t))||'';
  }
  function updateButtons(recording){
    const a=document.getElementById('recordStartBtn'),b=document.getElementById('recordStopBtn');
    if(a)a.disabled=recording; if(b)b.disabled=!recording;
  }
  window.startVoiceRecording=async function(){
    if(mediaRecorder&&mediaRecorder.state==='recording')return true;
    if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){setRecordStatus('⚠️ इस फोन/ब्राउज़र में रिकॉर्डिंग उपलब्ध नहीं है। Chrome में कोशिश करें।');return false;}
    try{
      await openRecordDB();
      recordStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});
      const mime=mimeForRecord();
      mediaRecorder=mime?new MediaRecorder(recordStream,{mimeType:mime}):new MediaRecorder(recordStream);
      recordChunks=[]; recordStartedAt=Date.now();
      mediaRecorder.ondataavailable=e=>{if(e.data&&e.data.size>0)recordChunks.push(e.data);};
      mediaRecorder.onerror=()=>{setRecordStatus('⚠️ रिकॉर्डिंग में समस्या हुई।');try{recordStream?.getTracks().forEach(t=>t.stop())}catch(_){};recordStream=null;updateButtons(false);};
      mediaRecorder.onstop=async()=>{try{recordStream?.getTracks().forEach(t=>t.stop())}catch(_){} recordStream=null;await saveVoiceRecording();};
      mediaRecorder.start(250); startRecordTimer(); updateButtons(true); setRecordStatus('🔴 रिकॉर्डिंग चल रही है…');
      return true;
    }catch(e){try{recordStream?.getTracks().forEach(t=>t.stop())}catch(_){} recordStream=null;mediaRecorder=null;updateButtons(false);setRecordStatus(e?.name==='NotAllowedError'?'⚠️ माइक्रोफोन की अनुमति नहीं मिली। ब्राउज़र में अनुमति दें।':'⚠️ माइक्रोफोन शुरू नहीं हो सका।');return false;}
  };
  window.stopVoiceRecording=function(errorStop){
    stopRecordTimer(); updateButtons(false);
    if(!mediaRecorder){try{recordStream?.getTracks().forEach(t=>t.stop())}catch(_){} recordStream=null;return;}
    if(mediaRecorder.state!=='inactive'){setRecordStatus(errorStop?'⚠️ रिकॉर्डिंग रोक दी गई।':'💾 रिकॉर्डिंग सेव हो रही है…');mediaRecorder.stop();}
    else if(!errorStop)saveVoiceRecording();
  };
  window.saveVoiceRecording=async function(){
    const duration=Math.max(0,Date.now()-recordStartedAt), chunks=recordChunks.slice(), mr=mediaRecorder;
    recordChunks=[]; mediaRecorder=null;
    if(!chunks.length){setRecordStatus('⚠️ कोई आवाज़ रिकॉर्ड नहीं हुई।');return;}
    try{
      const mime=mr?.mimeType||chunks[0].type||'audio/webm';
      const blob=new Blob(chunks,{type:mime});
      const db=await openRecordDB();
      await new Promise((resolve,reject)=>{const tx=db.transaction(RECORD_STORE,'readwrite');tx.objectStore(RECORD_STORE).add({name:'मेरी रिकॉर्डिंग — '+new Date().toLocaleString('hi-IN'),createdAt:Date.now(),duration,blob,type:mime});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||new Error('save failed'));});
      setRecordStatus('✅ रिकॉर्डिंग सेव हो गई।');
      const t=document.getElementById('recordTimer');if(t)t.textContent='00:00';
      renderRecordings();
      if(typeof inlineRecording!=='undefined' && inlineRecording){inlineRecording=false;clearInterval(inlineRecordTimerId);inlineRecordTimerId=null;updateInlineRecordUI();const el=document.getElementById('inlineRecordSaved');if(el)el.innerHTML='<div class="recordStatus">✅ रिकॉर्डिंग सेव हो गई। इसे ⚙️ सेटिंग्स → मेरी रिकॉर्डिंग में सुन सकते हैं।</div>';}
    }catch(e){setRecordStatus('⚠️ रिकॉर्डिंग सेव नहीं हो सकी। फोन का स्टोरेज उपलब्ध है या नहीं जाँचें।');}
  };
  window.toggleInlineRecording=async function(){
    if(inlineRecording){inlineRecording=false;clearInterval(inlineRecordTimerId);inlineRecordTimerId=null;updateInlineRecordUI();stopVoiceRecording(false);}
    else{const ok=await startVoiceRecording();if(!ok)return;inlineRecording=true;inlineRecordStartedAt=Date.now();clearInterval(inlineRecordTimerId);inlineRecordTimerId=setInterval(()=>{const el=document.getElementById('inlineRecordTimer');if(el)el.textContent=formatRecordTime(Date.now()-inlineRecordStartedAt)},250);updateInlineRecordUI();}
  };
  window.renderPathshalaLinks=function(){
    const box=document.getElementById('savedLinks');if(!box)return;let arr=[];try{arr=JSON.parse(localStorage.getItem(LS_KEY)||'[]')}catch(_){}
    if(!arr.length){box.innerHTML='<div class="bookEmpty">🔗 अभी कोई लिंक नहीं है। ऊपर से लिंक जोड़ें।</div>';return;}
    box.innerHTML=arr.map((x,i)=>'<article class="linkCard"><h3>'+escLink(x.title)+'</h3><a href="'+escLink(x.url)+'" target="_blank" rel="noopener noreferrer">'+escLink(x.url)+'</a><div class="linkActions"><a class="bookOpen" href="'+escLink(x.url)+'" target="_blank" rel="noopener noreferrer">🔗 लिंक खोलें</a><button class="recordDelete" onclick="deletePathshalaLink('+i+')">🗑️ हटाएँ</button></div></article>').join('');
  };
  function escLink(v){return String(v||'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
  window.addPathshalaLink=function(){
    const title=(document.getElementById('linkTitle')?.value||'').trim(), raw=(document.getElementById('linkUrl')?.value||'').trim();
    const st=document.getElementById('linkStatus');
    if(!title||!raw){if(st)st.textContent='⚠️ नाम और लिंक दोनों भरें।';return;}
    let u;try{u=new URL(/^https?:\/\//i.test(raw)?raw:'https://'+raw);}catch(_){if(st)st.textContent='⚠️ सही वेबसाइट लिंक डालें।';return;}
    if(!/^https?:$/.test(u.protocol)){if(st)st.textContent='⚠️ केवल http/https लिंक स्वीकार हैं।';return;}
    let arr=[];try{arr=JSON.parse(localStorage.getItem(LS_KEY)||'[]')}catch(_){};arr.unshift({title,url:u.href,createdAt:Date.now()});arr=arr.slice(0,50);localStorage.setItem(LS_KEY,JSON.stringify(arr));
    document.getElementById('linkTitle').value='';document.getElementById('linkUrl').value='';if(st)st.textContent='✅ लिंक सेव हो गया।';renderPathshalaLinks();
  };
  window.deletePathshalaLink=function(i){let arr=[];try{arr=JSON.parse(localStorage.getItem(LS_KEY)||'[]')}catch(_){};arr.splice(i,1);localStorage.setItem(LS_KEY,JSON.stringify(arr));renderPathshalaLinks();};
  document.addEventListener('DOMContentLoaded',()=>{if(location.hash==='#links')renderPathshalaLinks();});
})();

;

(function(){
  // V43: final safety layer for navigation, links and recording state.
  const LINK_KEY='pathshalaSavedLinksV1';
  function safeUrl(raw){
    try{ const u=new URL(/^https?:\/\//i.test(raw)?raw:'https://'+raw); return /^https?:$/.test(u.protocol)?u.href:null; }catch(e){ return null; }
  }
  function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
  window.renderPathshalaLinks=function(){
    const box=document.getElementById('savedLinks'); if(!box)return; let arr=[];
    try{arr=JSON.parse(localStorage.getItem(LINK_KEY)||'[]');if(!Array.isArray(arr))arr=[];}catch(e){arr=[];}
    if(!arr.length){box.innerHTML='<div class="bookEmpty">🔗 अभी कोई लिंक सेव नहीं है। ऊपर से लिंक जोड़ें।</div>';return;}
    box.innerHTML=arr.map((x,i)=>`<article class="linkCard"><h3>🔗 ${esc(x.title)}</h3><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.url)}</a><div class="linkActions"><a class="bookOpen" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">🔗 लिंक खोलें</a><button type="button" class="recordDelete" onclick="deletePathshalaLink(${i})">🗑️ हटाएँ</button></div></article>`).join('');
  };
  window.addPathshalaLink=function(){
    const ti=document.getElementById('linkTitle'), ui=document.getElementById('linkUrl'), st=document.getElementById('linkStatus');
    const title=(ti?.value||'').trim(), raw=(ui?.value||'').trim(), url=safeUrl(raw);
    if(!title||!raw){if(st)st.textContent='⚠️ नाम और लिंक दोनों भरें।';return;}
    if(!url){if(st)st.textContent='⚠️ सही http/https लिंक डालें।';return;}
    let arr=[];try{arr=JSON.parse(localStorage.getItem(LINK_KEY)||'[]');if(!Array.isArray(arr))arr=[];}catch(e){}
    if(arr.some(x=>x.url===url)){if(st)st.textContent='ℹ️ यह लिंक पहले से सेव है।';return;}
    arr.unshift({title,url,createdAt:Date.now()}); localStorage.setItem(LINK_KEY,JSON.stringify(arr.slice(0,50)));
    if(ti)ti.value='';if(ui)ui.value='';if(st)st.textContent='✅ लिंक सेव हो गया।';renderPathshalaLinks();
  };
  window.deletePathshalaLink=function(i){let arr=[];try{arr=JSON.parse(localStorage.getItem(LINK_KEY)||'[]');}catch(e){} if(!Array.isArray(arr))arr=[];if(i>=0&&i<arr.length)arr.splice(i,1);localStorage.setItem(LINK_KEY,JSON.stringify(arr));renderPathshalaLinks();};
  // Never leave a microphone stream running after navigation.
  const oldGoHome=window.goHome; window.goHome=function(){try{if(typeof inlineRecording!=='undefined'&&inlineRecording)stopInlineRecording();}catch(e){} try{if(typeof mediaRecorder!=='undefined'&&mediaRecorder&&mediaRecorder.state==='recording')stopVoiceRecording(true);}catch(e){} return oldGoHome.apply(this,arguments);};
  document.addEventListener('DOMContentLoaded',()=>{
    renderPathshalaLinks();
    const title=document.querySelector('title');if(title)title.textContent='पाठशाला v43';
    // Keep buttons non-submitting in any future form wrapper.
    document.querySelectorAll('button').forEach(b=>{if(!b.type)b.type='button';});
  });
})();

;

