    const level=Math.min(5,cycle), levelText=['शुरुआती','आसान','मध्यम','अभ्यास','चुनौती'][level-1]||'शुरुआती';
    return {id:track.name+'-'+(i+1),no:i+1,title:`${topic} — पाठ ${i+1}`,explain:explain+extra,example:`उदाहरण: ${example}`,q,opts,ans,level,levelText,practice:`अब अपने शब्दों में बताइए: ${topic} को आपने क्या समझा?`,hint:`संकेत: पहले उदाहरण पढ़ें, फिर प्रश्न में मुख्य शब्द पहचानें।`};
