(function(){
  /* केवल आवाज़ की समस्या: बोले हुए शब्द पहले दिखें, अपने-आप भेजे न जाएँ। */
  window.startTutorVoice=function(){
    const btn=document.getElementById('tutorMicBtn');
    const status=document.getElementById('tutorStatus');
    const inp=document.getElementById('tutorInput');
    const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
    if(!SR){if(status)status.textContent='⚠️ इस Chrome में बोलकर सवाल उपलब्ध नहीं है। HTTPS पर खोलकर Chrome में Microphone की अनुमति दें।';return;}
    try{
      if(window.tutorRecognition){try{window.tutorRecognition.abort();}catch(e){} window.tutorRecognition=null;}
      const rec=new SR(); window.tutorRecognition=rec;
      rec.lang=(window.selectedVoiceLanguage==='en-IN'||window.selectedVoiceLanguage==='en-US')?'en-IN':'hi-IN';
      rec.interimResults=false; rec.continuous=false; rec.maxAlternatives=3;
      if(btn){btn.disabled=true;btn.textContent='🔴';}
      if(status)status.textContent='🎙️ सुन रहा हूँ… साफ-साफ बोलिए।';
      rec.onresult=function(e){
        let text='';
        try{
          const r=e.results[0];
          text=(r[0]&&r[0].transcript||'').trim();
        }catch(err){}
        if(inp && text){
          inp.value=text;
          inp.focus();
          inp.dispatchEvent(new Event('input',{bubbles:true}));
          if(status)status.textContent='✏️ मैंने यह सुना: “'+text+'” — सही है तो नीचे भेजें, गलत है तो पहले सुधारें।';
        }else if(status){status.textContent='⚠️ आवाज़ समझ नहीं आई। फिर से 🎤 दबाएँ।';}
      };
      rec.onerror=function(e){
        let msg='⚠️ आवाज़ पहचान नहीं पाई। फिर से 🎤 दबाएँ।';
        if(e&&e.error==='not-allowed')msg='⚠️ Microphone की अनुमति बंद है। Chrome में Microphone → Allow करें।';
        else if(e&&e.error==='no-speech')msg='⚠️ आवाज़ सुनाई नहीं दी। 🎤 दबाकर सीधे बोलिए।';
        else if(e&&e.error==='network')msg='⚠️ आवाज़ पहचानने के लिए इंटरनेट चालू करें।';
        if(status)status.textContent=msg;
      };
      rec.onend=function(){
        if(btn){btn.disabled=false;btn.textContent='🎙️';}
        if(window.tutorRecognition===rec)window.tutorRecognition=null;
      };
      rec.start();
    }catch(e){if(btn){btn.disabled=false;btn.textContent='🎙️';}if(status)status.textContent='⚠️ Mic शुरू नहीं हो पाया। फिर से 🎤 दबाएँ।';}
  };

  /* कहानी: केवल उम्र-उपयुक्त लेबल स्पष्ट करें; बाकी कहानी सिस्टम को न बदलें। */
  const oldRenderStory=window.renderStoryScreen;
  if(oldRenderStory){
    window.renderStoryScreen=function(){
      oldRenderStory.apply(this,arguments);
      const sub=document.getElementById('storySub');
      if(sub && sub.textContent && !sub.textContent.includes('6–8 वर्ष')){
        sub.textContent='6–8 वर्ष के बच्चों के लिए • '+sub.textContent;
      }
    };
  }
})();

;

(function(){
  // केवल तभी fallback करें जब ऐप का अपना Back handler मौजूद न हो।
  window.pathshalaSafeBack = function(){
    try{
      if (typeof window.backTo === "function") { window.backTo(); return; }
      if (typeof window.goBack === "function") { window.goBack(); return; }
      if (history.length > 1) { history.back(); return; }
    }catch(e){}
  };
})();

