/* ===== V70 STUDY EXPANSION: 30 structured lessons ===== */
(function(){
 const v70Lessons = [{"id":"c1-hindi-v70-1","title":"स्वर और व्यंजन पहचान","icon":"📘","content":"हिंदी में स्वर अपने आप बोले जा सकते हैं, जबकि व्यंजन के साथ स्वर की ध्वनि जुड़ती है। अ, आ, इ, ई जैसे स्वर पहचानें और क, म, न जैसे व्यंजन पहचानें।","quiz":[{"q":"इनमें स्वर कौन है?","options":["अ","क","म","न"],"correct":"अ"},{"q":"इनमें व्यंजन कौन है?","options":["आ","इ","क","ई"],"correct":"क"},{"q":"“म” क्या है?","options":["व्यंजन","स्वर","अंक","चिह्न"],"correct":"व्यंजन"},{"q":"“ई” क्या है?","options":["स्वर","व्यंजन","अंक","शब्द"],"correct":"स्वर"},{"q":"स्वर की एक विशेषता क्या है?","options":["उसे अकेले बोला जा सकता है","वह केवल संख्या है","वह केवल चित्र है","वह केवल विराम है"],"correct":"उसे अकेले बोला जा सकता है"}]},{"id":"c1-hindi-v70-2","title":"एक जैसे अर्थ वाले सरल शब्द","icon":"📘","content":"कुछ शब्दों के अर्थ मिलते-जुलते होते हैं। ऐसे शब्दों को पहचानने का अभ्यास करें, जैसे खुशी–प्रसन्न और घर–मकान।","quiz":[{"q":"खुशी का समान अर्थ वाला शब्द कौन है?","options":["प्रसन्न","कड़वा","धीमा","ऊँचा"],"correct":"प्रसन्न"},{"q":"घर का समान अर्थ वाला शब्द कौन है?","options":["मकान","आकाश","पेड़","पानी"],"correct":"मकान"},{"q":"“प्रसन्न” का अर्थ क्या है?","options":["खुश","उदास","भूखा","थका"],"correct":"खुश"},{"q":"कौन-सा जोड़ा अर्थ में मिलता है?","options":["जल–पानी","दिन–रात","बड़ा–छोटा","ऊपर–नीचे"],"correct":"जल–पानी"},{"q":"समान अर्थ वाले शब्द सीखने से क्या बढ़ता है?","options":["शब्द-भंडार","केवल गिनती","केवल चित्र","केवल रंग"],"correct":"शब्द-भंडार"}]},{"id":"c1-english-v70-1","title":"Short Vowel a","icon":"📘","content":"The short vowel a appears in words such as cat, bat and map. Listen for the /a/ sound and read the word carefully.","quiz":[{"q":"Which word has short a?","options":["cat","bed","pig","sun"],"correct":"cat"},{"q":"Which word rhymes with cat?","options":["bat","bed","sit","run"],"correct":"bat"},{"q":"What vowel is in cat?","options":["a","e","i","o"],"correct":"a"},{"q":"Which word means a drawing location?","options":["map","sun","pen","cup"],"correct":"map"},{"q":"Choose the CVC word with a.","options":["hat","tree","bike","moon"],"correct":"hat"}]},{"id":"c1-english-v70-2","title":"This and That","icon":"📘","content":"Use “this” for one thing near you and “that” for one thing farther away. Practice choosing the correct word.","quiz":[{"q":"___ is my book. It is near me.","options":["This","Those","They","These"],"correct":"This"},{"q":"___ is a star in the sky.","options":["That","This","These","Those"],"correct":"That"},{"q":"Which word is for one nearby thing?","options":["this","that","those","they"],"correct":"this"},{"q":"Which word is for one far thing?","options":["that","this","these","those"],"correct":"that"},{"q":"“This is a pen.” talks about how many pens?","options":["one","two","three","many"],"correct":"one"}]},{"id":"c1-math-v70-1","title":"दहाई और इकाई","icon":"📘","content":"दो अंकों की संख्या में दहाई का स्थान बाईं ओर और इकाई का स्थान दाईं ओर होता है। 34 में 3 दहाई और 4 इकाइयाँ हैं।","quiz":[{"q":"34 में दहाई का अंक कौन है?","options":["3","4","7","0"],"correct":"3"},{"q":"34 में इकाई का अंक कौन है?","options":["4","3","0","8"],"correct":"4"},{"q":"2 दहाई कितनी होती हैं?","options":["20","2","12","200"],"correct":"20"},{"q":"5 इकाइयाँ कितनी होती हैं?","options":["5","50","15","500"],"correct":"5"},{"q":"47 में 4 का मान क्या है?","options":["40","4","7","47"],"correct":"40"}]},{"id":"c1-math-v70-2","title":"जोड़ में संख्या बढ़ाना","icon":"📘","content":"जोड़ का अर्थ है दो या अधिक समूहों को मिलाना। पहले इकाइयों को जोड़ें और फिर उत्तर जाँचें।","quiz":[{"q":"3 + 4 कितना है?","options":["7","6","8","9"],"correct":"7"},{"q":"5 + 2 कितना है?","options":["7","8","6","3"],"correct":"7"},{"q":"6 + 3 कितना है?","options":["8","9","10","7"],"correct":"9"},{"q":"2 + 7 कितना है?","options":["9","8","10","7"],"correct":"9"},{"q":"4 + 5 कितना है?","options":["8","9","10","7"],"correct":"9"}]},{"id":"c2-hindi-v70-1","title":"संज्ञा पहचान","icon":"📘","content":"किसी व्यक्ति, स्थान, वस्तु या जीव के नाम को संज्ञा कहते हैं। राम, पटना, किताब और गाय इसके उदाहरण हैं।","quiz":[{"q":"“किताब” क्या है?","options":["संज्ञा","क्रिया","विशेषण","विराम"],"correct":"संज्ञा"},{"q":"इनमें स्थान का नाम कौन है?","options":["पटना","दौड़ना","सुंदर","जल्दी"],"correct":"पटना"},{"q":"“गाय” किसका नाम है?","options":["जीव","स्थान","क्रिया","गुण"],"correct":"जीव"},{"q":"“राम खेलता है” में संज्ञा कौन है?","options":["राम","खेलता","है","कोई नहीं"],"correct":"राम"},{"q":"संज्ञा किसका नाम बताती है?","options":["व्यक्ति, स्थान, वस्तु या जीव","केवल समय","केवल रंग","केवल संख्या"],"correct":"व्यक्ति, स्थान, वस्तु या जीव"}]},{"id":"c2-hindi-v70-2","title":"वचन: एक और अनेक","icon":"📘","content":"एक वस्तु के लिए एकवचन और एक से अधिक के लिए बहुवचन का प्रयोग होता है। जैसे बच्चा–बच्चे और किताब–किताबें।","quiz":[{"q":"“लड़का” का बहुवचन क्या है?","options":["लड़के","लड़की","लड़कों","लड़का"],"correct":"लड़के"},{"q":"“किताब” का बहुवचन क्या है?","options":["किताबें","किताबी","किताब","किताब का"],"correct":"किताबें"},{"q":"एक वस्तु के लिए कौन-सा वचन है?","options":["एकवचन","बहुवचन","दोवचन","कोई नहीं"],"correct":"एकवचन"},{"q":"“बच्चे” किस वचन का उदाहरण है?","options":["बहुवचन","एकवचन","काल","लिंग"],"correct":"बहुवचन"},{"q":"वचन किसकी संख्या बताता है?","options":["एक या अनेक","केवल रंग","केवल आकार","केवल समय"],"correct":"एक या अनेक"}]},{"id":"c2-english-v70-1","title":"Nouns: Person Place Thing","icon":"📘","content":"A noun can name a person, place, animal or thing. Read each word and identify the noun category.","quiz":[{"q":"Which is a place?","options":["school","teacher","pencil","dog"],"correct":"school"},{"q":"Which is a person?","options":["doctor","park","ball","cat"],"correct":"doctor"},{"q":"Which is a thing?","options":["book","girl","market","horse"],"correct":"book"},{"q":"Which is an animal?","options":["tiger","school","farmer","table"],"correct":"tiger"},{"q":"A noun can name a ___.","options":["person","only color","only action","only number"],"correct":"person"}]},{"id":"c2-english-v70-2","title":"Present Continuous","icon":"📘","content":"Use am, is or are with an -ing word to describe an action happening now, such as “She is reading.”","quiz":[{"q":"She ___ reading.","options":["is","are","am","be"],"correct":"is"},{"q":"They ___ playing.","options":["are","is","am","be"],"correct":"are"},{"q":"I ___ writing.","options":["am","is","are","be"],"correct":"am"},{"q":"Which sentence shows an action happening now?","options":["He is running.","He ran yesterday.","He will run.","He runs daily."],"correct":"He is running."},{"q":"Which ending is common in present continuous verbs?","options":["-ing","-ed","-s","-ly"],"correct":"-ing"}]},{"id":"c2-math-v70-1","title":"स्थान-मूल्य से संख्या बनाना","icon":"📘","content":"दहाई और इकाई को मिलाकर दो अंकों की संख्या बनाई जाती है। 6 दहाई और 3 इकाई मिलकर 63 बनाते हैं।","quiz":[{"q":"6 दहाई और 3 इकाई से कौन-सी संख्या बनेगी?","options":["63","36","69","33"],"correct":"63"},{"q":"4 दहाई और 8 इकाई से?","options":["48","84","44","88"],"correct":"48"},{"q":"7 दहाई और 2 इकाई से?","options":["72","27","70","22"],"correct":"72"},{"q":"5 दहाई और 0 इकाई से?","options":["50","5","55","500"],"correct":"50"},{"q":"9 दहाई और 1 इकाई से?","options":["91","19","90","99"],"correct":"91"}]},{"id":"c2-math-v70-2","title":"गुणा को बार-बार जोड़ना","icon":"📘","content":"गुणा समान समूहों को जल्दी गिनने का तरीका है। 3 × 4 का अर्थ 4 को तीन बार जोड़ना भी है।","quiz":[{"q":"3 × 4 कितना है?","options":["12","7","9","16"],"correct":"12"},{"q":"2 × 5 कितना है?","options":["10","7","12","15"],"correct":"10"},{"q":"4 × 3 कितना है?","options":["12","9","16","7"],"correct":"12"},{"q":"5 × 2 कितना है?","options":["10","8","12","7"],"correct":"10"},{"q":"2 × 6 कितना है?","options":["12","8","10","14"],"correct":"12"}]},{"id":"c3-hindi-v70-1","title":"कर्ता और क्रिया","icon":"📘","content":"वाक्य में जो काम करता है वह कर्ता और जो काम बताया जाता है वह क्रिया हो सकती है। “सीमा दौड़ती है” में सीमा कर्ता और दौड़ती क्रिया है।","quiz":[{"q":"“मोहन पढ़ता है” में कर्ता कौन है?","options":["मोहन","पढ़ता","है","कोई नहीं"],"correct":"मोहन"},{"q":"उसी वाक्य में क्रिया कौन है?","options":["पढ़ता","मोहन","है","मोहन पढ़ता"],"correct":"पढ़ता"},{"q":"“रीना गाती है” में कौन काम कर रहा है?","options":["रीना","गाती","है","गीत"],"correct":"रीना"},{"q":"क्रिया क्या बताती है?","options":["काम","केवल नाम","केवल रंग","केवल संख्या"],"correct":"काम"},{"q":"कर्ता किससे जुड़ा होता है?","options":["काम करने वाले से","केवल जगह से","केवल रंग से","केवल समय से"],"correct":"काम करने वाले से"}]},{"id":"c3-hindi-v70-2","title":"काल का सरल परिचय","icon":"📘","content":"क्रिया के समय को काल कहते हैं। काम अभी हो रहा हो तो वर्तमान, पहले हुआ हो तो भूत और आगे होगा तो भविष्य का संकेत मिलता है।","quiz":[{"q":"“राम खेलता है” किस समय का संकेत है?","options":["वर्तमान","भूत","भविष्य","कोई नहीं"],"correct":"वर्तमान"},{"q":"“राम कल खेला” किस समय का संकेत है?","options":["भूत","वर्तमान","भविष्य","संज्ञा"],"correct":"भूत"},{"q":"“राम कल खेलेगा” किस समय का संकेत है?","options":["भविष्य","वर्तमान","भूत","विशेषण"],"correct":"भविष्य"},{"q":"काल किससे जुड़ा है?","options":["समय","रंग","आकार","गिनती"],"correct":"समय"},{"q":"“मैं पढ़ूँगा” किसका संकेत है?","options":["भविष्य","भूत","वर्तमान","वचन"],"correct":"भविष्य"}]},{"id":"c3-english-v70-1","title":"Subject and Verb","icon":"📘","content":"In a simple sentence, the subject tells who or what the sentence is about, and the verb tells the action or state.","quiz":[{"q":"In “Ravi runs”, the subject is ___.","options":["Ravi","runs","Ravi runs","none"],"correct":"Ravi"},{"q":"In “Ravi runs”, the verb is ___.","options":["runs","Ravi","run Ravi","none"],"correct":"runs"},{"q":"In “Birds fly”, what is the subject?","options":["Birds","fly","birds fly","none"],"correct":"Birds"},{"q":"A verb often tells a ___.","options":["action","color","place","number"],"correct":"action"},{"q":"Which is a verb?","options":["jump","school","blue","five"],"correct":"jump"}]},{"id":"c3-english-v70-2","title":"Comparative Adjectives","icon":"📘","content":"Comparative adjectives compare two things. Many short adjectives take -er, such as tall–taller and fast–faster.","quiz":[{"q":"The comparative of tall is ___.","options":["taller","tallest","tall","tally"],"correct":"taller"},{"q":"The comparative of fast is ___.","options":["faster","fastest","fast","fastly"],"correct":"faster"},{"q":"Which compares two things?","options":["bigger","biggest","big","bigness"],"correct":"bigger"},{"q":"The word “smaller” means ___.","options":["less big","more big","very big","not big"],"correct":"less big"},{"q":"Choose the comparative form of “short”.","options":["shorter","shortest","short","shortly"],"correct":"shorter"}]},{"id":"c3-math-v70-1","title":"गुणा में क्रम बदलना","icon":"📘","content":"गुणा में दो संख्याओं का क्रम बदलने पर गुणनफल नहीं बदलता। जैसे 3 × 4 और 4 × 3 दोनों 12 होते हैं।","quiz":[{"q":"3 × 4 का उत्तर क्या है?","options":["12","7","9","16"],"correct":"12"},{"q":"4 × 3 का उत्तर क्या है?","options":["12","10","8","14"],"correct":"12"},{"q":"क्या 2 × 5 और 5 × 2 बराबर हैं?","options":["हाँ","नहीं","कभी नहीं","पता नहीं"],"correct":"हाँ"},{"q":"6 × 2 कितना है?","options":["12","8","10","14"],"correct":"12"},{"q":"2 × 6 कितना है?","options":["12","8","10","14"],"correct":"12"}]},{"id":"c3-math-v70-2","title":"भाग के समूह","icon":"📘","content":"भाग का अर्थ किसी मात्रा को बराबर समूहों में बाँटना हो सकता है। 12 वस्तुओं को 3 बराबर समूहों में बाँटने पर हर समूह में 4 आएँगे।","quiz":[{"q":"12 ÷ 3 कितना है?","options":["4","3","6","9"],"correct":"4"},{"q":"10 ÷ 2 कितना है?","options":["5","2","8","12"],"correct":"5"},{"q":"15 ÷ 3 कितना है?","options":["5","3","6","12"],"correct":"5"},{"q":"8 ÷ 2 कितना है?","options":["4","2","6","10"],"correct":"4"},{"q":"20 ÷ 5 कितना है?","options":["4","5","10","15"],"correct":"4"}]},{"id":"c4-hindi-v70-1","title":"विशेषण पहचान","icon":"📘","content":"जो शब्द किसी संज्ञा की विशेषता बताते हैं उन्हें विशेषण कहते हैं। जैसे लाल फूल में “लाल” फूल की विशेषता बताता है।","quiz":[{"q":"“लाल फूल” में विशेषण कौन है?","options":["लाल","फूल","में","कोई नहीं"],"correct":"लाल"},{"q":"“मीठा आम” में विशेषण कौन है?","options":["मीठा","आम","में","कोई नहीं"],"correct":"मीठा"},{"q":"विशेषण क्या बताता है?","options":["विशेषता","केवल नाम","केवल काम","केवल समय"],"correct":"विशेषता"},{"q":"“बड़ा घर” में घर की विशेषता क्या है?","options":["बड़ा","घर","का","में"],"correct":"बड़ा"},{"q":"कौन-सा शब्द विशेषण है?","options":["सुंदर","लड़का","दौड़ना","पटना"],"correct":"सुंदर"}]},{"id":"c4-hindi-v70-2","title":"मुहावरे का सरल अर्थ","icon":"📘","content":"मुहावरा ऐसा प्रचलित वाक्यांश है जिसका अर्थ शब्दों के सीधे अर्थ से अलग हो सकता है। “नाक में दम करना” का अर्थ बहुत परेशान करना है।","quiz":[{"q":"“नाक में दम करना” का अर्थ क्या है?","options":["बहुत परेशान करना","नाक साफ करना","सो जाना","खाना खाना"],"correct":"बहुत परेशान करना"},{"q":"मुहावरे का अर्थ हमेशा कैसा होता है?","options":["प्रचलित अर्थ","केवल शब्दशः अर्थ","केवल संख्या","केवल रंग"],"correct":"प्रचलित अर्थ"},{"q":"मुहावरा भाषा को कैसा बना सकता है?","options":["रोचक","केवल छोटा","केवल कठिन","बेरंग"],"correct":"रोचक"},{"q":"“आँखों का तारा” किसके लिए कहा जा सकता है?","options":["बहुत प्यारे व्यक्ति के लिए","आकाश के तारे के लिए","पेड़ के लिए","किताब के लिए"],"correct":"बहुत प्यारे व्यक्ति के लिए"},{"q":"मुहावरे सीखने से क्या बढ़ता है?","options":["भाषा की समझ","केवल गिनती","केवल चित्र","केवल आवाज़"],"correct":"भाषा की समझ"}]},{"id":"c4-english-v70-1","title":"Past Simple","icon":"📘","content":"The past simple describes completed actions in the past. Regular verbs often use -ed, such as played and walked.","quiz":[{"q":"Which is past tense?","options":["played","play","playing","plays"],"correct":"played"},{"q":"The past of walk is ___.","options":["walked","walks","walking","walk"],"correct":"walked"},{"q":"Which sentence is in past simple?","options":["She visited home.","She visits home.","She is visiting home.","She will visit home."],"correct":"She visited home."},{"q":"Regular past verbs often end in ___.","options":["-ed","-ing","-s","-ly"],"correct":"-ed"},{"q":"The word “yesterday” often points to ___.","options":["past","future","present","place"],"correct":"past"}]},{"id":"c4-english-v70-2","title":"Adverbs of Frequency","icon":"📘","content":"Words such as always, often, sometimes and never tell how frequently something happens.","quiz":[{"q":"Which word means every time?","options":["always","never","sometimes","rarely"],"correct":"always"},{"q":"Which word means not at any time?","options":["never","often","always","sometimes"],"correct":"never"},{"q":"Which word means many times but not every time?","options":["often","never","always","none"],"correct":"often"},{"q":"Which word means on some occasions?","options":["sometimes","always","never","daily"],"correct":"sometimes"},{"q":"Frequency words tell us ___.","options":["how often","where","who","what color"],"correct":"how often"}]},{"id":"c4-math-v70-1","title":"भिन्न का अर्थ","icon":"📘","content":"भिन्न पूरे के बराबर भागों में से कुछ भाग दिखाती है। 1/2 का अर्थ दो बराबर भागों में से एक भाग है।","quiz":[{"q":"1/2 में नीचे की संख्या क्या बताती है?","options":["कुल बराबर भाग","लिए गए भाग","जोड़","गुणा"],"correct":"कुल बराबर भाग"},{"q":"1/2 में ऊपर की संख्या क्या बताती है?","options":["लिए गए भाग","कुल भाग","हर","उत्तर"],"correct":"लिए गए भाग"},{"q":"एक पूरे को 4 बराबर भागों में बाँटा, एक भाग क्या होगा?","options":["1/4","4/1","1/2","2/4"],"correct":"1/4"},{"q":"2/4 और 1/2 क्या बराबर हैं?","options":["हाँ","नहीं","केवल कभी","पता नहीं"],"correct":"हाँ"},{"q":"भिन्न किसका भाग दिखाती है?","options":["पूरे का","केवल संख्या का","केवल समय का","केवल रंग का"],"correct":"पूरे का"}]},{"id":"c4-math-v70-2","title":"परिमाप का परिचय","icon":"📘","content":"किसी बंद आकृति की चारों ओर की कुल लंबाई उसका परिमाप कहलाती है। आयत में सभी चार भुजाओं की लंबाइयाँ जोड़ते हैं।","quiz":[{"q":"परिमाप किसकी लंबाई है?","options":["चारों ओर की कुल लंबाई","केवल एक भुजा","केवल क्षेत्रफल","केवल ऊँचाई"],"correct":"चारों ओर की कुल लंबाई"},{"q":"4 सेमी भुजा वाले वर्ग का परिमाप कितना है?","options":["16 सेमी","8 सेमी","12 सेमी","4 सेमी"],"correct":"16 सेमी"},{"q":"3 सेमी × 2 सेमी आयत का परिमाप कितना है?","options":["10 सेमी","6 सेमी","12 सेमी","5 सेमी"],"correct":"10 सेमी"},{"q":"परिमाप निकालने में क्या जोड़ते हैं?","options":["भुजाएँ","केवल कोने","केवल रंग","केवल क्षेत्रफल"],"correct":"भुजाएँ"},{"q":"परिमाप की इकाई क्या हो सकती है?","options":["सेमी","वर्ग सेमी","किलोग्राम","लीटर"],"correct":"सेमी"}]},{"id":"c5-hindi-v70-1","title":"समास का सरल परिचय","icon":"📘","content":"दो या अधिक शब्द मिलकर छोटा और अर्थपूर्ण पद बना सकते हैं। इसे समास का सरल परिचय समझें, जैसे राज + पुत्र = राजपुत्र।","quiz":[{"q":"राज + पुत्र से कौन-सा पद बनता है?","options":["राजपुत्र","राजघर","पुत्रराजा","राजा पुत्र"],"correct":"राजपुत्र"},{"q":"समास में क्या होता है?","options":["शब्दों का संक्षिप्त मेल","केवल अक्षर गिनना","केवल रंग बदलना","केवल विराम"],"correct":"शब्दों का संक्षिप्त मेल"},{"q":"“राजपुत्र” में कौन दो शब्द हैं?","options":["राज और पुत्र","राजा और घर","रथ और पुत्र","राज और पानी"],"correct":"राज और पुत्र"},{"q":"समास का एक लाभ क्या है?","options":["भाषा को संक्षिप्त बनाना","गिनती बढ़ाना","रंग बदलना","आवाज़ तेज करना"],"correct":"भाषा को संक्षिप्त बनाना"},{"q":"समास किससे जुड़ा है?","options":["शब्द-रचना","केवल संख्या","केवल चित्र","केवल समय"],"correct":"शब्द-रचना"}]},{"id":"c5-hindi-v70-2","title":"अनुच्छेद का मुख्य विचार","icon":"📘","content":"किसी अनुच्छेद में कई वाक्य मिलकर एक मुख्य विचार बताते हैं। पढ़ते समय यह पहचानें कि लेखक सबसे महत्वपूर्ण बात क्या कहना चाहता है।","quiz":[{"q":"अनुच्छेद का मुख्य विचार क्या है?","options":["सबसे महत्वपूर्ण बात","सबसे लंबा शब्द","पहली संख्या","अंतिम अक्षर"],"correct":"सबसे महत्वपूर्ण बात"},{"q":"मुख्य विचार खोजने के लिए क्या करें?","options":["पूरे अनुच्छेद को समझें","केवल पहला शब्द पढ़ें","केवल चित्र देखें","केवल संख्या गिनें"],"correct":"पूरे अनुच्छेद को समझें"},{"q":"एक अनुच्छेद में क्या हो सकते हैं?","options":["कई जुड़े वाक्य","केवल एक अक्षर","केवल अंक","केवल चित्र"],"correct":"कई जुड़े वाक्य"},{"q":"मुख्य विचार किससे मदद करता है?","options":["समझने में","केवल लिखावट में","केवल रंग में","केवल गिनती में"],"correct":"समझने में"},{"q":"पढ़कर अपने शब्दों में बताना किस कौशल का अभ्यास है?","options":["समझ और अभिव्यक्ति","केवल जोड़","केवल चित्रकारी","केवल आवाज़"],"correct":"समझ और अभिव्यक्ति"}]},{"id":"c5-english-v70-1","title":"Main Idea in a Paragraph","icon":"📘","content":"A paragraph contains related sentences. The main idea is the most important point the writer wants the reader to understand.","quiz":[{"q":"What is the main idea?","options":["the most important point","the longest word","the first number","the last letter"],"correct":"the most important point"},{"q":"A paragraph contains related ___.","options":["sentences","numbers only","pictures only","letters only"],"correct":"sentences"},{"q":"To find the main idea, you should ___.","options":["understand the whole paragraph","read one word only","count letters only","ignore the sentences"],"correct":"understand the whole paragraph"},{"q":"Supporting details help explain the ___.","options":["main idea","alphabet","number line","title only"],"correct":"main idea"},{"q":"Summarizing means ___.","options":["telling the important points briefly","copying every word","changing every word","counting sentences"],"correct":"telling the important points briefly"}]},{"id":"c5-english-v70-2","title":"Future with Will","icon":"📘","content":"Use “will” to talk about an action that is expected or decided for the future, such as “I will study tomorrow.”","quiz":[{"q":"Which sentence is future?","options":["I will study tomorrow.","I study now.","I studied yesterday.","I am studying now."],"correct":"I will study tomorrow."},{"q":"Which word signals the future here?","options":["will","study","tomorrow","I"],"correct":"will"},{"q":"Complete: She ___ help me.","options":["will","did","is","was"],"correct":"will"},{"q":"Will is used for ___.","options":["future actions","past actions only","names","colors"],"correct":"future actions"},{"q":"Complete: We will ___ tomorrow.","options":["play","played","playing","plays"],"correct":"play"}]},{"id":"c5-math-v70-1","title":"दशमलव का परिचय","icon":"📘","content":"दशमलव संख्या पूरे और उसके भागों को दिखा सकती है। 0.5 को पाँच दसवें के रूप में समझा जा सकता है।","quiz":[{"q":"0.5 किसके बराबर है?","options":["5/10","5/100","1/5","10/5"],"correct":"5/10"},{"q":"0.5 को शब्दों में कैसे पढ़ सकते हैं?","options":["शून्य दशमलव पाँच","पाँच शून्य","पाँच दशमलव शून्य","पचास"],"correct":"शून्य दशमलव पाँच"},{"q":"0.2 किस भिन्न के बराबर है?","options":["2/10","2/100","1/2","10/2"],"correct":"2/10"},{"q":"दशमलव बिंदु किसे अलग करता है?","options":["पूरे भाग और दशमलव भाग को","केवल दो शब्दों को","केवल जोड़ को","केवल घटाव को"],"correct":"पूरे भाग और दशमलव भाग को"},{"q":"1.0 किसके बराबर है?","options":["1","10","0.1","100"],"correct":"1"}]},{"id":"c5-math-v70-2","title":"प्रतिशत का परिचय","icon":"📘","content":"प्रतिशत का अर्थ प्रति सौ होता है। 50% का अर्थ 100 में से 50 भाग है, यानी आधा।","quiz":[{"q":"प्रतिशत का अर्थ क्या है?","options":["प्रति सौ","प्रति दस","प्रति हजार","प्रति एक"],"correct":"प्रति सौ"},{"q":"50% कितने में से 50 है?","options":["100","10","50","500"],"correct":"100"},{"q":"50% किसके बराबर है?","options":["1/2","1/4","1/10","2/5"],"correct":"1/2"},{"q":"25% किसके बराबर है?","options":["1/4","1/2","3/4","1/5"],"correct":"1/4"},{"q":"100% का अर्थ क्या है?","options":["पूरा","आधा","चौथाई","कुछ नहीं"],"correct":"पूरा"}]}];
 for(const l of v70Lessons){ const m=l.id.match(/^c(\d+)-(hindi|english|math)-/); if(!m) continue; const c=m[1],s=m[2]; if(STUDY_DATA[c]?.subjects?.[s]) STUDY_DATA[c].subjects[s].lessons.push(l); }
})();


