/* ===== V73 HIGH STUDY EXPANSION: 30 structured lessons (Classes 6-10) ===== */
(function(){
  const v73Lessons = [{"id":"c6-hindi-v73-1","title":"पत्र लेखन की मूल बातें","icon":"📘","content":"औपचारिक और अनौपचारिक पत्र का उद्देश्य अलग हो सकता है। पत्र में संबोधन, मुख्य बात और उचित समापन का क्रम रखना चाहिए।","quiz":[{"q":"पत्र लिखने का मुख्य उद्देश्य क्या है?","options":["संदेश या विचार पहुँचाना","केवल चित्र बनाना","केवल गिनती करना","केवल शीर्षक लिखना"],"correct":"संदेश या विचार पहुँचाना"},{"q":"पत्र के आरंभ में क्या लिखा जा सकता है?","options":["संबोधन","निष्कर्ष","उत्तरमाला","केवल संख्या"],"correct":"संबोधन"},{"q":"पत्र का मुख्य भाग किसके लिए होता है?","options":["मुख्य संदेश के लिए","केवल नाम के लिए","केवल तारीख के लिए","केवल चित्र के लिए"],"correct":"मुख्य संदेश के लिए"},{"q":"पत्र के अंत में क्या होना उचित है?","options":["उचित समापन","नया असंबंधित विषय","केवल प्रश्न","केवल संख्या"],"correct":"उचित समापन"},{"q":"मित्र को लिखा पत्र सामान्यतः कैसा हो सकता है?","options":["अनौपचारिक","केवल सरकारी","केवल वैज्ञानिक","केवल समाचार"],"correct":"अनौपचारिक"}]},{"id":"c6-hindi-v73-2","title":"विशेषण और विशेष्य","icon":"📘","content":"जो शब्द किसी संज्ञा या सर्वनाम की विशेषता बताते हैं, वे विशेषण कहलाते हैं। जिस शब्द की विशेषता बताई जाती है, वह विशेष्य कहलाता है।","quiz":[{"q":"“सुंदर फूल” में विशेषण कौन है?","options":["सुंदर","फूल","में","कोई नहीं"],"correct":"सुंदर"},{"q":"“लाल गेंद” में विशेष्य कौन है?","options":["गेंद","लाल","में","कोई नहीं"],"correct":"गेंद"},{"q":"विशेषण किसकी विशेषता बता सकता है?","options":["संज्ञा या सर्वनाम की","केवल क्रिया की","केवल विराम की","केवल संख्या की"],"correct":"संज्ञा या सर्वनाम की"},{"q":"“तीन आम” में विशेषण कौन है?","options":["तीन","आम","में","कोई नहीं"],"correct":"तीन"},{"q":"विशेष्य क्या है?","options":["जिसकी विशेषता बताई जाए","जो केवल काम बताए","जो केवल समय बताए","जो केवल स्थान बताए"],"correct":"जिसकी विशेषता बताई जाए"}]},{"id":"c6-english-v73-1","title":"Pronouns and Their Use","icon":"📘","content":"Pronouns replace nouns to avoid unnecessary repetition. Common pronouns include he, she, it, they, we and them.","quiz":[{"q":"Which pronoun can replace “Riya”?","options":["she","they","it","we"],"correct":"she"},{"q":"Which pronoun can replace “the boys”?","options":["they","he","it","she"],"correct":"they"},{"q":"In “Ravi lost his book”, “his” shows ___.","options":["possession","place","time","question"],"correct":"possession"},{"q":"Which pronoun can refer to a thing?","options":["it","he","she","who"],"correct":"it"},{"q":"Why do we use pronouns?","options":["To avoid repeated nouns","To remove verbs","To add numbers","To change punctuation"],"correct":"To avoid repeated nouns"}]},{"id":"c6-english-v73-2","title":"Subject-Verb Agreement","icon":"📘","content":"A verb should agree with its subject. In the simple present, a singular subject such as “he” usually takes a verb ending in -s, while “they” takes the base form.","quiz":[{"q":"He ___ to school every day.","options":["goes","go","going","gone"],"correct":"goes"},{"q":"They ___ football.","options":["play","plays","playing","played"],"correct":"play"},{"q":"She ___ a story.","options":["reads","read","reading","reader"],"correct":"reads"},{"q":"We ___ English.","options":["study","studies","studying","studied"],"correct":"study"},{"q":"Why is subject-verb agreement important?","options":["It makes sentences grammatically clear","It removes nouns","It changes every tense","It adds punctuation only"],"correct":"It makes sentences grammatically clear"}]},{"id":"c6-math-v73-1","title":"पूर्णांक और संख्या रेखा","icon":"📘","content":"पूर्णांकों में ऋणात्मक संख्याएँ, शून्य और धनात्मक संख्याएँ शामिल होती हैं। संख्या रेखा पर दाईं ओर जाने पर मान बढ़ता है और बाईं ओर जाने पर घटता है।","quiz":[{"q":"पूर्णांकों में कौन शामिल है?","options":["ऋणात्मक, शून्य और धनात्मक संख्याएँ","केवल धनात्मक","केवल भिन्न","केवल दशमलव"],"correct":"ऋणात्मक, शून्य और धनात्मक संख्याएँ"},{"q":"संख्या रेखा पर दाईं ओर जाने से मान क्या होता है?","options":["बढ़ता है","घटता है","हमेशा शून्य होता है","बदलता नहीं"],"correct":"बढ़ता है"},{"q":"-3 और 2 में कौन बड़ा है?","options":["2","-3","दोनों बराबर","0"],"correct":"2"},{"q":"0 से बाईं ओर पहली पूर्णांक कौन है?","options":["-1","1","2","-2"],"correct":"-1"},{"q":"|-5| का मान क्या है?","options":["5","-5","0","10"],"correct":"5"}]},{"id":"c6-math-v73-2","title":"अनुपात और समानुपात","icon":"📘","content":"अनुपात दो राशियों की तुलना करता है। समानुपात में दो अनुपात बराबर होते हैं, जैसे 2:3 = 4:6।","quiz":[{"q":"2:3 में 2 और 3 क्या हैं?","options":["तुलना की राशियाँ","क्षेत्रफल","इकाइयाँ","कोण"],"correct":"तुलना की राशियाँ"},{"q":"2:3 और 4:6 क्या समानुपाती हैं?","options":["हाँ","नहीं","केवल कभी","पता नहीं"],"correct":"हाँ"},{"q":"3:5 में पहली संख्या क्या बताती है?","options":["पहली तुलना की मात्रा","कुल मात्रा हमेशा","प्रतिशत","क्षेत्रफल"],"correct":"पहली तुलना की मात्रा"},{"q":"यदि 1 पेन की कीमत 10 रुपये है, तो 3 पेन की कीमत कितनी होगी?","options":["30 रुपये","13 रुपये","20 रुपये","40 रुपये"],"correct":"30 रुपये"},{"q":"समानुपात का अर्थ क्या है?","options":["दो अनुपातों की समानता","दो संख्याओं का अंतर","केवल जोड़","केवल गुणा"],"correct":"दो अनुपातों की समानता"}]},{"id":"c7-hindi-v73-1","title":"समाचार लेखन","icon":"📘","content":"समाचार लेखन में घटना की मुख्य जानकारी स्पष्ट रूप से दी जाती है। क्या, कब, कहाँ और किससे संबंधित जानकारी उपयोगी होती है।","quiz":[{"q":"समाचार में सबसे पहले किस बात की स्पष्टता जरूरी है?","options":["मुख्य घटना","केवल सजावट","केवल लेखक का नाम","केवल रंग"],"correct":"मुख्य घटना"},{"q":"समाचार में “कब” किसकी जानकारी देता है?","options":["समय","स्थान","व्यक्ति","कारण"],"correct":"समय"},{"q":"“कहाँ” किसकी जानकारी देता है?","options":["स्थान","समय","संख्या","भावना"],"correct":"स्थान"},{"q":"समाचार की भाषा कैसी होनी चाहिए?","options":["स्पष्ट और तथ्यपरक","बहुत उलझी हुई","केवल कल्पनात्मक","बिना क्रम"],"correct":"स्पष्ट और तथ्यपरक"},{"q":"अच्छे समाचार में क्या नहीं करना चाहिए?","options":["बिना प्रमाण अफवाह को तथ्य बनाना","मुख्य जानकारी देना","तारीख बताना","स्रोत देखना"],"correct":"बिना प्रमाण अफवाह को तथ्य बनाना"}]},{"id":"c7-hindi-v73-2","title":"वाक्य के भेद","icon":"📘","content":"वाक्य का प्रकार उसके उद्देश्य के अनुसार पहचाना जा सकता है। प्रश्नवाचक वाक्य प्रश्न पूछता है और आज्ञावाचक वाक्य आदेश, अनुरोध या सलाह व्यक्त कर सकता है।","quiz":[{"q":"“तुम कहाँ जा रहे हो?” कौन-सा वाक्य है?","options":["प्रश्नवाचक","विस्मयादिबोधक","आज्ञावाचक","निषेधवाचक"],"correct":"प्रश्नवाचक"},{"q":"“कृपया बैठ जाइए।” किस प्रकार का वाक्य है?","options":["आज्ञावाचक","प्रश्नवाचक","विस्मयादिबोधक","घोषणात्मक"],"correct":"आज्ञावाचक"},{"q":"“वाह! कितना सुंदर दृश्य है!” कौन-सा है?","options":["विस्मयादिबोधक","प्रश्नवाचक","आज्ञावाचक","निषेधवाचक"],"correct":"विस्मयादिबोधक"},{"q":"प्रश्नवाचक वाक्य का उद्देश्य क्या है?","options":["प्रश्न पूछना","आदेश देना","आश्चर्य बताना","केवल नाम बताना"],"correct":"प्रश्न पूछना"},{"q":"वाक्य के भेद पहचानने में क्या मदद करता है?","options":["वाक्य का उद्देश्य","केवल लंबाई","केवल शब्दों की संख्या","केवल रंग"],"correct":"वाक्य का उद्देश्य"}]},{"id":"c7-english-v73-1","title":"Active and Passive Voice","icon":"📘","content":"In active voice, the subject performs the action. In passive voice, the receiver of the action becomes the grammatical subject.","quiz":[{"q":"In active voice, who usually performs the action?","options":["the subject","the object only","the punctuation","the title"],"correct":"the subject"},{"q":"“Ravi wrote the letter” is ___.","options":["active voice","passive voice","a question","a fragment"],"correct":"active voice"},{"q":"In passive voice, focus is often on ___.","options":["the receiver of the action","only the doer","only the tense name","the punctuation"],"correct":"the receiver of the action"},{"q":"Which sentence is passive?","options":["The ball was kicked by Arun.","Arun kicked the ball.","Arun kicks balls.","Arun will kick the ball."],"correct":"The ball was kicked by Arun."},{"q":"Why is voice useful in writing?","options":["It changes what the sentence emphasizes","It removes meaning","It changes every noun","It removes verbs"],"correct":"It changes what the sentence emphasizes"}]},{"id":"c7-english-v73-2","title":"Comparatives and Superlatives","icon":"📘","content":"Comparatives compare two things, while superlatives compare one thing with a group. Examples include taller and tallest.","quiz":[{"q":"Which form compares two things?","options":["comparative","superlative","noun","pronoun"],"correct":"comparative"},{"q":"What is the comparative of “tall”?","options":["taller","tallest","more tall","tallly"],"correct":"taller"},{"q":"What is the superlative of “small”?","options":["smallest","smaller","more small","smalling"],"correct":"smallest"},{"q":"“Asha is taller than Rina” compares ___.","options":["two people","one person only","a place and a thing","three groups"],"correct":"two people"},{"q":"“This is the best answer” uses ___.","options":["a superlative","a comparative","a noun only","a preposition"],"correct":"a superlative"}]},{"id":"c7-math-v73-1","title":"परिमेय संख्याएँ","icon":"📘","content":"जिस संख्या को p/q के रूप में लिखा जा सके, जहाँ q शून्य न हो, उसे परिमेय संख्या कहा जाता है।","quiz":[{"q":"परिमेय संख्या किस रूप में लिखी जा सकती है?","options":["p/q, q ≠ 0","p+q only","pq only","q/0"],"correct":"p/q, q ≠ 0"},{"q":"1/2 परिमेय संख्या है?","options":["हाँ","नहीं","केवल कभी","पता नहीं"],"correct":"हाँ"},{"q":"क्या 5 को 5/1 के रूप में लिखा जा सकता है?","options":["हाँ","नहीं","केवल दशमलव में","केवल प्रतिशत में"],"correct":"हाँ"},{"q":"परिमेय संख्या के हर में क्या नहीं हो सकता?","options":["0","1","2","-3"],"correct":"0"},{"q":"-3/4 धनात्मक है या ऋणात्मक?","options":["ऋणात्मक","धनात्मक","शून्य","दोनों"],"correct":"ऋणात्मक"}]},{"id":"c7-math-v73-2","title":"बीजीय व्यंजक और पद","icon":"📘","content":"बीजीय व्यंजक में संख्याएँ, चर और गणितीय संक्रियाएँ हो सकती हैं। 3x + 5 में 3x और 5 पद हैं।","quiz":[{"q":"3x + 5 में कितने पद हैं?","options":["2","1","3","5"],"correct":"2"},{"q":"3x में 3 क्या है?","options":["गुणांक","चर","घात","पदचिह्न"],"correct":"गुणांक"},{"q":"3x में x क्या है?","options":["चर","गुणांक","स्थिरांक","भिन्न"],"correct":"चर"},{"q":"5 अकेला किस प्रकार का पद है?","options":["स्थिरांक","चर","गुणांक हमेशा","घात"],"correct":"स्थिरांक"},{"q":"समान पदों को क्या किया जा सकता है?","options":["जोड़ा या घटाया जा सकता है","हमेशा हटाया जाता है","केवल चित्र बनाया जाता है","केवल रंग बदला जाता है"],"correct":"जोड़ा या घटाया जा सकता है"}]},{"id":"c8-hindi-v73-1","title":"तर्कपूर्ण अनुच्छेद","icon":"📘","content":"तर्कपूर्ण अनुच्छेद में स्पष्ट विचार, कारण और उदाहरण दिए जाते हैं। पाठक को केवल दावा नहीं, बल्कि उसके समर्थन का आधार भी दिखना चाहिए।","quiz":[{"q":"तर्कपूर्ण अनुच्छेद में क्या जरूरी है?","options":["दावा और कारण","केवल शीर्षक","केवल चित्र","केवल प्रश्न"],"correct":"दावा और कारण"},{"q":"उदाहरण का काम क्या है?","options":["विचार को स्पष्ट करना","विषय बदलना","केवल लंबाई बढ़ाना","केवल सजावट"],"correct":"विचार को स्पष्ट करना"},{"q":"तर्क को मजबूत करने के लिए क्या उपयोगी है?","options":["प्रमाण या विश्वसनीय तथ्य","अफवाह","असंबंधित बात","केवल भावुक शब्द"],"correct":"प्रमाण या विश्वसनीय तथ्य"},{"q":"अच्छा अनुच्छेद किस क्रम में होना चाहिए?","options":["विचार का तार्किक क्रम","बिना क्रम","केवल प्रश्नों का क्रम","केवल शब्दों का क्रम"],"correct":"विचार का तार्किक क्रम"},{"q":"तर्कपूर्ण लेखन का उद्देश्य क्या हो सकता है?","options":["विचार को कारणों के साथ समझाना","केवल मनोरंजन","केवल चित्र बनाना","केवल गिनती करना"],"correct":"विचार को कारणों के साथ समझाना"}]},{"id":"c8-hindi-v73-2","title":"अलंकार का परिचय","icon":"📘","content":"अलंकार भाषा को अधिक प्रभावशाली और सुंदर बनाने का तरीका है। उपमा में किसी वस्तु या व्यक्ति की तुलना “जैसे” या “समान” शब्दों से की जा सकती है।","quiz":[{"q":"अलंकार का एक उद्देश्य क्या है?","options":["भाषा को प्रभावशाली बनाना","केवल छोटा करना","केवल गिनना","केवल विराम देना"],"correct":"भाषा को प्रभावशाली बनाना"},{"q":"उपमा में क्या होता है?","options":["तुलना","गिनती","प्रश्न","आदेश"],"correct":"तुलना"},{"q":"“चेहरा चाँद जैसा है” में तुलना किससे है?","options":["चाँद से","पेड़ से","पानी से","पुस्तक से"],"correct":"चाँद से"},{"q":"उपमा में कौन-सा शब्द तुलना का संकेत दे सकता है?","options":["जैसा","लेकिन","क्योंकि","यदि"],"correct":"जैसा"},{"q":"अलंकार सीखने से क्या समझ बढ़ती है?","options":["भाषा की अभिव्यक्ति","केवल गणित","केवल विज्ञान","केवल समय"],"correct":"भाषा की अभिव्यक्ति"}]},{"id":"c8-english-v73-1","title":"Reported Speech Basics","icon":"📘","content":"Reported speech tells what someone said without repeating the exact words. Pronouns, tense and time expressions may change depending on context.","quiz":[{"q":"Reported speech tells us ___.","options":["what someone said","only where they went","only their age","only a question"],"correct":"what someone said"},{"q":"Which is direct speech?","options":["Ravi said, “I am tired.”","Ravi said that he was tired.","Ravi was tired.","Ravi feels tired."],"correct":"Ravi said, “I am tired.”"},{"q":"In reported speech, pronouns may ___.","options":["change with the speaker","always disappear","become numbers","turn into punctuation"],"correct":"change with the speaker"},{"q":"Reported speech is useful for ___.","options":["summarizing what was said","removing meaning","changing every noun","writing only questions"],"correct":"summarizing what was said"},{"q":"Direct speech usually uses ___.","options":["quotation marks","a fraction bar","an equals sign","a percentage sign"],"correct":"quotation marks"}]},{"id":"c8-english-v73-2","title":"Relative Clauses","icon":"📘","content":"A relative clause gives extra information about a noun. Words such as who, which and that can introduce relative clauses.","quiz":[{"q":"A relative clause gives information about a ___.","options":["noun","number only","punctuation mark","title only"],"correct":"noun"},{"q":"Which word can introduce a clause about a person?","options":["who","which only","where only","when only"],"correct":"who"},{"q":"Which can refer to a thing?","options":["which","who only","whom only","he"],"correct":"which"},{"q":"In “The book that I bought is new”, “that I bought” is ___.","options":["a relative clause","the main title","a number","a punctuation mark"],"correct":"a relative clause"},{"q":"Why use relative clauses?","options":["To add useful information to a sentence","To remove all verbs","To shorten every word","To change numbers"],"correct":"To add useful information to a sentence"}]},{"id":"c8-math-v73-1","title":"रैखिक समीकरण और कोष्ठक","icon":"📘","content":"रैखिक समीकरण को हल करते समय दोनों पक्षों पर समान क्रिया करनी चाहिए। कोष्ठक हटाने के लिए वितरण नियम का उपयोग किया जा सकता है।","quiz":[{"q":"समीकरण के दोनों पक्षों पर क्या करना चाहिए?","options":["समान क्रिया","अलग-अलग क्रिया","कुछ भी नहीं","केवल जोड़"],"correct":"समान क्रिया"},{"q":"2(x+3) को सरल करने पर क्या मिलेगा?","options":["2x+6","2x+3","x+6","2x+5"],"correct":"2x+6"},{"q":"x+5=12 में x कितना है?","options":["7","17","5","12"],"correct":"7"},{"q":"3x=15 में x कितना है?","options":["5","45","12","3"],"correct":"5"},{"q":"समीकरण हल करने का उद्देश्य क्या है?","options":["चर का मान ज्ञात करना","केवल चित्र बनाना","केवल संख्या गिनना","केवल चिह्न बदलना"],"correct":"चर का मान ज्ञात करना"}]},{"id":"c8-math-v73-2","title":"क्षेत्रफल और घनाभ","icon":"📘","content":"आयत का क्षेत्रफल लंबाई × चौड़ाई होता है। घनाभ के आयामों से उसके आयतन की गणना लंबाई × चौड़ाई × ऊँचाई से की जा सकती है।","quiz":[{"q":"आयत का क्षेत्रफल क्या है?","options":["लंबाई × चौड़ाई","लंबाई + चौड़ाई","2 × लंबाई","केवल चौड़ाई"],"correct":"लंबाई × चौड़ाई"},{"q":"5 सेमी × 4 सेमी आयत का क्षेत्रफल कितना है?","options":["20 वर्ग सेमी","18 वर्ग सेमी","9 वर्ग सेमी","10 वर्ग सेमी"],"correct":"20 वर्ग सेमी"},{"q":"घनाभ का आयतन किससे निकलेगा?","options":["लंबाई × चौड़ाई × ऊँचाई","केवल लंबाई","लंबाई + चौड़ाई","2 × ऊँचाई"],"correct":"लंबाई × चौड़ाई × ऊँचाई"},{"q":"2×3×4 का मान क्या है?","options":["24","12","9","18"],"correct":"24"},{"q":"आयतन की इकाई कैसी हो सकती है?","options":["घन सेमी","सेमी","किलोग्राम","लीटर हमेशा"],"correct":"घन सेमी"}]},{"id":"c9-hindi-v73-1","title":"भावार्थ और संदर्भ","icon":"📘","content":"कविता या गद्यांश का भावार्थ बताते समय मूल विचार को अपने सरल शब्दों में समझाया जाता है। संदर्भ से यह भी पता चलता है कि पंक्ति किस प्रसंग में कही गई है।","quiz":[{"q":"भावार्थ क्या बताता है?","options":["मूल विचार का सरल अर्थ","केवल शब्दों की गिनती","केवल लेखक का नाम","केवल तुक"],"correct":"मूल विचार का सरल अर्थ"},{"q":"भावार्थ लिखते समय क्या करना चाहिए?","options":["अपने सरल शब्दों में अर्थ बताना","हर शब्द की नकल करना","विषय बदल देना","केवल शीर्षक लिखना"],"correct":"अपने सरल शब्दों में अर्थ बताना"},{"q":"संदर्भ किसमें मदद करता है?","options":["प्रसंग समझने में","केवल गिनती में","केवल चित्र में","केवल विराम में"],"correct":"प्रसंग समझने में"},{"q":"कविता की पंक्ति का भावार्थ किससे जुड़ा है?","options":["उसके अर्थ और भाव से","केवल अक्षरों से","केवल लंबाई से","केवल तुक से"],"correct":"उसके अर्थ और भाव से"},{"q":"अच्छे भावार्थ की भाषा कैसी होनी चाहिए?","options":["स्पष्ट और सरल","बिना अर्थ की","बहुत उलझी हुई","केवल कठिन शब्दों वाली"],"correct":"स्पष्ट और सरल"}]},{"id":"c9-hindi-v73-2","title":"रिपोर्ट और तथ्यपरक भाषा","icon":"📘","content":"रिपोर्ट में किसी घटना या विषय की जानकारी क्रमबद्ध और तथ्यपरक ढंग से दी जाती है। लेखक को अनुमान और प्रमाणित तथ्य के बीच अंतर रखना चाहिए।","quiz":[{"q":"रिपोर्ट की भाषा कैसी होनी चाहिए?","options":["तथ्यपरक और स्पष्ट","अफवाह आधारित","केवल भावुक","बिना क्रम"],"correct":"तथ्यपरक और स्पष्ट"},{"q":"रिपोर्ट में घटना की जानकारी किस क्रम में देना उपयोगी है?","options":["तार्किक क्रम में","बिना क्रम","केवल अंत से","केवल शीर्षक से"],"correct":"तार्किक क्रम में"},{"q":"अनुमान और तथ्य में क्या अंतर है?","options":["तथ्य का आधार प्रमाणित हो सकता है","दोनों हमेशा एक ही हैं","अनुमान हमेशा प्रमाण है","तथ्य केवल राय है"],"correct":"तथ्य का आधार प्रमाणित हो सकता है"},{"q":"रिपोर्ट में स्रोत क्यों महत्वपूर्ण है?","options":["विश्वसनीयता जाँचने के लिए","केवल लंबाई बढ़ाने के लिए","केवल रंग चुनने के लिए","केवल शीर्षक बनाने के लिए"],"correct":"विश्वसनीयता जाँचने के लिए"},{"q":"रिपोर्ट का उद्देश्य क्या हो सकता है?","options":["घटना की जानकारी देना","कहानी को मनमाने ढंग से बदलना","केवल प्रश्न पूछना","केवल चित्र बनाना"],"correct":"घटना की जानकारी देना"}]},{"id":"c9-english-v73-1","title":"Conditionals: Zero and First","icon":"📘","content":"Zero conditional is commonly used for general truths, while first conditional is used for possible future situations.","quiz":[{"q":"Zero conditional often describes ___.","options":["general truths","imaginary past only","names","punctuation"],"correct":"general truths"},{"q":"“If you heat ice, it melts” is an example of ___.","options":["zero conditional","first conditional","past perfect","passive voice"],"correct":"zero conditional"},{"q":"First conditional commonly refers to ___.","options":["a possible future situation","a fixed past event","a noun","a definition only"],"correct":"a possible future situation"},{"q":"Complete: If it rains, we ___ stay home.","options":["will","would have","were","did"],"correct":"will"},{"q":"Which word often begins a conditional clause?","options":["if","because","although","while"],"correct":"if"}]},{"id":"c9-english-v73-2","title":"Summary Writing","icon":"📘","content":"A good summary keeps the main ideas and important supporting points while leaving out unnecessary details and repetition.","quiz":[{"q":"A summary should include ___.","options":["main ideas","every single detail","only the title","only questions"],"correct":"main ideas"},{"q":"What should a summary avoid?","options":["unnecessary repetition","important ideas","clear language","key points"],"correct":"unnecessary repetition"},{"q":"A summary is usually ___.","options":["shorter than the original","longer than the original","exactly the same","only one word"],"correct":"shorter than the original"},{"q":"Why read the whole text before summarizing?","options":["To understand the main message","To count letters","To copy punctuation","To choose colors"],"correct":"To understand the main message"},{"q":"Good summary language should be ___.","options":["clear and concise","random","unclear","full of unrelated ideas"],"correct":"clear and concise"}]},{"id":"c9-math-v73-1","title":"बहुपद और घात","icon":"📘","content":"बहुपद में चर की घातें शून्य या धनात्मक पूर्णांक हो सकती हैं। पदों को उनके घात और गुणांक के आधार पर समझा जाता है।","quiz":[{"q":"x² + 3x + 2 में कितने पद हैं?","options":["3","2","4","1"],"correct":"3"},{"q":"x² की घात क्या है?","options":["2","1","0","3"],"correct":"2"},{"q":"3x में गुणांक क्या है?","options":["3","x","0","1"],"correct":"3"},{"q":"स्थिरांक 7 की घात क्या मानी जा सकती है?","options":["0","1","7","2"],"correct":"0"},{"q":"बहुपद किससे बना हो सकता है?","options":["चर, गुणांक और पद","केवल चित्र","केवल कोण","केवल भिन्न"],"correct":"चर, गुणांक और पद"}]},{"id":"c9-math-v73-2","title":"सांख्यिकी: माध्य, माध्यिका और बहुलक","icon":"📘","content":"डेटा के केंद्र को समझने के लिए माध्य, माध्यिका और बहुलक जैसे माप उपयोगी हैं। माध्य सभी मानों का योग करके मानों की संख्या से भाग देने पर मिलता है।","quiz":[{"q":"माध्य कैसे निकालते हैं?","options":["योग ÷ मानों की संख्या","सबसे बड़ा मान × संख्या","केवल मध्य मान","सबसे अधिक आने वाला मान"],"correct":"योग ÷ मानों की संख्या"},{"q":"2,4,6 का माध्य क्या है?","options":["4","6","3","12"],"correct":"4"},{"q":"क्रमबद्ध डेटा का बीच वाला मान क्या कहलाता है?","options":["माध्यिका","माध्य","बहुलक","परास"],"correct":"माध्यिका"},{"q":"सबसे अधिक बार आने वाला मान क्या कहलाता है?","options":["बहुलक","माध्यिका","माध्य","परास"],"correct":"बहुलक"},{"q":"सांख्यिकी किसमें मदद करती है?","options":["डेटा को समझने में","केवल कहानी लिखने में","केवल चित्र बनाने में","केवल भाषा सीखने में"],"correct":"डेटा को समझने में"}]},{"id":"c10-hindi-v73-1","title":"संपादन और भाषा-शुद्धि","icon":"📘","content":"संपादन में वर्तनी, व्याकरण, विराम-चिह्न और वाक्य की स्पष्टता जाँची जाती है। सुधार करते समय मूल अर्थ को बनाए रखना चाहिए।","quiz":[{"q":"संपादन में क्या जाँचा जाता है?","options":["वर्तनी और व्याकरण","केवल चित्र","केवल रंग","केवल पन्नों की संख्या"],"correct":"वर्तनी और व्याकरण"},{"q":"विराम-चिह्न क्यों जरूरी हैं?","options":["अर्थ और पढ़ने की स्पष्टता के लिए","केवल सजावट के लिए","केवल शब्द बढ़ाने के लिए","केवल गिनती के लिए"],"correct":"अर्थ और पढ़ने की स्पष्टता के लिए"},{"q":"भाषा-शुद्धि करते समय क्या बचाना चाहिए?","options":["मूल अर्थ","गलत वर्तनी","असंबंधित बात","अनावश्यक दोहराव"],"correct":"मूल अर्थ"},{"q":"किसे सुधारना संपादन का हिस्सा हो सकता है?","options":["गलत वाक्य-रचना","केवल रंग","केवल चित्र","केवल फॉन्ट का आकार"],"correct":"गलत वाक्य-रचना"},{"q":"अच्छा संपादन किस परिणाम की ओर ले जाता है?","options":["अधिक स्पष्ट लेखन","अधिक भ्रम","कम अर्थ","केवल लंबा पाठ"],"correct":"अधिक स्पष्ट लेखन"}]},{"id":"c10-hindi-v73-2","title":"आलोचनात्मक पठन","icon":"📘","content":"आलोचनात्मक पठन में पाठ के दावे, प्रमाण, भाषा और दृष्टिकोण पर विचार किया जाता है। पाठक केवल पढ़ता नहीं, बल्कि प्रमाण के आधार पर मूल्यांकन भी करता है।","quiz":[{"q":"आलोचनात्मक पठन में क्या देखा जाता है?","options":["दावे और प्रमाण","केवल शीर्षक","केवल चित्र","केवल लंबाई"],"correct":"दावे और प्रमाण"},{"q":"किसी दावे का मूल्यांकन कैसे किया जा सकता है?","options":["प्रमाण और तर्क देखकर","केवल अनुमान से","केवल शीर्षक से","केवल भावनाओं से"],"correct":"प्रमाण और तर्क देखकर"},{"q":"दृष्टिकोण का अर्थ क्या हो सकता है?","options":["किसी विषय को देखने का तरीका","केवल स्थान","केवल समय","केवल संख्या"],"correct":"किसी विषय को देखने का तरीका"},{"q":"विश्वसनीय स्रोत क्यों जरूरी है?","options":["जानकारी की जाँच के लिए","केवल पाठ लंबा करने के लिए","केवल चित्र चुनने के लिए","केवल प्रश्न बनाने के लिए"],"correct":"जानकारी की जाँच के लिए"},{"q":"आलोचनात्मक पाठक क्या करता है?","options":["प्रश्न पूछकर और प्रमाण देखकर सोचता है","हर बात बिना जाँच मानता है","केवल शीर्षक पढ़ता है","केवल चित्र देखता है"],"correct":"प्रश्न पूछकर और प्रमाण देखकर सोचता है"}]},{"id":"c10-english-v73-1","title":"Essay Structure and Coherence","icon":"📘","content":"A strong essay has a clear introduction, logically connected body paragraphs and a conclusion. Linking words help ideas flow from one sentence or paragraph to another.","quiz":[{"q":"What usually comes first in an essay?","options":["an introduction","a conclusion","a reference list only","a random detail"],"correct":"an introduction"},{"q":"What does a conclusion do?","options":["wraps up the main ideas","starts an unrelated topic","adds random facts","removes the main idea"],"correct":"wraps up the main ideas"},{"q":"What helps connect ideas?","options":["linking words","random punctuation","only numbers","only titles"],"correct":"linking words"},{"q":"A coherent essay has ideas that are ___.","options":["logically connected","randomly arranged","unrelated","repeated without purpose"],"correct":"logically connected"},{"q":"Which is a linking word?","options":["however","table","blue","seven"],"correct":"however"}]},{"id":"c10-english-v73-2","title":"Reading: Author’s Purpose and Tone","icon":"📘","content":"When reading, identify why the author wrote the text and the attitude or tone expressed. The purpose may be to inform, persuade, explain or entertain.","quiz":[{"q":"Author’s purpose means ___.","options":["why the author wrote the text","the page number","the longest word","the title only"],"correct":"why the author wrote the text"},{"q":"A text written to convince readers aims to ___.","options":["persuade","measure","count","translate"],"correct":"persuade"},{"q":"Tone refers to the author’s ___.","options":["attitude or feeling","page size","number of paragraphs","spelling only"],"correct":"attitude or feeling"},{"q":"A text giving factual information may aim to ___.","options":["inform","persuade only","entertain only","hide facts"],"correct":"inform"},{"q":"Why identify purpose and tone?","options":["To understand the text more deeply","To count words only","To change the title","To ignore evidence"],"correct":"To understand the text more deeply"}]},{"id":"c10-math-v73-1","title":"त्रिकोणमिति का मूल अनुपात","icon":"📘","content":"समकोण त्रिभुज में किसी कोण के सापेक्ष sin, cos और tan अनुपात भुजाओं की तुलना करते हैं। जैसे sin θ = लंब/कर्ण और cos θ = आधार/कर्ण।","quiz":[{"q":"sin θ किसके बराबर है?","options":["लंब/कर्ण","आधार/कर्ण","लंब/आधार","कर्ण/लंब"],"correct":"लंब/कर्ण"},{"q":"cos θ किसके बराबर है?","options":["आधार/कर्ण","लंब/कर्ण","कर्ण/आधार","लंब/आधार"],"correct":"आधार/कर्ण"},{"q":"tan θ किसके बराबर है?","options":["लंब/आधार","आधार/कर्ण","कर्ण/लंब","आधार/लंब"],"correct":"लंब/आधार"},{"q":"ये अनुपात किस त्रिभुज में मूल रूप से पढ़े जाते हैं?","options":["समकोण त्रिभुज","केवल वृत्त","केवल वर्ग","केवल समबाहु त्रिभुज"],"correct":"समकोण त्रिभुज"},{"q":"कर्ण किस भुजा को कहते हैं?","options":["समकोण के सामने वाली सबसे लंबी भुजा","सबसे छोटी भुजा हमेशा","ऊँचाई हमेशा","आधार हमेशा"],"correct":"समकोण के सामने वाली सबसे लंबी भुजा"}]},{"id":"c10-math-v73-2","title":"द्विघात समीकरण के गुणनखंड","icon":"📘","content":"कुछ द्विघात समीकरणों को गुणनखंड करके हल किया जा सकता है। यदि (x-a)(x-b)=0 हो, तो x=a या x=b हो सकता है।","quiz":[{"q":"(x-2)(x-3)=0 के हल क्या हैं?","options":["2 और 3","-2 और -3","5 और 6","0 और 1"],"correct":"2 और 3"},{"q":"यदि ab=0 है, तो सामान्यतः क्या हो सकता है?","options":["a=0 या b=0","a और b दोनों 1","a+b=0 हमेशा","ab=1"],"correct":"a=0 या b=0"},{"q":"x²-9 के गुणनखंड क्या हैं?","options":["(x-3)(x+3)","(x-9)(x+1)","(x-3)²","(x+9)(x-1)"],"correct":"(x-3)(x+3)"},{"q":"x²-5x+6 के गुणनखंड क्या हैं?","options":["(x-2)(x-3)","(x+2)(x+3)","(x-1)(x-6)","(x+1)(x-6)"],"correct":"(x-2)(x-3)"},{"q":"गुणनखंड विधि का उद्देश्य क्या है?","options":["समीकरण को सरल रूप में लिखकर हल ढूँढना","केवल चित्र बनाना","केवल प्रतिशत निकालना","केवल जोड़ करना"],"correct":"समीकरण को सरल रूप में लिखकर हल ढूँढना"}]}];
  for(const l of v73Lessons){
    const m=l.id.match(/^c(\d+)-(hindi|english|math)-/);
    if(!m) continue;
    const c=m[1], s=m[2];
    if(STUDY_DATA[c]?.subjects?.[s]){
      const exists=STUDY_DATA[c].subjects[s].lessons.some(x=>x.id===l.id);
      if(!exists) STUDY_DATA[c].subjects[s].lessons.push(l);
    }
  }
  window.PATHSHALA_V73_HIGH_STUDY={lessonsAdded:v73Lessons.length, questionsAdded:v73Lessons.length*5};
})();

;

/* ===== V74 HIGH STUDY: 30 structured lessons (Classes 6-10) ===== */
(function(){
  const v74Lessons=[{"id":"c6-hindi-v74-1","title":"मुहावरे और उनका प्रयोग","icon":"📘","content":"मुहावरा ऐसा प्रचलित वाक्यांश है जिसका अर्थ उसके शब्दों के सीधे अर्थ से अलग हो सकता है। सही अर्थ समझकर ही उसे वाक्य में प्रयोग करना चाहिए।","quiz":[{"q":"“आँखों का तारा” का अर्थ क्या है?","options":["बहुत प्रिय","बहुत दूर","बहुत तेज़","बहुत बड़ा"],"correct":"बहुत प्रिय"},{"q":"“दाँत खट्टे करना” का अर्थ है?","options":["बुरी तरह हरा देना","खाना खाना","हँसना","सो जाना"],"correct":"बुरी तरह हरा देना"},{"q":"मुहावरे का प्रयोग किससे लेखन प्रभावी हो सकता है?","options":["भाव स्पष्ट करने से","शब्द मिटाने से","वाक्य अधूरा करने से","केवल गिनती से"],"correct":"भाव स्पष्ट करने से"},{"q":"“नाक में दम करना” किस अर्थ में आता है?","options":["बहुत परेशान करना","शांत करना","सुलाना","बुलाना"],"correct":"बहुत परेशान करना"},{"q":"मुहावरे को समझने के लिए क्या जरूरी है?","options":["उसका प्रचलित अर्थ","केवल हर शब्द का अलग अर्थ","केवल उच्चारण","केवल लंबाई"],"correct":"उसका प्रचलित अर्थ"}]},{"id":"c6-hindi-v74-2","title":"अनुच्छेद लेखन","icon":"📘","content":"अनुच्छेद में एक मुख्य विचार होना चाहिए। शुरुआत में विषय का परिचय, बीच में संबंधित बातें और अंत में छोटा निष्कर्ष दिया जा सकता है।","quiz":[{"q":"एक अनुच्छेद में मुख्य रूप से कितने विचार पर ध्यान देना अच्छा है?","options":["एक मुख्य विचार","दस असंबंधित विचार","केवल प्रश्न","कोई विचार नहीं"],"correct":"एक मुख्य विचार"},{"q":"अनुच्छेद की शुरुआत में क्या दिया जा सकता है?","options":["विषय का परिचय","केवल निष्कर्ष","केवल हस्ताक्षर","केवल संख्या"],"correct":"विषय का परिचय"},{"q":"वाक्यों का क्रम कैसा होना चाहिए?","options":["तार्किक","बिना क्रम","असंबंधित","उलटा हमेशा"],"correct":"तार्किक"},{"q":"अंत में क्या दिया जा सकता है?","options":["संक्षिप्त निष्कर्ष","नया विषय","केवल शीर्षक","केवल चित्र"],"correct":"संक्षिप्त निष्कर्ष"},{"q":"अच्छा अनुच्छेद कैसा होता है?","options":["स्पष्ट और विषय से जुड़ा","असंबंधित","केवल एक शब्द का","बिना अर्थ का"],"correct":"स्पष्ट और विषय से जुड़ा"}]},{"id":"c6-english-v74-1","title":"Adjectives and Degrees","icon":"📘","content":"Adjectives describe nouns or pronouns. They can sometimes show comparison through positive, comparative and superlative forms.","quiz":[{"q":"In “a tall tree”, which word is the adjective?","options":["tall","tree","a","the"],"correct":"tall"},{"q":"Comparative form of “small” is ___.","options":["smaller","smallest","small","more small"],"correct":"smaller"},{"q":"Superlative form of “bright” is ___.","options":["brightest","brighter","bright","more bright"],"correct":"brightest"},{"q":"Adjectives mainly describe ___.","options":["nouns or pronouns","verbs only","punctuation","numbers only"],"correct":"nouns or pronouns"},{"q":"Which is a comparative adjective?","options":["faster","fastest","fast","quickly"],"correct":"faster"}]},{"id":"c6-english-v74-2","title":"Simple Past Tense","icon":"📘","content":"The simple past tense describes completed actions in the past. Regular verbs often take -ed, while irregular verbs have special forms.","quiz":[{"q":"Which sentence is in the simple past?","options":["She visited Delhi.","She visits Delhi.","She is visiting Delhi.","She will visit Delhi."],"correct":"She visited Delhi."},{"q":"Past form of “play” is ___.","options":["played","plays","playing","player"],"correct":"played"},{"q":"Past form of “go” is ___.","options":["went","goed","goes","going"],"correct":"went"},{"q":"Simple past usually describes an action that is ___.","options":["completed in the past","happening now","always future","only a question"],"correct":"completed in the past"},{"q":"Which is an irregular past form?","options":["saw","walked","played","jumped"],"correct":"saw"}]},{"id":"c6-math-v74-1","title":"पूर्णांक और संख्या रेखा","icon":"📘","content":"पूर्णांकों में धनात्मक संख्याएँ, ऋणात्मक संख्याएँ और शून्य शामिल होते हैं। संख्या रेखा पर दाईं ओर की संख्या बड़ी और बाईं ओर की संख्या छोटी होती है।","quiz":[{"q":"-3 और 2 में बड़ी संख्या कौन है?","options":["2","-3","दोनों बराबर","0"],"correct":"2"},{"q":"संख्या रेखा पर -5 के दाईं ओर कौन है?","options":["-4","-6","-7","-8"],"correct":"-4"},{"q":"शून्य से छोटी संख्या कैसी होती है?","options":["ऋणात्मक","धनात्मक","हमेशा भिन्न","हमेशा दशमलव"],"correct":"ऋणात्मक"},{"q":"|-7| का मान क्या है?","options":["7","-7","0","1"],"correct":"7"},{"q":"कौन-सा युग्म पूर्णांक है?","options":["-2 और 5","1/2 और 2/3","0.5 और 1.5","√2 और π"],"correct":"-2 और 5"}]},{"id":"c6-math-v74-2","title":"भिन्नों की तुलना","icon":"📘","content":"समान हर वाली भिन्नों में बड़े अंश वाली भिन्न बड़ी होती है। अलग हर वाली भिन्नों की तुलना करने के लिए समान हर बनाना उपयोगी है।","quiz":[{"q":"3/7 और 5/7 में बड़ी कौन है?","options":["5/7","3/7","दोनों बराबर","1/7"],"correct":"5/7"},{"q":"1/2 और 1/4 में बड़ी कौन है?","options":["1/2","1/4","दोनों बराबर","0"],"correct":"1/2"},{"q":"समान हर में तुलना किससे की जाती है?","options":["अंश से","केवल हर से","दशमलव बिंदु से","चिह्न से"],"correct":"अंश से"},{"q":"2/3 और 4/6 का संबंध क्या है?","options":["बराबर","पहली छोटी","पहली बड़ी","कोई संबंध नहीं"],"correct":"बराबर"},{"q":"भिन्नों की तुलना में समान हर बनाना क्यों उपयोगी है?","options":["तुलना आसान होती है","भिन्न मिट जाती है","अंश बदल जाता है","उत्तर हमेशा 1 होता है"],"correct":"तुलना आसान होती है"}]},{"id":"c7-hindi-v74-1","title":"समास का परिचय","icon":"📘","content":"दो या दो से अधिक शब्दों के मेल से बने संक्षिप्त शब्द को समासिक शब्द कहा जाता है। समास का अर्थ समझने के लिए उसका विग्रह करना उपयोगी है।","quiz":[{"q":"समास का संबंध किससे है?","options":["शब्दों के संक्षिप्त मेल से","केवल वाक्य के अंत से","केवल विराम से","केवल संख्या से"],"correct":"शब्दों के संक्षिप्त मेल से"},{"q":"समासिक शब्द का विस्तार क्या कहलाता है?","options":["विग्रह","अनुवाद","उच्चारण","विराम"],"correct":"विग्रह"},{"q":"“राजपुत्र” का विग्रह क्या हो सकता है?","options":["राजा का पुत्र","राजा और पुत्र दोनों अलग","पुत्र का राजा","केवल राजा"],"correct":"राजा का पुत्र"},{"q":"समास से भाषा कैसी हो सकती है?","options":["संक्षिप्त और प्रभावी","हमेशा लंबी","अर्थहीन","बिना शब्दों की"],"correct":"संक्षिप्त और प्रभावी"},{"q":"विग्रह का उद्देश्य क्या है?","options":["समासिक शब्द का संबंध स्पष्ट करना","शब्द मिटाना","केवल उच्चारण बदलना","केवल संख्या बताना"],"correct":"समासिक शब्द का संबंध स्पष्ट करना"}]},{"id":"c7-hindi-v74-2","title":"काल के प्रकार","icon":"📘","content":"क्रिया के समय को काल कहते हैं। सामान्य रूप से वर्तमान काल वर्तमान समय, भूतकाल बीते समय और भविष्यत् काल आने वाले समय को व्यक्त करता है।","quiz":[{"q":"“राम पढ़ता है” किस काल का उदाहरण है?","options":["वर्तमान","भूत","भविष्यत्","कोई नहीं"],"correct":"वर्तमान"},{"q":"“राम पढ़ा” किस काल का उदाहरण है?","options":["भूत","वर्तमान","भविष्यत्","सर्वनाम"],"correct":"भूत"},{"q":"“राम पढ़ेगा” किस काल का उदाहरण है?","options":["भविष्यत्","वर्तमान","भूत","विशेषण"],"correct":"भविष्यत्"},{"q":"काल किससे जुड़ा है?","options":["क्रिया के समय से","केवल संज्ञा से","केवल लिंग से","केवल वचन से"],"correct":"क्रिया के समय से"},{"q":"“वे कल आएँगे” में समय कौन-सा है?","options":["भविष्य","वर्तमान","भूत","अनिश्चित"],"correct":"भविष्य"}]},{"id":"c7-english-v74-1","title":"Modal Verbs","icon":"📘","content":"Modal verbs such as can, may, should and must express ability, possibility, advice or necessity.","quiz":[{"q":"“You can swim” expresses ___.","options":["ability","necessity","past time","comparison"],"correct":"ability"},{"q":"“You should study” expresses ___.","options":["advice","ability only","past action","place"],"correct":"advice"},{"q":"“You must wear a helmet” expresses ___.","options":["necessity","possibility only","permission only","past time"],"correct":"necessity"},{"q":"Which modal can show possibility?","options":["may","must only","should not","did"],"correct":"may"},{"q":"Modal verbs are followed by ___.","options":["the base form of a verb","always -ed","a noun only","a punctuation mark"],"correct":"the base form of a verb"}]},{"id":"c7-english-v74-2","title":"Active and Passive Voice","icon":"📘","content":"In active voice, the subject performs the action. In passive voice, the subject receives the action; the form of the verb changes accordingly.","quiz":[{"q":"In active voice, who usually performs the action?","options":["the subject","the object only","the punctuation","the adjective"],"correct":"the subject"},{"q":"“Ravi wrote the letter” is ___.","options":["active","passive","question only","future"],"correct":"active"},{"q":"Passive voice focuses more on ___.","options":["the receiver of the action","the spelling only","the subject's name always","the title"],"correct":"the receiver of the action"},{"q":"“The cake was eaten by Maya” is ___.","options":["passive","active","present continuous","imperative"],"correct":"passive"},{"q":"Why use passive voice?","options":["When the action or receiver is important","Only to shorten every sentence","To remove all verbs","To make every sentence a question"],"correct":"When the action or receiver is important"}]},{"id":"c7-math-v74-1","title":"अनुपात और समानुपात","icon":"📘","content":"अनुपात दो समान प्रकार की राशियों की तुलना करता है। समानुपात में दो अनुपात बराबर होते हैं, जैसे 2:3 = 4:6।","quiz":[{"q":"2:3 और 4:6 का संबंध क्या है?","options":["समानुपात","असमान","भिन्न इकाइयाँ","कोई संबंध नहीं"],"correct":"समानुपात"},{"q":"अनुपात में किन राशियों की तुलना करनी चाहिए?","options":["समान प्रकार की राशियों की","हमेशा अलग प्रकार की","केवल समय की","केवल क्षेत्रफल की"],"correct":"समान प्रकार की राशियों की"},{"q":"3:5 में कुल भाग कितने हैं?","options":["8","15","2","5"],"correct":"8"},{"q":"यदि 2:5 = x:10, तो x क्या है?","options":["4","5","2","10"],"correct":"4"},{"q":"समानुपात का अर्थ क्या है?","options":["दो अनुपात बराबर होना","दो संख्याएँ घटाना","दो कोण जोड़ना","केवल गुणा करना"],"correct":"दो अनुपात बराबर होना"}]},{"id":"c7-math-v74-2","title":"बीजीय व्यंजक का सरलीकरण","icon":"📘","content":"बीजीय व्यंजक में समान पदों को जोड़ा या घटाया जा सकता है। जैसे 3x + 2x = 5x, क्योंकि दोनों पदों में x समान है।","quiz":[{"q":"3x + 2x = ?","options":["5x","6x","5","x"],"correct":"5x"},{"q":"7a - 3a = ?","options":["4a","10a","4","a"],"correct":"4a"},{"q":"समान पदों में क्या समान होता है?","options":["चर और उसकी घात","केवल गुणांक","केवल चिह्न","केवल संख्या"],"correct":"चर और उसकी घात"},{"q":"2x + 3y को सीधे 5xy लिख सकते हैं?","options":["नहीं","हाँ","हमेशा","केवल x=1 पर"],"correct":"नहीं"},{"q":"x + x + x = ?","options":["3x","x³","3","x"],"correct":"3x"}]},{"id":"c8-hindi-v74-1","title":"वाक्य-भेद","icon":"📘","content":"वाक्यों को उनके अर्थ और उद्देश्य के आधार पर अलग-अलग प्रकारों में समझा जाता है, जैसे कथन, प्रश्न, आज्ञा/अनुरोध और विस्मयादिबोधक वाक्य।","quiz":[{"q":"“तुम कहाँ जा रहे हो?” कैसा वाक्य है?","options":["प्रश्नवाचक","विधानवाचक","विस्मयादिबोधक","आज्ञावाचक"],"correct":"प्रश्नवाचक"},{"q":"“दरवाज़ा बंद करो।” कैसा वाक्य है?","options":["आज्ञावाचक","प्रश्नवाचक","विस्मयादिबोधक","विधानवाचक"],"correct":"आज्ञावाचक"},{"q":"“आज मौसम अच्छा है।” कैसा वाक्य है?","options":["विधानवाचक","प्रश्नवाचक","आज्ञावाचक","विस्मयादिबोधक"],"correct":"विधानवाचक"},{"q":"“वाह! कितना सुंदर दृश्य है!” कैसा वाक्य है?","options":["विस्मयादिबोधक","प्रश्नवाचक","आज्ञावाचक","विधानवाचक"],"correct":"विस्मयादिबोधक"},{"q":"वाक्य-भेद समझने में क्या देखा जाता है?","options":["अर्थ और उद्देश्य","केवल लंबाई","केवल अक्षर","केवल विराम"],"correct":"अर्थ और उद्देश्य"}]},{"id":"c8-hindi-v74-2","title":"संधि का परिचय","icon":"📘","content":"दो वर्णों या शब्दांशों के मेल से होने वाले ध्वनि-परिवर्तन को संधि कहा जाता है। संधि-विच्छेद में संयुक्त रूप को अलग करके मूल रूप समझा जाता है।","quiz":[{"q":"संधि किससे जुड़ी है?","options":["वर्णों के मेल और परिवर्तन से","केवल विराम से","केवल संख्या से","केवल अनुच्छेद से"],"correct":"वर्णों के मेल और परिवर्तन से"},{"q":"संधि-विच्छेद का उद्देश्य क्या है?","options":["संयुक्त रूप को अलग समझना","शब्द लंबा करना","वाक्य मिटाना","केवल उच्चारण बदलना"],"correct":"संयुक्त रूप को अलग समझना"},{"q":"संधि में क्या बदल सकता है?","options":["ध्वनि या वर्ण का रूप","केवल अर्थ हमेशा","केवल पन्ना","केवल चित्र"],"correct":"ध्वनि या वर्ण का रूप"},{"q":"संधि और समास क्या बिल्कुल एक ही हैं?","options":["नहीं","हाँ","केवल गणित में","केवल English में"],"correct":"नहीं"},{"q":"संधि समझने के लिए क्या देखना उपयोगी है?","options":["मिलने वाले वर्णों का रूप","केवल शब्द की लंबाई","केवल विराम","केवल संख्या"],"correct":"मिलने वाले वर्णों का रूप"}]},{"id":"c8-english-v74-1","title":"Direct and Reported Speech","icon":"📘","content":"Direct speech gives a speaker’s exact words, while reported speech conveys the meaning without repeating the exact wording. Pronouns and tense may change in reported speech.","quiz":[{"q":"Direct speech gives ___.","options":["the speaker’s exact words","only a summary","only a title","only a question"],"correct":"the speaker’s exact words"},{"q":"Reported speech mainly conveys ___.","options":["the meaning of what was said","only punctuation","only spelling","only the speaker’s name"],"correct":"the meaning of what was said"},{"q":"Which punctuation commonly marks direct speech?","options":["quotation marks","a colon only","a slash","a bracket only"],"correct":"quotation marks"},{"q":"In reported speech, pronouns may ___.","options":["change","never change","be removed always","become numbers"],"correct":"change"},{"q":"Why use reported speech?","options":["To report what someone said","To count words","To change nouns into numbers","To remove meaning"],"correct":"To report what someone said"}]},{"id":"c8-english-v74-2","title":"Paragraph Coherence","icon":"📘","content":"A coherent paragraph has a clear topic sentence, supporting details and logical links. Linking words such as however, therefore and because help connect ideas.","quiz":[{"q":"A topic sentence gives the ___.","options":["main idea","last punctuation","page number","author’s address"],"correct":"main idea"},{"q":"Supporting sentences should ___.","options":["develop the main idea","start unrelated topics","remove the topic","only repeat one word"],"correct":"develop the main idea"},{"q":"Which word can show contrast?","options":["however","therefore","because","also"],"correct":"however"},{"q":"Which word can show a result?","options":["therefore","however","although","but"],"correct":"therefore"},{"q":"Coherence means ideas are ___.","options":["logically connected","random","unrelated","only repeated"],"correct":"logically connected"}]},{"id":"c8-math-v74-1","title":"रैखिक समीकरण","icon":"📘","content":"एक चर वाले रैखिक समीकरण में चर की उच्चतम घात 1 होती है। समीकरण को संतुलित रखते हुए दोनों पक्षों पर समान क्रिया करके हल निकाला जा सकता है।","quiz":[{"q":"2x + 3 = 9 में x क्या है?","options":["3","6","2","12"],"correct":"3"},{"q":"x - 5 = 7 में x क्या है?","options":["12","2","5","7"],"correct":"12"},{"q":"समीकरण हल करते समय दोनों पक्षों पर क्या करना चाहिए?","options":["समान क्रिया","केवल बाएँ पक्ष पर","केवल दाएँ पक्ष पर","कुछ नहीं"],"correct":"समान क्रिया"},{"q":"3x = 15 में x क्या है?","options":["5","45","12","3"],"correct":"5"},{"q":"रैखिक समीकरण में चर की उच्चतम घात क्या होती है?","options":["1","2","3","0"],"correct":"1"}]},{"id":"c8-math-v74-2","title":"घन और घनाभ का पृष्ठीय क्षेत्रफल","icon":"📘","content":"घन के सभी किनारे समान होते हैं। घनाभ में लंबाई, चौड़ाई और ऊँचाई अलग हो सकती हैं। पृष्ठीय क्षेत्रफल निकालते समय सभी बाहरी फलकों के क्षेत्रफल को जोड़ा जाता है।","quiz":[{"q":"घन के कितने समान वर्गाकार फलक होते हैं?","options":["6","4","8","12"],"correct":"6"},{"q":"घन की भुजा a हो तो कुल पृष्ठीय क्षेत्रफल क्या है?","options":["6a²","a³","4a²","3a"],"correct":"6a²"},{"q":"घनाभ में किन मापों की जरूरत होती है?","options":["लंबाई, चौड़ाई और ऊँचाई","केवल लंबाई","केवल ऊँचाई","केवल विकर्ण"],"correct":"लंबाई, चौड़ाई और ऊँचाई"},{"q":"पृष्ठीय क्षेत्रफल किसकी माप है?","options":["बाहरी सतह का क्षेत्रफल","अंदर की क्षमता","केवल लंबाई","केवल कोण"],"correct":"बाहरी सतह का क्षेत्रफल"},{"q":"क्षेत्रफल की इकाई कैसी होती है?","options":["वर्ग इकाई","घन इकाई","केवल मीटर","केवल सेकंड"],"correct":"वर्ग इकाई"}]},{"id":"c9-hindi-v74-1","title":"तर्कपूर्ण लेखन","icon":"📘","content":"तर्कपूर्ण लेखन में स्पष्ट दावा, कारण और उपयुक्त प्रमाण दिए जाते हैं। विरोधी विचार का सम्मानपूर्वक उल्लेख करके अपने निष्कर्ष को मजबूत बनाया जा सकता है।","quiz":[{"q":"तर्कपूर्ण लेखन में मुख्य दावा क्या होता है?","options":["मुख्य विचार या स्थिति","केवल शीर्षक","केवल तारीख","केवल प्रश्न"],"correct":"मुख्य विचार या स्थिति"},{"q":"दावे को मजबूत करने के लिए क्या उपयोगी है?","options":["कारण और प्रमाण","केवल सजावट","केवल दोहराव","केवल लंबाई"],"correct":"कारण और प्रमाण"},{"q":"विरोधी विचार के साथ कैसा व्यवहार होना चाहिए?","options":["सम्मानपूर्वक","बिना पढ़े","मजाक में","असंबंधित"],"correct":"सम्मानपूर्वक"},{"q":"प्रमाण कैसा होना चाहिए?","options":["दावे से संबंधित","दावे से असंबंधित","काल्पनिक ही","छिपा हुआ"],"correct":"दावे से संबंधित"},{"q":"निष्कर्ष में क्या होना चाहिए?","options":["मुख्य तर्क का संक्षेप","नया असंबंधित विषय","केवल चित्र","केवल प्रश्न"],"correct":"मुख्य तर्क का संक्षेप"}]},{"id":"c9-hindi-v74-2","title":"कविता में बिंब और भाव","icon":"📘","content":"कविता में बिंब ऐसे शब्द-चित्र बनाते हैं जिनसे पाठक दृश्य, ध्वनि या अनुभूति की कल्पना कर सकता है। कविता का भाव उसके केंद्रीय अनुभव या भावना को व्यक्त करता है।","quiz":[{"q":"बिंब किसका निर्माण करता है?","options":["शब्दों से कल्पनात्मक चित्र","केवल संख्या","केवल व्याकरण","केवल शीर्षक"],"correct":"शब्दों से कल्पनात्मक चित्र"},{"q":"कविता का भाव किससे जुड़ा है?","options":["केंद्रीय भावना या अनुभव से","केवल लंबाई से","केवल तुक से","केवल पृष्ठ संख्या से"],"correct":"केंद्रीय भावना या अनुभव से"},{"q":"“ठंडी हवा की सरसराहट” किस तरह का अनुभव जगा सकती है?","options":["ध्वनि और स्पर्श की कल्पना","केवल गणना","केवल व्याकरण","केवल तारीख"],"correct":"ध्वनि और स्पर्श की कल्पना"},{"q":"कविता पढ़ते समय क्या देखना उपयोगी है?","options":["शब्द-चित्र और भावना","केवल अक्षरों की संख्या","केवल शीर्षक","केवल विराम"],"correct":"शब्द-चित्र और भावना"},{"q":"बिंब कविता को कैसे प्रभावित कर सकता है?","options":["कल्पना को जीवंत बनाता है","अर्थ मिटाता है","वाक्य हटाता है","केवल लंबा करता है"],"correct":"कल्पना को जीवंत बनाता है"}]},{"id":"c9-english-v74-1","title":"Subject-Verb Agreement in Complex Sentences","icon":"📘","content":"In longer sentences, identify the real subject before choosing the verb. Words between the subject and verb do not usually change the agreement.","quiz":[{"q":"In “The box of books is heavy”, the subject is ___.","options":["box","books","heavy","of"],"correct":"box"},{"q":"Choose: “The players on the field ___ ready.”","options":["are","is","was","has"],"correct":"are"},{"q":"What should you identify first?","options":["the real subject","the last word","the punctuation only","the longest phrase"],"correct":"the real subject"},{"q":"Choose: “My brother, along with his friends, ___ coming.”","options":["is","are","were","be"],"correct":"is"},{"q":"Why can complex sentences be tricky?","options":["Extra words can come between subject and verb","They have no verbs","They have no subjects","They are always questions"],"correct":"Extra words can come between subject and verb"}]},{"id":"c9-english-v74-2","title":"Writing a Strong Conclusion","icon":"📘","content":"A strong conclusion restates the main idea in fresh words, summarizes key points and leaves the reader with a clear final thought. It should not introduce an unrelated major idea.","quiz":[{"q":"A conclusion should mainly ___.","options":["wrap up the main argument","start a new unrelated topic","repeat every sentence","remove the main idea"],"correct":"wrap up the main argument"},{"q":"Should a conclusion introduce a completely new major idea?","options":["No","Yes, always","Only in titles","Only in questions"],"correct":"No"},{"q":"A conclusion may restate the main idea using ___.","options":["fresh words","exact random words","only numbers","only punctuation"],"correct":"fresh words"},{"q":"What can a conclusion leave the reader with?","options":["a clear final thought","an unfinished sentence","an unrelated list","only a title"],"correct":"a clear final thought"},{"q":"A good conclusion should be ___.","options":["connected to the whole text","unrelated","only one word","without meaning"],"correct":"connected to the whole text"}]},{"id":"c9-math-v74-1","title":"दो चर वाले रैखिक समीकरण का परिचय","icon":"📘","content":"दो चर वाले रैखिक समीकरण में x और y जैसे दो चर हो सकते हैं। एक ही समीकरण के कई युग्म हल हो सकते हैं; दो स्वतंत्र समीकरणों से एक निश्चित युग्म मिल सकता है।","quiz":[{"q":"x + y = 5 में कितने चर हैं?","options":["2","1","3","0"],"correct":"2"},{"q":"x=2, y=3 क्या x+y=5 का हल है?","options":["हाँ","नहीं","केवल y=0 पर","केवल x=0 पर"],"correct":"हाँ"},{"q":"दो चर वाले समीकरण में चर कौन हो सकते हैं?","options":["x और y","केवल 5","केवल 0","केवल कोण"],"correct":"x और y"},{"q":"एक ही दो-चर समीकरण के कितने हल हो सकते हैं?","options":["कई","हमेशा केवल एक","हमेशा शून्य","कोई नहीं"],"correct":"कई"},{"q":"दो समीकरणों का उपयोग किसके लिए किया जा सकता है?","options":["एक निश्चित युग्म हल खोजने के लिए","केवल जोड़ सीखने के लिए","केवल क्षेत्रफल के लिए","केवल समय के लिए"],"correct":"एक निश्चित युग्म हल खोजने के लिए"}]},{"id":"c9-math-v74-2","title":"समांतर चतुर्भुज के गुण","icon":"📘","content":"समांतर चतुर्भुज में विपरीत भुजाएँ समांतर और बराबर होती हैं। इसके विपरीत कोण बराबर होते हैं और विकर्ण एक-दूसरे को समद्विभाजित करते हैं।","quiz":[{"q":"समांतर चतुर्भुज की विपरीत भुजाएँ कैसी होती हैं?","options":["समांतर और बराबर","केवल बराबर","केवल लंब","हमेशा तिरछी"],"correct":"समांतर और बराबर"},{"q":"विपरीत कोण कैसे होते हैं?","options":["बराबर","हमेशा 90°","हमेशा अलग","शून्य"],"correct":"बराबर"},{"q":"विकर्ण क्या करते हैं?","options":["एक-दूसरे को समद्विभाजित करते हैं","हमेशा लंब होते हैं","हमेशा बराबर होते हैं","कुछ नहीं"],"correct":"एक-दूसरे को समद्विभाजित करते हैं"},{"q":"समांतर चतुर्भुज में विपरीत भुजाओं की दिशा कैसी होती है?","options":["समांतर","लंबवत हमेशा","एक ही रेखा","कोई निश्चित नहीं"],"correct":"समांतर"},{"q":"समांतर चतुर्भुज की चार भुजाएँ कैसी होती हैं?","options":["दो-दो विपरीत भुजाएँ बराबर","चारों हमेशा बराबर","सभी अलग","कोई भुजा नहीं"],"correct":"दो-दो विपरीत भुजाएँ बराबर"}]},{"id":"c10-hindi-v74-1","title":"रिपोर्ट लेखन","icon":"📘","content":"रिपोर्ट किसी घटना या गतिविधि की तथ्यात्मक और क्रमबद्ध जानकारी देती है। इसमें शीर्षक, स्थान/समय, मुख्य घटनाएँ और आवश्यक विवरण स्पष्ट भाषा में दिए जाते हैं।","quiz":[{"q":"रिपोर्ट का मुख्य उद्देश्य क्या है?","options":["घटना की तथ्यात्मक जानकारी देना","कहानी को कल्पना से बदलना","केवल प्रश्न पूछना","केवल चित्र बनाना"],"correct":"घटना की तथ्यात्मक जानकारी देना"},{"q":"रिपोर्ट में क्या स्पष्ट होना चाहिए?","options":["घटना और उसके विवरण","केवल लेखक का नाम","केवल रंग","केवल लंबाई"],"correct":"घटना और उसके विवरण"},{"q":"रिपोर्ट की भाषा कैसी होनी चाहिए?","options":["स्पष्ट और तथ्यात्मक","अस्पष्ट","केवल भावुक","बिना क्रम"],"correct":"स्पष्ट और तथ्यात्मक"},{"q":"रिपोर्ट में समय और स्थान क्यों उपयोगी हैं?","options":["घटना का संदर्भ समझने के लिए","केवल सजावट के लिए","केवल प्रश्न बनाने के लिए","केवल शीर्षक के लिए"],"correct":"घटना का संदर्भ समझने के लिए"},{"q":"रिपोर्ट में घटनाओं का क्रम कैसा होना चाहिए?","options":["तार्किक और क्रमबद्ध","बिना क्रम","हमेशा उलटा","असंबंधित"],"correct":"तार्किक और क्रमबद्ध"}]},{"id":"c10-hindi-v74-2","title":"सारांश और भावार्थ में अंतर","icon":"📘","content":"सारांश में किसी पाठ की मुख्य बातों को संक्षेप में प्रस्तुत किया जाता है, जबकि भावार्थ में मूल विचार या भावना को अपने शब्दों में स्पष्ट किया जाता है।","quiz":[{"q":"सारांश में क्या रखा जाता है?","options":["मुख्य बातें","हर छोटी बात","केवल शीर्षक","केवल प्रश्न"],"correct":"मुख्य बातें"},{"q":"भावार्थ किसे स्पष्ट करता है?","options":["मूल भाव या विचार","केवल शब्दों की गिनती","केवल तारीख","केवल लेखक का नाम"],"correct":"मूल भाव या विचार"},{"q":"सारांश कैसा होता है?","options":["मूल पाठ से छोटा","मूल पाठ से हमेशा लंबा","बिल्कुल समान","केवल एक शब्द"],"correct":"मूल पाठ से छोटा"},{"q":"अपने शब्दों में लिखना किसमें उपयोगी है?","options":["सारांश और भावार्थ दोनों में","किसी में नहीं","केवल शीर्षक में","केवल प्रश्न में"],"correct":"सारांश और भावार्थ दोनों में"},{"q":"सारांश बनाते समय क्या हटाना चाहिए?","options":["अनावश्यक विवरण और दोहराव","मुख्य विचार","जरूरी तथ्य","केंद्रीय संदेश"],"correct":"अनावश्यक विवरण और दोहराव"}]},{"id":"c10-english-v74-1","title":"Formal Letter: Complaint and Request","icon":"📘","content":"A formal letter should state its purpose clearly, provide relevant details, use polite language and end with an appropriate closing.","quiz":[{"q":"A formal complaint letter should state the ___.","options":["problem clearly","joke first","author’s favorite color","only title"],"correct":"problem clearly"},{"q":"Formal requests should use ___.","options":["polite language","rude language","random slang","no verbs"],"correct":"polite language"},{"q":"What details should be included?","options":["relevant details","every unrelated detail","only a picture","only a number"],"correct":"relevant details"},{"q":"A formal letter needs an appropriate ___.","options":["closing","game","equation","map"],"correct":"closing"},{"q":"Why organize a formal letter clearly?","options":["So the reader understands the purpose and details","To make it confusing","To remove the request","To add unrelated ideas"],"correct":"So the reader understands the purpose and details"}]},{"id":"c10-english-v74-2","title":"Reading Inference","icon":"📘","content":"An inference is a reasonable conclusion based on clues in a text and what the reader already knows. It should be supported by evidence from the passage.","quiz":[{"q":"An inference is a ___.","options":["reasonable conclusion from clues","random guess","title only","direct quotation only"],"correct":"reasonable conclusion from clues"},{"q":"What supports an inference?","options":["textual clues and reasoning","only imagination","only the title","only one letter"],"correct":"textual clues and reasoning"},{"q":"Should an inference be completely unrelated to the text?","options":["No","Yes","Always","Only in poems"],"correct":"No"},{"q":"Why use evidence when making an inference?","options":["To justify the conclusion","To make text longer","To remove clues","To change the topic"],"correct":"To justify the conclusion"},{"q":"Inference requires the reader to ___.","options":["connect clues and think","copy every sentence","ignore the text","count punctuation"],"correct":"connect clues and think"}]},{"id":"c10-math-v74-1","title":"अंकगणितीय प्रगति का परिचय","icon":"📘","content":"अंकगणितीय प्रगति में क्रमागत पदों के बीच अंतर समान रहता है। जैसे 3, 7, 11, 15 में समान अंतर 4 है।","quiz":[{"q":"3, 7, 11, 15 में समान अंतर क्या है?","options":["4","3","7","11"],"correct":"4"},{"q":"अंकगणितीय प्रगति में क्या समान रहता है?","options":["क्रमागत पदों का अंतर","हर पद","केवल पहला पद","केवल अंतिम पद"],"correct":"क्रमागत पदों का अंतर"},{"q":"5, 10, 15, 20 का अगला पद क्या है?","options":["25","30","20","35"],"correct":"25"},{"q":"2, 5, 8, 11 में अंतर क्या है?","options":["3","2","5","4"],"correct":"3"},{"q":"यदि पहला पद 4 और अंतर 2 है, तो अगला पद क्या है?","options":["6","8","2","4"],"correct":"6"}]},{"id":"c10-math-v74-2","title":"वृत्त से जुड़े क्षेत्रफल","icon":"📘","content":"वृत्त का क्षेत्रफल πr² और परिधि 2πr होती है, जहाँ r त्रिज्या है। प्रश्न में π का मान आवश्यकता के अनुसार लिया जा सकता है।","quiz":[{"q":"वृत्त का क्षेत्रफल क्या है?","options":["πr²","2πr","πd","r²"],"correct":"πr²"},{"q":"वृत्त की परिधि क्या है?","options":["2πr","πr²","r/2","π+r"],"correct":"2πr"},{"q":"त्रिज्या 7 cm हो तो क्षेत्रफल का सूत्र क्या लगेगा?","options":["π×7²","2π×7","7²/π","π+7"],"correct":"π×7²"},{"q":"व्यास और त्रिज्या का संबंध क्या है?","options":["व्यास = 2 × त्रिज्या","व्यास = त्रिज्या/2","व्यास = त्रिज्या²","व्यास = πr"],"correct":"व्यास = 2 × त्रिज्या"},{"q":"क्षेत्रफल की इकाई कैसी होती है?","options":["वर्ग इकाई","घन इकाई","रेखीय इकाई","समय इकाई"],"correct":"वर्ग इकाई"}]}];
  for(const l of v74Lessons){
    const m=l.id.match(/^c(\d+)-(hindi|english|math)-/);
    if(!m) continue;
    const c=m[1], s=m[2];
    if(STUDY_DATA[c]?.subjects?.[s]){
      if(!STUDY_DATA[c].subjects[s].lessons.some(x=>x.id===l.id)) STUDY_DATA[c].subjects[s].lessons.push(l);
    }
  }
  window.PATHSHALA_V74_HIGH_STUDY={lessonsAdded:v74Lessons.length,questionsAdded:v74Lessons.length*5};
})();

;

/* ===== V75 HIGH STUDY: 30 deeper lessons for Classes 6-10 ===== */
(function(){
 const v75Lessons=[{"id":"c6-hindi-v75-1","title":"विलोम शब्द और संदर्भ","icon":"📝","content":"विलोम शब्द विपरीत अर्थ बताते हैं। संदर्भ देखकर सही विलोम चुनना चाहिए।","quiz":[{"q":"“लाभ” का विलोम?","options":["हानि","धन","यश","सुख"],"correct":"हानि"},{"q":"“आरंभ” का विलोम?","options":["अंत","प्रारंभ","उदय","शुरुआत"],"correct":"अंत"},{"q":"“सत्य” का विलोम?","options":["असत्य","सरल","न्याय","सुंदर"],"correct":"असत्य"},{"q":"विलोम पहचानने में मुख्य बात?","options":["अर्थ","लंबाई","रंग","पृष्ठ"],"correct":"अर्थ"},{"q":"“उन्नति” का विलोम?","options":["अवनति","प्रगति","विकास","सफलता"],"correct":"अवनति"}]},{"id":"c6-hindi-v75-2","title":"वर्णनात्मक लेखन","icon":"📝","content":"वर्णनात्मक लेखन में व्यक्ति, स्थान, वस्तु या घटना की विशेषताएँ क्रम से और स्पष्ट भाषा में लिखी जाती हैं।","quiz":[{"q":"वर्णनात्मक लेखन का उद्देश्य?","options":["विषय का स्पष्ट वर्णन","केवल प्रश्न","केवल गणना","केवल शीर्षक"],"correct":"विषय का स्पष्ट वर्णन"},{"q":"वर्णन में क्या जरूरी है?","options":["उपयुक्त विवरण","असंबंधित बातें","केवल संख्या","बिना क्रम"],"correct":"उपयुक्त विवरण"},{"q":"स्थान का वर्णन करते समय क्या बताया जा सकता है?","options":["विशेषताएँ","केवल नाम","केवल तारीख","केवल प्रश्न"],"correct":"विशेषताएँ"},{"q":"अच्छा वर्णन कैसा होता है?","options":["स्पष्ट और क्रमबद्ध","बिखरा हुआ","असंबंधित","एक शब्द"],"correct":"स्पष्ट और क्रमबद्ध"},{"q":"वर्णन से पहले क्या तय करना अच्छा है?","options":["मुख्य बिंदु","विषय बदलना","उत्तर छिपाना","सिर्फ चित्र"],"correct":"मुख्य बिंदु"}]},{"id":"c6-english-v75-1","title":"Past Continuous","icon":"🔤","content":"The past continuous describes an action that was in progress at a particular time in the past.","quiz":[{"q":"I ___ reading at 8 pm.","options":["was","were","am","be"],"correct":"was"},{"q":"They ___ playing when it rained.","options":["were","was","is","be"],"correct":"were"},{"q":"What follows “was” here?","options":["verb + ing","base verb only","noun only","past participle only"],"correct":"verb + ing"},{"q":"Past continuous often describes an action ___.","options":["in progress around a past time","after every event","without a time","only in the future"],"correct":"in progress around a past time"},{"q":"“She was cooking” is ___.","options":["past continuous","simple present","future","present perfect"],"correct":"past continuous"}]},{"id":"c6-english-v75-2","title":"Countable and Uncountable Nouns","icon":"🔤","content":"Countable nouns can be counted. Uncountable nouns usually name substances or ideas that are not counted as individual units.","quiz":[{"q":"“apples” is usually ___.","options":["countable","uncountable","a verb","an adverb"],"correct":"countable"},{"q":"“water” is usually ___.","options":["uncountable","countable","a pronoun","a verb"],"correct":"uncountable"},{"q":"Which word can take “many”?","options":["books","water","milk","rice"],"correct":"books"},{"q":"Which word can take “much”?","options":["water","books","chairs","apples"],"correct":"water"},{"q":"Why learn this distinction?","options":["To choose determiners correctly","To remove nouns","To change verbs","To add punctuation"],"correct":"To choose determiners correctly"}]},{"id":"c6-math-v75-1","title":"दशमलव का जोड़ और घटाव","icon":"➗","content":"दशमलव संख्याओं को जोड़ते या घटाते समय दशमलव बिंदुओं को एक सीध में रखना उपयोगी है।","quiz":[{"q":"2.5 + 1.3 = ?","options":["3.8","3.5","4.8","2.8"],"correct":"3.8"},{"q":"5.7 - 2.4 = ?","options":["3.3","3.1","2.3","4.3"],"correct":"3.3"},{"q":"दशमलव जोड़ते समय क्या एक सीध में रखें?","options":["दशमलव बिंदु","केवल अंतिम अंक","केवल पहला अंक","इकाई का नाम"],"correct":"दशमलव बिंदु"},{"q":"0.6 + 0.2 = ?","options":["0.8","0.4","0.6","1.2"],"correct":"0.8"},{"q":"4.0 - 1.5 = ?","options":["2.5","3.5","2.0","1.5"],"correct":"2.5"}]},{"id":"c6-math-v75-2","title":"भिन्नों की तुलना","icon":"➗","content":"समान हर वाली भिन्नों में बड़े अंश वाली भिन्न बड़ी होती है। अलग हर वाली भिन्नों की तुलना के लिए समान हर बनाया जा सकता है।","quiz":[{"q":"3/5 और 2/5 में बड़ी कौन?","options":["3/5","2/5","बराबर","1/5"],"correct":"3/5"},{"q":"समान हर में तुलना किससे आसान है?","options":["अंश से","हर के नाम से","रंग से","पृष्ठ से"],"correct":"अंश से"},{"q":"1/2 और 2/4 कैसे हैं?","options":["बराबर","अलग","एक शून्य","तुलना नहीं"],"correct":"बराबर"},{"q":"भिन्न का हर क्या बताता है?","options":["बराबर भागों की कुल संख्या","चुने भागों की संख्या","योग","अंतर"],"correct":"बराबर भागों की कुल संख्या"},{"q":"2/3 में अंश कौन है?","options":["2","3","1","6"],"correct":"2"}]},{"id":"c7-hindi-v75-1","title":"कारक की पहचान","icon":"📝","content":"कारक वाक्य में संज्ञा या सर्वनाम का दूसरे शब्दों से संबंध बताते हैं। “ने”, “को”, “से” आदि संबंध स्पष्ट कर सकते हैं।","quiz":[{"q":"“राम ने फल खाया” में “ने” किसका संकेत है?","options":["कर्ता","कर्म","स्थान","समय"],"correct":"कर्ता"},{"q":"कारक क्या बताता है?","options":["शब्दों का संबंध","केवल लिंग","केवल वचन","केवल काल"],"correct":"शब्दों का संबंध"},{"q":"“मोहन को बुलाओ” में “को” किसका संकेत है?","options":["कर्म","करण","अपादान","अधिकरण"],"correct":"कर्म"},{"q":"“कलम से लिखता है” में “से” किसका संकेत है?","options":["करण","संबोधन","कर्ता","अधिकरण"],"correct":"करण"},{"q":"कारक पहचानने में क्या देखें?","options":["वाक्य में संबंध","लंबाई","रंग","विराम"],"correct":"वाक्य में संबंध"}]},{"id":"c7-hindi-v75-2","title":"तर्कपूर्ण अनुच्छेद","icon":"📝","content":"तर्कपूर्ण अनुच्छेद में मुख्य विचार के समर्थन में कारण, उदाहरण और निष्कर्ष क्रम से दिए जाते हैं।","quiz":[{"q":"तर्कपूर्ण अनुच्छेद में क्या होना चाहिए?","options":["दावा, कारण और उदाहरण","केवल कहानी","केवल प्रश्न","केवल शीर्षक"],"correct":"दावा, कारण और उदाहरण"},{"q":"कारण क्यों दिया जाता है?","options":["विचार का समर्थन करने के लिए","विषय बदलने के लिए","सजावट के लिए","शब्द गिनने के लिए"],"correct":"विचार का समर्थन करने के लिए"},{"q":"उदाहरण का काम क्या है?","options":["बात स्पष्ट करना","बात छिपाना","विषय हटाना","लंबाई बढ़ाना"],"correct":"बात स्पष्ट करना"},{"q":"निष्कर्ष क्या करता है?","options":["मुख्य विचार समेटता है","नया विषय शुरू करता है","केवल प्रश्न देता है","केवल नाम लिखता है"],"correct":"मुख्य विचार समेटता है"},{"q":"भाषा कैसी होनी चाहिए?","options":["स्पष्ट और तार्किक","असंबंधित","अस्पष्ट","बिना क्रम"],"correct":"स्पष्ट और तार्किक"}]},{"id":"c7-english-v75-1","title":"Prepositions of Place","icon":"🔤","content":"Prepositions of place show where something is located, such as in, on, under, beside and between.","quiz":[{"q":"The book is ___ the table.","options":["on","at","to","from"],"correct":"on"},{"q":"The shoes are ___ the bed.","options":["under","between","from","to"],"correct":"under"},{"q":"“Between” is used for ___.","options":["two things or people","one thing","all verbs","all times"],"correct":"two things or people"},{"q":"Which word shows location?","options":["beside","quickly","beautiful","write"],"correct":"beside"},{"q":"Prepositions of place answer ___.","options":["Where?","When?","Why?","How many?"],"correct":"Where?"}]},{"id":"c7-english-v75-2","title":"Paragraph Unity","icon":"🔤","content":"A unified paragraph stays focused on one main idea. Supporting sentences should explain or develop that idea.","quiz":[{"q":"A unified paragraph has ___.","options":["one clear main idea","many unrelated ideas","only questions","only titles"],"correct":"one clear main idea"},{"q":"Supporting sentences should ___.","options":["develop the main idea","change the topic","remove the topic","add random facts"],"correct":"develop the main idea"},{"q":"What improves unity?","options":["Relevant details","Unrelated examples","Random sentences","New topics"],"correct":"Relevant details"},{"q":"A topic sentence introduces the ___.","options":["main idea","page number","punctuation","author biography"],"correct":"main idea"},{"q":"Why avoid unrelated details?","options":["They weaken focus","They add grammar","They change every verb","They shorten the text"],"correct":"They weaken focus"}]},{"id":"c7-math-v75-1","title":"बीजगणितीय व्यंजक","icon":"➗","content":"चर, संख्याएँ और संक्रियाएँ मिलकर बीजगणितीय व्यंजक बना सकते हैं। जैसे 3x + 2।","quiz":[{"q":"3x + 2 में चर कौन है?","options":["x","3","2","+"],"correct":"x"},{"q":"x=4 पर 2x का मान?","options":["8","6","4","2"],"correct":"8"},{"q":"5a में 5 क्या है?","options":["गुणांक","चर","योग","भाजक"],"correct":"गुणांक"},{"q":"x + x = ?","options":["2x","x²","2","x+2"],"correct":"2x"},{"q":"चर का मान बदलने से क्या बदल सकता है?","options":["व्यंजक का मान","गणित का नियम","चर का नाम","केवल चिन्ह"],"correct":"व्यंजक का मान"}]},{"id":"c7-math-v75-2","title":"प्रतिशत का उपयोग","icon":"➗","content":"प्रतिशत किसी मात्रा को 100 के आधार पर व्यक्त करता है। 25% का अर्थ 25/100 या 1/4 है।","quiz":[{"q":"25% = ?","options":["1/4","1/2","1/5","3/4"],"correct":"1/4"},{"q":"50% किसके बराबर है?","options":["1/2","1/4","1/5","2/5"],"correct":"1/2"},{"q":"10% of 200 = ?","options":["20","10","200","2"],"correct":"20"},{"q":"प्रतिशत का आधार क्या है?","options":["100","10","1000","1"],"correct":"100"},{"q":"75% = ?","options":["3/4","1/4","2/3","1/2"],"correct":"3/4"}]},{"id":"c8-hindi-v75-1","title":"संधि के प्रकार","icon":"📝","content":"दो वर्णों या शब्दांशों के मेल से होने वाले परिवर्तन को संधि कहते हैं। स्वर, व्यंजन और विसर्ग इसके प्रमुख प्रकार हैं।","quiz":[{"q":"संधि किसे कहते हैं?","options":["मेल से होने वाला परिवर्तन","विलोम शब्द","छंद","विराम"],"correct":"मेल से होने वाला परिवर्तन"},{"q":"प्रमुख संधि प्रकार?","options":["स्वर, व्यंजन, विसर्ग","लिंग, वचन, काल","कर्ता, कर्म, करण","उपमा, रूपक, यमक"],"correct":"स्वर, व्यंजन, विसर्ग"},{"q":"संधि में किसका मेल हो सकता है?","options":["वर्णों या शब्दांशों का","केवल वाक्यों का","केवल अनुच्छेदों का","केवल अंकों का"],"correct":"वर्णों या शब्दांशों का"},{"q":"संधि सीखने से क्या समझ आता है?","options":["शब्द-रचना","समय","चित्र","गणना"],"correct":"शब्द-रचना"},{"q":"संधि पहचानने के लिए क्या देखें?","options":["मेल से हुआ परिवर्तन","रंग","लंबाई","पृष्ठ"],"correct":"मेल से हुआ परिवर्तन"}]},{"id":"c8-hindi-v75-2","title":"अलंकार का परिचय","icon":"📝","content":"काव्य में भाषा को सुंदर और प्रभावशाली बनाने वाले विशेष प्रयोगों को अलंकार कहा जाता है। उपमा और रूपक परिचित उदाहरण हैं।","quiz":[{"q":"अलंकार का उद्देश्य?","options":["भाषा को प्रभावशाली बनाना","वाक्य हटाना","गणना करना","तारीख बताना"],"correct":"भाषा को प्रभावशाली बनाना"},{"q":"“सा/सी” से तुलना किसका संकेत हो सकती है?","options":["उपमा","रूपक","समास","विराम"],"correct":"उपमा"},{"q":"रूपक में क्या किया जाता है?","options":["एक को दूसरे के रूप में प्रस्तुत","केवल प्रश्न पूछा","गिनती की जाती","विराम लगाया"],"correct":"एक को दूसरे के रूप में प्रस्तुत"},{"q":"अलंकार किसमें अधिक मिलता है?","options":["काव्यात्मक भाषा में","गणितीय सूत्र में","पते में","तालिका में"],"correct":"काव्यात्मक भाषा में"},{"q":"अलंकार से भाषा में क्या आता है?","options":["सौंदर्य और प्रभाव","केवल संख्या","केवल समय","कोई परिवर्तन नहीं"],"correct":"सौंदर्य और प्रभाव"}]},{"id":"c8-english-v75-1","title":"Relative Clauses","icon":"🔤","content":"Relative clauses add information about a noun. Common relative words include who, which and that.","quiz":[{"q":"“The boy who won” uses “who” for a ___.","options":["person","place","number","time"],"correct":"person"},{"q":"“The book which I bought” uses “which” for a ___.","options":["thing","person only","time","verb"],"correct":"thing"},{"q":"Relative clauses add ___.","options":["information about a noun","numbers","punctuation only","a new tense"],"correct":"information about a noun"},{"q":"Which word can introduce a clause for people?","options":["who","where","when","because"],"correct":"who"},{"q":"Why use a relative clause?","options":["To connect extra information to a noun","To remove the noun","To change every verb","To add numbers"],"correct":"To connect extra information to a noun"}]},{"id":"c8-english-v75-2","title":"Reported Questions","icon":"🔤","content":"Reported questions tell someone what was asked. The word order usually changes to statement order.","quiz":[{"q":"“He asked where I lived” reports a ___.","options":["question","command","greeting","fact only"],"correct":"question"},{"q":"Reported question word order is usually like a ___.","options":["statement","direct question","title","list"],"correct":"statement"},{"q":"Which verb can introduce a question?","options":["asked","painted","ran","slept"],"correct":"asked"},{"q":"Reported questions may not keep the original ___.","options":["question word order","meaning","topic","noun"],"correct":"question word order"},{"q":"Why use reported questions?","options":["To tell what was asked","To remove meaning","To change topic","To add numbers"],"correct":"To tell what was asked"}]},{"id":"c8-math-v75-1","title":"रैखिक समीकरण","icon":"➗","content":"रैखिक समीकरण में अज्ञात संख्या पाने के लिए दोनों पक्षों पर समान क्रिया करके संतुलन बनाए रखा जाता है।","quiz":[{"q":"x + 5 = 12 में x?","options":["7","17","5","12"],"correct":"7"},{"q":"3x = 18 में x?","options":["6","9","15","3"],"correct":"6"},{"q":"x - 4 = 9 में x?","options":["13","5","9","4"],"correct":"13"},{"q":"समीकरण हल करते समय दोनों पक्षों पर?","options":["समान क्रिया","अलग क्रिया","कुछ नहीं","केवल बाएँ पर"],"correct":"समान क्रिया"},{"q":"2x + 1 = 9 में x?","options":["4","5","3","8"],"correct":"4"}]},{"id":"c8-math-v75-2","title":"प्रतिशत और लाभ-हानि","icon":"➗","content":"लाभ तब होता है जब विक्रय मूल्य लागत मूल्य से अधिक हो और हानि तब जब विक्रय मूल्य कम हो।","quiz":[{"q":"लागत 100, विक्रय 120: लाभ?","options":["20","10","120","220"],"correct":"20"},{"q":"लागत 200, विक्रय 180: हानि?","options":["20","10","180","380"],"correct":"20"},{"q":"लाभ = ?","options":["विक्रय - लागत","लागत - विक्रय","योग","गुणन"],"correct":"विक्रय - लागत"},{"q":"हानि कब होती है?","options":["विक्रय मूल्य कम हो","विक्रय मूल्य अधिक हो","दोनों बराबर हों","लागत शून्य हो"],"correct":"विक्रय मूल्य कम हो"},{"q":"लाभ प्रतिशत किसके आधार पर?","options":["लागत मूल्य","विक्रय मूल्य","समय","कुल संख्या"],"correct":"लागत मूल्य"}]},{"id":"c9-hindi-v75-1","title":"तत्सम और तद्भव शब्द","icon":"📝","content":"संस्कृत से लगभग उसी रूप में आए शब्द तत्सम कहलाते हैं; समय के साथ बदले रूप वाले शब्द तद्भव कहलाते हैं।","quiz":[{"q":"तत्सम शब्द किसे कहते हैं?","options":["संस्कृत से लगभग उसी रूप का शब्द","बदला लोक-रूप","विदेशी शब्द","संक्षिप्त शब्द"],"correct":"संस्कृत से लगभग उसी रूप का शब्द"},{"q":"तद्भव शब्द कैसे बनते हैं?","options":["समय के साथ रूप बदलने से","केवल अंग्रेज़ी से","केवल गणित से","बिना बदलाव"],"correct":"समय के साथ रूप बदलने से"},{"q":"“अग्नि” का तद्भव रूप?","options":["आग","अनल","अग्नि","ज्वाला"],"correct":"आग"},{"q":"पहचानने में क्या देखें?","options":["रूप और स्रोत","लंबाई","रंग","मात्रा"],"correct":"रूप और स्रोत"},{"q":"अध्ययन क्यों उपयोगी है?","options":["भाषा के विकास को समझने के लिए","चित्र बनाने के लिए","गणना के लिए","समय रोकने के लिए"],"correct":"भाषा के विकास को समझने के लिए"}]},{"id":"c9-hindi-v75-2","title":"विचार-लेखन","icon":"📝","content":"विचार-लेखन में अपना मत स्पष्ट करके उसके समर्थन में कारण, उदाहरण और निष्कर्ष दिए जाते हैं।","quiz":[{"q":"सबसे पहले क्या स्पष्ट होना चाहिए?","options":["मुख्य विचार","नाम","तारीख","चित्र"],"correct":"मुख्य विचार"},{"q":"कारण और उदाहरण क्यों?","options":["मत मजबूत करने के लिए","विषय बदलने के लिए","सजावट के लिए","उत्तर हटाने के लिए"],"correct":"मत मजबूत करने के लिए"},{"q":"निष्कर्ष क्या करता है?","options":["मुख्य बात समेटता है","नई बात शुरू करता है","केवल प्रश्न देता है","शीर्षक बदलता है"],"correct":"मुख्य बात समेटता है"},{"q":"अच्छा विचार-लेखन कैसा?","options":["तार्किक और स्पष्ट","बिना कारण","असंबंधित","अस्पष्ट"],"correct":"तार्किक और स्पष्ट"},{"q":"प्रमाण या उदाहरण का महत्व?","options":["विश्वसनीयता बढ़ती है","भाषा मिटती है","विषय बदलता है","कोई नहीं"],"correct":"विश्वसनीयता बढ़ती है"}]},{"id":"c9-english-v75-1","title":"Modal Verbs","icon":"🔤","content":"Modal verbs such as can, may, might, must and should express ability, possibility, permission or obligation.","quiz":[{"q":"“You must wear a helmet” expresses ___.","options":["obligation","ability","place","comparison"],"correct":"obligation"},{"q":"“She can swim” expresses ___.","options":["ability","permission only","past time","place"],"correct":"ability"},{"q":"“It might rain” expresses ___.","options":["possibility","obligation","ability","command"],"correct":"possibility"},{"q":"Which modal often gives advice?","options":["should","must","can","might"],"correct":"should"},{"q":"A modal is followed by the ___.","options":["base form of a verb","-ing form always","past participle always","noun only"],"correct":"base form of a verb"}]},{"id":"c9-english-v75-2","title":"First Conditional","icon":"🔤","content":"The first conditional describes a possible future condition and its likely result: if + present simple, will + base verb.","quiz":[{"q":"If it rains, we ___ stay home.","options":["will","would","are","were"],"correct":"will"},{"q":"The if-clause commonly uses ___.","options":["present simple","past perfect","future simple","present perfect only"],"correct":"present simple"},{"q":"The result clause often uses ___.","options":["will + base verb","past continuous","had + noun","is + noun"],"correct":"will + base verb"},{"q":"First conditional is mainly about ___.","options":["possible future situations","impossible past events","daily facts only","definitions"],"correct":"possible future situations"},{"q":"If you study, you ___ improve.","options":["will","would have","were","had"],"correct":"will"}]},{"id":"c9-math-v75-1","title":"बहुपद का परिचय","icon":"➗","content":"बहुपद चर और गुणांकों से बने पदों का योग होता है। 2x² + 3x - 5 एक उदाहरण है।","quiz":[{"q":"2x² + 3x - 5 की उच्चतम घात?","options":["2","3","5","1"],"correct":"2"},{"q":"3x में x की घात?","options":["1","3","0","2"],"correct":"1"},{"q":"बहुपद में पद क्या हैं?","options":["जोड़/घटाव से जुड़े भाग","केवल चर","केवल अंक","केवल चिन्ह"],"correct":"जोड़/घटाव से जुड़े भाग"},{"q":"x² + x में कितने पद?","options":["2","1","3","0"],"correct":"2"},{"q":"स्थिर पद क्या है?","options":["चर रहित पद","सबसे बड़ा पद","केवल चर","घात का नाम"],"correct":"चर रहित पद"}]},{"id":"c9-math-v75-2","title":"हीरोन के सूत्र का उपयोग","icon":"➗","content":"तीनों भुजाएँ ज्ञात हों तो अर्धपरिमाप s=(a+b+c)/2 लेकर हीरोन के सूत्र से त्रिभुज का क्षेत्रफल निकाला जा सकता है।","quiz":[{"q":"अर्धपरिमाप s?","options":["(a+b+c)/2","a+b+c","abc/2","a-b-c"],"correct":"(a+b+c)/2"},{"q":"हीरोन का सूत्र किसके लिए?","options":["त्रिभुज का क्षेत्रफल","वृत्त की परिधि","घन का आयतन","आयत का विकर्ण"],"correct":"त्रिभुज का क्षेत्रफल"},{"q":"तीनों भुजाएँ ज्ञात हों तो क्या निकाला जा सकता है?","options":["क्षेत्रफल","समय","तापमान","प्रतिशत"],"correct":"क्षेत्रफल"},{"q":"s में क्या शामिल है?","options":["तीनों भुजाओं का आधा योग","सबसे बड़ी भुजा","सबसे छोटी भुजा","दो भुजाओं का गुणन"],"correct":"तीनों भुजाओं का आधा योग"},{"q":"हीरोन सूत्र किस आकृति से जुड़ा है?","options":["त्रिभुज","वृत्त","वर्ग","घन"],"correct":"त्रिभुज"}]},{"id":"c10-hindi-v75-1","title":"औपचारिक लेखन की भाषा","icon":"📝","content":"औपचारिक लेखन में स्पष्ट, विनम्र और विषय-केंद्रित भाषा प्रयोग की जाती है। अनावश्यक बोलचाल से बचना चाहिए।","quiz":[{"q":"औपचारिक भाषा कैसी?","options":["स्पष्ट और विनम्र","बहुत अनौपचारिक","असंबंधित","बिना उद्देश्य"],"correct":"स्पष्ट और विनम्र"},{"q":"किससे बचना चाहिए?","options":["अनावश्यक बोलचाल","सटीक जानकारी","उचित संबोधन","विषय-केंद्रित भाषा"],"correct":"अनावश्यक बोलचाल"},{"q":"विषय-केंद्रित का अर्थ?","options":["मुख्य विषय पर बने रहना","हर बात लिखना","विषय बदलना","केवल प्रश्न पूछना"],"correct":"मुख्य विषय पर बने रहना"},{"q":"औपचारिक पत्र में संबोधन क्यों?","options":["प्राप्तकर्ता को उचित रूप से संबोधित करने के लिए","सजावट के लिए","तारीख के लिए","शीर्षक के लिए"],"correct":"प्राप्तकर्ता को उचित रूप से संबोधित करने के लिए"},{"q":"अच्छे औपचारिक लेखन में क्या जरूरी?","options":["क्रम और स्पष्टता","अफवाह","असंबंधित विवरण","बिना निष्कर्ष"],"correct":"क्रम और स्पष्टता"}]},{"id":"c10-hindi-v75-2","title":"काव्य में प्रतीक और बिंब","icon":"📝","content":"काव्य में प्रतीक किसी बड़े विचार का संकेत दे सकता है और बिंब शब्दों से मन में दृश्य या अनुभूति बना सकता है।","quiz":[{"q":"प्रतीक क्या कर सकता है?","options":["बड़े विचार का संकेत","केवल संख्या दिखाना","केवल समय बताना","केवल विराम देना"],"correct":"बड़े विचार का संकेत"},{"q":"बिंब मन में क्या बनाता है?","options":["दृश्य या अनुभूति","केवल गणना","केवल तारीख","केवल नाम"],"correct":"दृश्य या अनुभूति"},{"q":"प्रतीक का उपयोग क्यों?","options":["अर्थ को संकेतात्मक बनाने के लिए","विषय हटाने के लिए","शब्द गिनने के लिए","शीर्षक बदलने के लिए"],"correct":"अर्थ को संकेतात्मक बनाने के लिए"},{"q":"बिंब किससे उभर सकता है?","options":["शब्दों से बनी छवि या अनुभूति","केवल अंक","केवल तालिका","केवल पता"],"correct":"शब्दों से बनी छवि या अनुभूति"},{"q":"इन्हें समझने में क्या मदद करता है?","options":["संदर्भ और भाव","अक्षर गिनना","केवल विराम","केवल शीर्षक"],"correct":"संदर्भ और भाव"}]},{"id":"c10-english-v75-1","title":"Argumentative Writing","icon":"🔤","content":"Argumentative writing presents a clear claim and supports it with reasons and relevant evidence while considering the topic carefully.","quiz":[{"q":"What is a claim?","options":["The main position or point","A greeting","A question mark","A title only"],"correct":"The main position or point"},{"q":"What supports a claim?","options":["Reasons and evidence","Decoration","Random words","Only a heading"],"correct":"Reasons and evidence"},{"q":"Why consider an opposing view?","options":["To make the argument more balanced","To remove the claim","To avoid evidence","To change the subject"],"correct":"To make the argument more balanced"},{"q":"A strong argument should be ___.","options":["clear and supported","random and vague","only emotional","without reasons"],"correct":"clear and supported"},{"q":"What should a conclusion do?","options":["Reinforce the main position","Introduce an unrelated topic","Delete evidence","Ask new questions"],"correct":"Reinforce the main position"}]},{"id":"c10-english-v75-2","title":"Editing for Clarity","icon":"🔤","content":"Editing improves a draft by checking meaning, organization, grammar, word choice and unnecessary repetition.","quiz":[{"q":"Editing mainly improves a ___.","options":["draft","dictionary","number","map"],"correct":"draft"},{"q":"What should be removed when unnecessary?","options":["repetition","main ideas","evidence","clear examples"],"correct":"repetition"},{"q":"Which check helps sentence accuracy?","options":["grammar","page color","screen brightness","file size"],"correct":"grammar"},{"q":"Why revise organization?","options":["To make ideas easier to follow","To add random facts","To remove examples","To change every noun"],"correct":"To make ideas easier to follow"},{"q":"Good editing keeps the writer’s ___ clear.","options":["meaning","password","device","location"],"correct":"meaning"}]},{"id":"c10-math-v75-1","title":"द्विघात समीकरण का परिचय","icon":"➗","content":"द्विघात समीकरण में चर की उच्चतम घात 2 होती है। सामान्य रूप ax² + bx + c = 0 है, जहाँ a शून्य नहीं होता।","quiz":[{"q":"द्विघात में उच्चतम घात?","options":["2","1","3","0"],"correct":"2"},{"q":"ax² + bx + c = 0 में a कैसा?","options":["शून्य नहीं","हमेशा 0","हमेशा 1","ऋणात्मक ही"],"correct":"शून्य नहीं"},{"q":"x² - 5x + 6 = 0 में c?","options":["6","5","-5","1"],"correct":"6"},{"q":"“द्विघात” किससे जुड़ा है?","options":["दूसरी घात से","दो उत्तर हमेशा","दो चर से","दो जोड़ से"],"correct":"दूसरी घात से"},{"q":"x² = 9 के वास्तविक हल?","options":["3 और -3","9 और 0","3 और 9","-9 और 0"],"correct":"3 और -3"}]},{"id":"c10-math-v75-2","title":"निर्देशांक ज्यामिति में ढाल","icon":"➗","content":"दो बिंदुओं के लिए ढाल m=(y2-y1)/(x2-x1), जब x2≠x1। यह y में परिवर्तन की तुलना x के परिवर्तन से करती है।","quiz":[{"q":"ढाल का सूत्र?","options":["(y2-y1)/(x2-x1)","(x2-x1)/(y2-y1)","x+y","xy"],"correct":"(y2-y1)/(x2-x1)"},{"q":"(1,2) और (3,6) की ढाल?","options":["2","4","1","3"],"correct":"2"},{"q":"क्षैतिज रेखा की ढाल?","options":["0","1","-1","परिभाषित नहीं"],"correct":"0"},{"q":"ऊर्ध्वाधर रेखा की ढाल?","options":["परिभाषित नहीं","0","1","-1"],"correct":"परिभाषित नहीं"},{"q":"ढाल क्या बताती है?","options":["y परिवर्तन की तुलना x परिवर्तन से","क्षेत्रफल की तुलना","केवल दूरी","केवल कोण"],"correct":"y परिवर्तन की तुलना x परिवर्तन से"}]}];
 for(const l of v75Lessons){
  const m=l.id.match(/^c(\d+)-(hindi|english|math)-/); if(!m) continue;
  const c=m[1],sub=m[2];
  if(STUDY_DATA[c]?.subjects?.[sub] && !STUDY_DATA[c].subjects[sub].lessons.some(x=>x.id===l.id)) STUDY_DATA[c].subjects[sub].lessons.push(l);
 }
 window.PATHSHALA_V75_HIGH_STUDY={lessonsAdded:v75Lessons.length,questionsAdded:v75Lessons.reduce((n,l)=>n+l.quiz.length,0)};
})();

